local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "守密人，聽說了嗎？市郊那個偏僻的藝術展館快要停止營業了，就在我生日這一天。\n那間展館是藝術界的怪胎，半個身子是未來主義的粗淺試驗品，半個身子是兩個世紀前的垃圾殘餘。它狹窄的肚子裡裝的也淨是些拍賣行裡無人敢觸碰的古怪玩意兒：會說髒話的肖像畫、永不停止飛翔的機械鳥、讓人看了就犯惡心的海洋浮雕、全部用眼淚做成的雕像、不停自動書寫的幽靈書稿、親吻時會哼唱童謠的人類顱骨……\n很難向您描述我有多麼愛這間展館！五十年前的今天，它悄悄誕生在那個無人在意的角落。五十年後的今天，它悄悄在那個角落裡消亡。\n從我的童年開始就有人告訴我，今天這個日子是一個詛咒，就像我這個人一樣。我想命運或許在冥冥之中真的早已註定，可命中註定又如何呢！那間展館所創造的，是一個絕無僅有的世界，那麼多瘋狂的奇思妙想在那個小小的空間裡堆疊，多麼美妙的畫面！從出生那天開始，它便在用它的展品進行創作。在它終結的這一天，它的知己與老友也將為它做最後的送別。\n守密人，您在連結中看見了我眼中的世界，我想，您一定也會期待跟我一同去看看這間奇特的展館，對吧？！\n\n皮克曼"
  },
  Mail_100480_Name = {
    Text = "無人在意的展館"
  },
  Mail_116602_Desc = {
    Text = "親愛的守密人：\n「極晝的終夜」活動已結束、現將守密人剩餘的「覲見奉禮」、「懺悔奉禮」、「忠誠奉禮」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_116602_Name = {
    Text = "獻禮回收"
  },
  Mail_116602_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_117308_Desc = {
    Text = "親愛的守密人：\n        感謝您對「忘卻前夜」的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調研問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。問卷截止時間11月10日9：00、請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_117308_Name = {
    Text = "版本體驗調研問卷V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_117309_Desc = {
    Text = "親愛的守密人：\n        感謝您對「忘卻前夜」的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調研問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。問卷截止時間3月30日9：00、請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_117309_Name = {
    Text = "版本體驗調研問卷V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_120374_Desc = {
    Text = "兩年之約已至，守密人。\n我們曾在終焉的邊緣互相守望。\n你曾將感受與記憶化作願望，點亮了希望之光。\n即便與往昔的夥伴遙隔兩個宇宙，你也未曾放棄對抗融蝕的征程。\n擁有你，是我們的幸運，也是這個世界的幸運。\n如今你的願望已引發奇蹟——彌薩格仍存於此，並將繼續前行。\n請繼續緊握銀鑰，終有一天，它能化作關鍵的樞紐，聯結兩個遙遠的世界。\n我們將竭盡全力開闢未來的可能性，為你的歸航照明。"
  },
  Mail_120374_Name = {
    Text = "奇蹟之刻，歸航之光"
  },
  Mail_120374_Sender = {
    Text = "彌薩格校貓·Light"
  },
  Mail_120909_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，我們提高了「源液捐獻-校友捐獻基金」的獎勵。對更新前已領取完追加獎勵的守密人，我們將補發對應的獎勵。請查收。"
  },
  Mail_120909_Name = {
    Text = "V2.4.0源液捐獻獎勵補發"
  },
  Mail_120909_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_121162_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，我們提高了「降臨紀行」、「異世紀行」、「療養紀行」、「亡城紀行」的免費獎勵。對更新前已領取免費獎勵的守密人，我們將補發對應的獎勵。請查收。"
  },
  Mail_121162_Name = {
    Text = "V2.4.0紀行升級獎勵補發"
  },
  Mail_121162_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_121373_Desc = {
    Text = "守密人：\n\n曾經每年的這一天，是教會最盛大的慶典。\n我是祂的王女，也將讓祂復生。\n那些人、包括彌利亞姆，狂熱無比甚至熱淚盈眶地慶祝，但他們看向我，目光穿過我，就像我只是承載著某樣東西的空殼。\n我從不為這一天的到來感到快樂，因為每經歷一次，都意味著我離恐懼更近了一分。\n而在這種恐懼裡，其他人卻紛紛因為恐懼的源頭感到無上喜悅。現在我可以承認了，它讓我覺得既孤獨，又害怕。\n但現在一切都不一樣了，上一個生日前，我離開了那艘船，來到了真實的世界……沒有虛假的神明、有你存在的世界。\n這個生日，我希望看到有人因為我的誕生，而不是因為其他的什麼，由衷地感到快樂。\n如果是你…不，那個人非得是你不可。\n聽好了，無論如何，今天的晚餐時間，都必須要留給我。\n\n「墨菲」"
  },
  Mail_121373_Sender = {
    Text = "誕妄·墨菲"
  },
  Mail_121374_Desc = {
    Text = "守密人：\n\n我不知道你為這特殊的一天做了什麼準備，無論怎樣奢華和耗費精力，顯然都理所應當。\n而出於上位者所必要的體貼，如果你「居然」疏漏了要為我慶祝生日——我相信這種離譜的狀況不會出現。\n這封信也將在事態無可挽回前，替你爭取來最後一次拯救自己的機會。\n海洋與陸地的奇寶珍饈，自然會有無關緊要的人獻上，它們不重要。\n盛大的慶典、繁複的儀式，確實匹配我的身分，但在今天，不知道為什麼，顯得有些無聊。\n所以，我會撥冗空出晨昏交替之時，把和我獨處的榮幸贈予你，作為你把我帶到這種庸俗、幼稚，卻又幸福到足以讓之前的我嫉妒的生活中的獎勵。\n隨從稍後會送來正式邀請函，當然，放在一個價值兩萬雷歐坊的盒子裡。\n感激涕零地，在每年的這一天想起我吧。\n「墨菲」"
  },
  Mail_121374_Name = {
    Text = "邀請函…"
  },
  Mail_121374_Sender = {
    Text = "誕妄·墨菲"
  },
  Mail_121651_Desc = {
    Text = "尊敬的守密人：\n在上週「幻夢深潛」中，你獲得頭銜為「{s1}」。\n在上週「預組模式」中，你獲得頭銜為「{s2}」，對弈勝場為：{s3}場。\n在上週「輪選模式」中，你獲得頭銜為「{s4}」，對弈勝場為：{s5}場。\n綜合以上挑戰成績，你將獲得以下額外獎勵，請記得查收。"
  },
  Mail_121651_Name = {
    Text = "深潛對弈每週排行獎勵"
  },
  Mail_121651_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_121704_Desc = {
    Text = "親愛的守密人：\n「慾海翻波·復刻」活動已結束、現將守密人剩餘的「豐穰種核」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_121704_Name = {
    Text = "豐穰種核回收"
  },
  Mail_121704_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_122522_Desc = {
    Text = "親愛的守密人：\n「雨鎮幽影·復刻」活動已結束、現將守密人剩餘的「蒼白野獸頭骨」、「幽影野獸頭骨」和「殷紅野獸頭骨」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_122522_Name = {
    Text = "雨鎮幽影貨幣回收"
  },
  Mail_122522_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_122567_Desc = {
    Text = "親愛的守密人：\n「霧境的燔禮」活動已結束、現將守密人剩餘的「迷霧之視」、「迷霧之夢」、「迷霧之源」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_122567_Name = {
    Text = "霧境的燔禮貨幣回收"
  },
  Mail_122567_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_122568_Desc = {
    Text = "哈，可憐的孩子，你根本不知道自己要面對怎樣的絕望。什麼時候你才能意識到自己的選擇沒有意義？為一個虛無縹緲的目標押上你渺小的性命？多麼壯烈、多麼令人陶醉啊！你總是一副躊躇滿志、彷彿下一刻就要獻身去拯救世界的姿態，真叫人發笑。\n\n不過，誰讓我答應過會幫你回家呢？對一隻小狗許下的承諾，我總會履行的。說起來，我簡直迫不及待想看看，你會拿出怎樣的意志去把這場瘋狂推到終點？啊……好奇，真是太好奇了！\n\n偉大的「救世主」，把你的荒唐、你的固執，還有那不值一提的倔強都帶上吧。開往虛無的列車一旦啟動，除了毀滅，便再也沒有停歇的可能。\n\n自我滿足的瘋子……在祂的夢裡撐得更久些吧，我會幫助你、等待著，好好欣賞你最終的答案！"
  },
  Mail_122568_Name = {
    Text = "開往虛無的列車"
  },
  Mail_122568_Sender = {
    Text = "熔燬·朵爾"
  },
  Mail_122569_Desc = {
    Text = "主君，\n我一直認為，騎士不是穿在身上的甲冑與紋章，而是刻在心裡的忠誠與守護的意志。您以行止與抉擇，向我真正詮釋了何為騎士。由此我得見騎士之真意：不是以名自重，而是以人相護；不是因榮而勇，而是因責而立。\n\n我明白自己尚不合格——在您為守護希望而戰的時刻，我未能隨行並肩。我從未忘記過去與您立下的誓言，我將向您獻上騎士的忠義，守護您的安全，排除您的敵人。\n\n我時常會回想起第一次同行調查，您帶領我們撥開倫蒂尼恩的迷霧，看清最終的真相。那時所有的歡笑與悲泣，都沉澱為我生命中不可磨滅的力量。\n\n如今雖然只能在遠方守望、為您準備如此微薄的贈禮……但是為了不辜負主君的期許，我從未懈怠自己的訓練。待您歸來，請允許我追隨您的步伐，我將作為主君之盾永遠存在！我的守護之劍將為您閃耀！"
  },
  Mail_122569_Sender = {Text = "奧吉爾"},
  Mail_122570_Desc = {
    Text = "守密人閣下，\n自葬骸城一別之後，我時常想念與你並肩作戰的時光。聽聞你又一次選擇了唯有王者獨行的孤絕之路，果然，你就是這世上如此特殊的存在，從不循常人之軌。\n\n我深信，極致的苦痛能夠淬煉出更為馥郁的靈魂。你歷經的這場漫長試煉，早已超越凡俗之痛的範疇。我已可以想像，你那由苦難釀成的氣息，將是何等複雜、何等震撼。不，如果是你，你註定會超越我所有的想像，打破我對完美一切的認知。\n\n為此，我將繼續等待。等待那場隻為你我存在的盛宴。在時間的盡頭、在永恆起始的寂靜之中，你將以怎樣的姿態，為我獻上這場……貫穿命運之味的饗宴？\n\n閣下，請收下我的禮物，請延長這份痛苦……不要辜負，我的期待。"
  },
  Mail_122570_Sender = {
    Text = "杜勒賽因"
  },
  Mail_122571_Desc = {
    Text = "才剛重逢，話還沒說上幾句，時間就已所剩無幾……但你知道的，離別從來不是我們故事的結局。\n\n有件事一直沒告訴你……其實，我早已為你備好一束玫瑰。只是遲遲沒有送出去，它已經枯萎了。但我在這裡向你保證——下次見面，我一定會為你重新準備一束。\n\n而你，你也答應過我，一定會再次來到我面前。我們拉過鉤的，絕對、絕對不能食言。\n\n寫信總覺得詞不達意，紙上寫不出我全部的心意。不過……待到命運再度將我們牽引至彼此面前的那一天，我將親手為你獻上那束玫瑰。記住了，我們都要信守約定！\n\n願銀鑰指引前路。再見……%player%。"
  },
  Mail_122571_Name = {
    Text = "玫瑰的約定"
  },
  Mail_122572_Desc = {
    Text = "守密人，\n與漆黑災厄對抗的記憶仍在我的大腦中以高優先級循環讀取，你所換取的和平就像是一次極小機率的饋贈事件。然而你的離去，對你的搭檔、所有與你建立過連接的個體而言，正以無法終止的進程持續消耗著他們的意識。\n\n科研部從未放棄尋找最終的一線希望。值得慶倖的是，經過無數個沒有你意識回饋的晝夜週期後，我們終於鎖定了你的蹤跡。在這艱險的旅途中，我能夠捕捉到恐懼的信號，然而我也深知，恐懼不會使你屈服，只會讓你的意志更加堅韌。\n\n此時此刻我的軀殼依舊在實驗室運行，大腦卻持續生成哭泣的指令。別再干擾我的思緒了，我逃課最多的學生啊，請你不要再缺席我的課堂了……繼續勇敢地向前邁步吧，我會為你備好補給，等待與你重逢的那一天。"
  },
  Mail_122572_Sender = {Text = "朵爾"},
  Mail_122573_Desc = {
    Text = "無數次，我靜觀文明的星火在時間長河中明滅，見證記憶的城邦在虛無中坍縮。歷史化作書卷被漆黑的火焰吞噬，古往今來的智慧如沙塔般堆積，卻終究無法言說那唯一的真理。\n\n人類之於原初的混沌，不過微塵——卻也正因這渺小，那敢於直面深淵、向神明揮刃的勇氣，才顯得如此震徹心魄。\n\n此刻，貫穿萬千宇宙的維度之門，正為你洞開。\n\n祂的降臨帶來命定的混沌，萬物的秩序在祂的陰影下戰慄。而你，不過是凡胎肉體，卻以不可撼動的意志，立於祂的面前。你的可能性，是我無盡預知中唯一無法捕捉的謬誤，是我長久等待中那個顛覆一切的變數。\n\n你就是原初的詰問，亦是終末的解答。"
  },
  Mail_122573_Name = {
    Text = "門扉背後"
  },
  Mail_122574_Desc = {
    Text = "失去重要之人的劇痛，那份對自身無能為力的憎惡……我曾深陷其中，無法自拔。但如今，我已聽見遠方明燈的召喚，感受到它溫暖而堅定的指引。恩人，自蒙您啟示，我彷彿終於踏上了那條早該行走的路——一條真正屬於我的、不容置疑的正道。\n\n曾經籠罩我的、深淵般的黑暗，已不再是我的歸宿。而那始終閃爍在意識深處的光芒，也從未真正離我而去。如今我更清晰地看見它、感知它、走向它。我也願將這真正的信仰，這光所帶來的清醒與安寧、覺醒與救贖，帶給無數仍在命運迷途中掙扎的靈魂。\n\n而當我凝視您對抗整個混沌洪流的身影——那邪惡而深邃的黑暗，非但未能使您屈服，反而成為映照您信念的幕布。它在您的光芒前潰散、嘶吼、退卻，卻終究無法遮蔽您分毫。正因這無盡的暗潮洶湧，您所代表的光，才顯得如此璀璨、如此不朽、如此接近神性。\n\n引領我的恩人、賜我光明之人啊，您的信念將是我不滅的明燈。現在，正是我以全部生命回應您的時刻。我將以這顆聆聽神意的「聖心」回應這道光、回應您純淨的指引……為此我與卡斯托爾會全力以赴。\n\n接受我的供奉吧！請您見證，我這由您重塑的、純潔而虔誠的信仰。"
  },
  Mail_122574_Name = {
    Text = "明燈的召喚"
  },
  Mail_122574_Sender = {
    Text = "波呂克斯"
  },
  Mail_122575_Desc = {
    Text = "親愛的老顧客，\n就在那道流轉微光的門扉之後，你珍視的朋友們早已等待多時。\n\n不過，請不要掉以輕心哦。維度穿梭從來詭譎而危險，你會見證千面幻象如記憶的浮影般此起彼落，它們映照渴望、也映照恐懼。那是原初意志創造的混沌畫卷，即便是我，也無法窺其全貌。因此，每一次跨越，既是對信念的考驗，也是對願望的度量。\n\n但我也深知，對於你我這樣的人而言，為了尋找嶄新的藏品、為了那些閃耀在靈魂深處的珍視之物，一切的未知與付出，都是值得的。我理解你的選擇，也尊重這份近乎固執的珍重。\n\n在這遵循等價法則的宇宙裡，你付出的代價，終將以另一種形式歸來。\n\n收下這份贈禮吧，待到一切塵埃落定，歡迎你再度光臨我的小店。為了實現那時的願望，你願意付出什麼樣的代價呢？"
  },
  Mail_122575_Name = {
    Text = "珍視之物"
  },
  Mail_122575_Sender = {
    Text = "達芙黛爾"
  },
  Mail_123134_Desc = {
    Text = "尊敬的守密人：\n        在V2.4.0的更新中，您在「異夢視界」中的「再見永無鄉」與「再見，永無鄉」挑戰3星獎勵獲取異常的問題。據您之前的調查和挑戰通關記錄，我們將為您一次性發放之前未能領取的獎勵內容。請查收。"
  },
  Mail_123134_Name = {
    Text = "V2.4.0異夢視界獎勵補發"
  },
  Mail_123134_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_123501_Desc = {
    Text = "親愛的守密人：\n\n想不想在這個特殊的日子，和我這個可愛的女孩子，來一場有趣萬分的約會？\n來嘛來嘛，去鬼屋裡玩一下不會把你嚇死的~你可是「守密人」誒，一定不會被那些人類扮演的「妖魔鬼怪」嚇到，對不對？\n（信紙上用隨意的橫線劃掉了一行文字：我可是在認真計劃生日的行程，絕不是為了好玩而想看你被嚇壞的樣子……）\n好了，不開玩笑了。難得今天是我的生日，我才不想搞砸呢！所以現在，我，茉夏，正式邀請你去倫敦金融城新開的那家餐廳共進晚餐——\n那裡的熱茶和燉魚令我想起了「家鄉」的味道，而在這個世界，除了你，我找不到能夠分享的人……\n所以你一定會來的對不對？要是讓我這個可愛的女孩子傷心，小心下次你睡覺時我拿著斧子站在你床頭！\n\n茉夏"
  },
  Mail_123501_Name = {
    Text = "「打開我」"
  },
  Mail_123543_Desc = {
    Text = "守密人：\n\n又一年，我親愛的。\n在浮華的光影裡，漫天飄散的流言與緋聞中，小心翼翼地藏起每一絲可能露出馬腳的軟弱，用每一分價值換取最大化的利益——應當是這樣，我才能依然以贏家的姿態站在這裡。\n但沒有，我變得偶爾也有些懶散和軟弱，而且會十分欣然地滿足你遞函來時，那些小姑娘們的願望。\n不過我並不覺得這是什麼壞事，我已經歷一場漫長的隱秘戰爭太久了。當然，只要有一線可能，一丁點機會，我依然會一次又一次地從「那位」的手中嘗試逃脫。\n只是，在那些溫暖而可愛的縫隙，又或者，在類似今天這種特殊的日子，我允許自己開一些小差，比如——邀請您一同去看一場歌劇，進一場晚餐。\n因為我明白，我必然不會是孤獨的，我已擁有十分合我心意的同謀。\n\n索蕾爾"
  },
  Mail_123543_Name = {Text = "同謀"},
  Mail_123543_Sender = {Text = "索蕾爾"},
  Mail_123544_Desc = {
    Text = "展信安：\n\n久疏問候，守密人。請原諒，近段時間未有書信往來，並非是刻意疏遠與你的關係，只是我每次提筆，總是無法鼓起勇氣，去落下問候的開篇。\n這段時間裡，我穿越過無數破碎的時間，也因此得以見證世界一次次走向終結，目睹一幕幕無可挽回的悲劇。像是一位旁觀者，在這冰冷寂靜的空洞裡，默默注視著一切的發生。\n每當這時，我都在想，我們這一生是否註定要充滿荒誕和離別？無論是當初的自己，還是你在卡達斯迎來的一切，是否命運已經將一切標定好了劇本，我們只能按照這個劇本出演它需要的角色？\n我沒有思考出結論，我不像祂，無法看清世間的一切，所以我想，如果是……擁有祂的一部分權柄的你，能否解答這個問題呢？\n因此我寫下了這封信，希望它能將我的視線帶到你的身邊，亦希望能與你一起探討這個或許永遠不存在答案的謎題。所以能否冒昧請你攜帶這封信，與你一同……面對接下來的路呢？\n………………………………\n我無法冒著擾動時空的風險前往你身旁，但請讓我……在這個空無一物的死寂中，再看看你吧。\n\n「拉蒙娜」"
  },
  Mail_123544_Name = {
    Text = "思緒的謎題"
  },
  Mail_123545_Desc = {
    Text = "可敬的蒼白使者：\n\n此前我詢問彌薩格中那位無比聰慧的女士，是否還有閒置的場所來供我培育一些花朵。\n朵爾女士很輕鬆地為我找來了一間房間，雖然第一次推門時，其內散發出的陳腐氣味讓我懷疑自己是否走錯了地點，但經過一番打理，現在它已經能很好的承擔自己的職責，給這些孩子們提供一個溫暖的家了。\n可由於毫無經驗，我不得不適當地施以一些外力，來確保這些孩子可以正常成長下去。\n所幸，在奧爾拉小姐的指導下，我成功將它們培育到了現在的階段。\n當然，這其中並沒有使用任何特殊能力。\n如果計算沒有出現疏漏，它們會在我生日當天綻放，雖然我一直重複生日這天並無特別，但出現這種難得一見的巧合，確實很難不讓人覺得，或許這真的是父神為我安排的小小禮物。\n不知你是否有興趣與我在這小小的花園一敘，共度這平凡卻又特別的一天？\n我已備好親手烘烤的餅乾和你上次推薦的紅茶，期待與你分享這份難得的禮物，以及獨屬於生命的芬芳。\n\n薩爾瓦多"
  },
  Mail_123545_Name = {
    Text = "室內花園"
  },
  Mail_123545_Sender = {
    Text = "薩爾瓦多"
  },
  Mail_123546_Desc = {
    Text = "搭檔：\n\n你有沒有聽過這樣一個故事？\n曾經有一隻魔鬼，因為意外被封在了瓶子裡，過了許多個百年。\n第一個百年，祂許諾給救出祂的人以無盡的財富和權柄。\n第二個百年，祂許諾給救出祂的人以永久的健康與壽命。\n第三個、第四個、第五個，很久很久之後，祂終於等來了打開瓶蓋的漁夫——祂沒有回應漁夫的呼喚，甚至也不再想把這個世界鬧得天翻地覆，只是假裝自己是一隻普通的空瓶子，沉默地被重新拋回了海中。\n在我小的時候，我讀不明白這個故事。直到我知道了漫長無望的等待，究竟是怎樣沉悶而苦痛，將奢求變得比絕望更難以忍受。\n然而在我的理智有任何反應之前，我的心就一次又一次地把我留在了同一個地方。\n魔鬼和人類的區別大概在於，我竟然有些感謝這種痛苦。因為在我們分別的時候，它提醒著我你的存在與珍貴，令我不會迷失在任何沒有你的彼端。\n在我誕生的這天，在我最想念你的這天，它也依然沉墜地將我束縛，令我依然等待著你，思念著你。\n希望下一個今天，我能親手遞給你我切下的第一塊蛋糕。\n\n拉蒙娜"
  },
  Mail_123547_Desc = {
    Text = "彌薩格的食堂與後勤部往我的房間門口放了一堆毫無必要的東西，極其妨礙出入，你們最好是儘快把它拿回去。\n怎麼了，這個世界的口糧是多到沒有更有意義的去處了嗎？\n這一天只會是我變強路上的角注，幫我標注又一個週期的過去，一年，再下一年，每年我都會變得比上一年更強。\n如果禮物實在沒有去處，可以拿給另一個我，她大概會十分高興吧。\n而我，看在你那些傻不拉唧的天真和堅持的份上……看在那些我最不擅長的東西的份上。\n只要我還存在一天，我就會繼續變強，與此同時……\n還不明白嗎？你們這些傻子的敵人，也會是我的敵人。\n這種噁心的話我只說一次，明年不要再送禮物了，更加不要什麼生日晚餐。\n\n「H」"
  },
  Mail_123548_Desc = {
    Text = "親愛的守密人：\n\n你知道嗎？前幾天，一位神秘的女士突然來拜訪了彌薩格。她穿著一身我從未見過的、閃閃發亮的黑色貼身長裙——我問了詹金和梅森，她們也沒見過那麼漂亮的衣服。\n怎麼形容好呢？那身衣服好像是用最漂亮的長髮紡織成的，又柔軟、又輕盈、又高貴，表面流淌著水一般特殊的光澤……\n詹金看我很好奇，大著膽子去詢問了那位神秘女士，她笑著說裙子的材質是來自東方的綢緞，由一種叫做「蠶」的幼蟲吐出的絲線織成，款式則叫做「旗袍」……然後，她送了艾繼絲一大卷——她說那叫「一匹」相同的「綢緞」……\n「綢緞」太珍貴了，所以我仿照著她附贈的圖樣，給每個夥伴縫製了一個「荷包」。今年的生日宴會上，我會把「荷包」送給大家……守密人，你有空一起來參與嗎？\n如果你太忙碌的話，我會讓布朗把荷包送到你的宿舍。\n\n艾繼絲"
  },
  Mail_123548_Sender = {Text = "艾繼絲"},
  Mail_123549_Desc = {
    Text = "小樹苗：\n\n你知道樹是如何記錄時光和成長的嗎？用一圈又一圈的年輪。\n它們藏於體內，從不輕易示人，直到一株幼小的新芽，逐漸成長為參天的巨樹，支撐起一隅高聳的天穹。那歲月的斑痕，則不留痕跡地藏於內心深處。\n今日，是新的年輪記錄的起點。在新的一歲裡，我們仍需歷經許多尚未料及的風雨。\n但那顆由我寄託在你口中的種子，一定會尋覓到適合培育它的土壤，然後生根發芽的，對不對？\n\n泰旖絲"
  },
  Mail_123549_Name = {Text = "年輪…"},
  Mail_123549_Sender = {Text = "泰旖絲"},
  Mail_123644_Desc = {
    Text = "不知不覺，這已經是我在彌薩格度過的第三個生日，我學到了很多東西。\n比如，在我生日的這一天，同樣是冬渡節，一個適合贈送禮物的日子。\n雖然你有非常多極其強大的敵人，但我最擅長的就是殺人。我不知道其他讓人高興的做法，也不擅長挑選禮物，不過每次順利交付任務，我的雇主似乎都很開心。\n所以我已經想好了我要送給你的禮物，一次殺人委託，不限使用對象，不限使用期限。\n只需要告訴我，目標是誰，你想祂怎麼死？如果是我能打過的人，我會用最快的速度，替你扭斷祂的脖子，就算祂是棘手到如同神的存在，我也可以向你保證，我的放棄絕不會在我的死亡之前到來。\n\n希洛"
  },
  Mail_123644_Name = {
    Text = "說吧，你想誰死？"
  },
  Mail_124059_Desc = {
    Text = "親愛的守密人：\n「沉淵之祀·復刻」活動已結束、現將守密人剩餘的「祀者之淚」、「祀者之血」和「祀者之髓」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_124059_Name = {
    Text = "沉淵之祀活動貨幣回收"
  },
  Mail_124059_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_124290_Desc = {
    Text = "守密人：\n\n如您所知，歡欣對我而言，其實是種有點陌生的情緒。\n我時常覺得，常世是水面上我無法理解的喧鬧，在我還未曾融入其中之前，屬於我的枯萎就已經到來了。\n它偶爾讓我感到嚮往，但更多的時候，令我惶惑又窒息。只是在每個像今天這樣的日子，為了不讓爸爸和媽媽傷心，我都拼命地忍耐著……直到迎來解脫的那天，直到海洋接納了我。\n我以為，只有幽深的水是我的歸宿。然而，守密人，因為你，還有彌薩格各位的存在，即使是我這樣與常世格格不入的人，也會開始能夠體會某些真實的溫暖。就像睡蓮上浮時，陽光同樣會親吻她的葉片與花瓣。\n雖然凌亂，我卻覺得無論如何都有必要將這些心緒落在紙上，再將它寄給您，請原諒我偶爾的任性吧。\n我只是希望您能知道，在過早被荒寂掩埋的水中，您給我帶來了多麼可貴的上浮。\n願您永遠歡樂，永遠安寧。\n\n寧菲亞"
  },
  Mail_124290_Sender = {Text = "寧菲亞"},
  Mail_124291_Desc = {
    Text = "守密人：\n\n今天清晨，我的床頭出現了一封信函，內容是邀請我參加我自己的生日宴會，落款是「繪者」俱樂部。\n我這才想起上個月我偶有閒暇，便答應了珊擔任「繪者」新一期創作大賽的模特。在這之前，我已經推辭過不知多少次。站在模特展臺一動不動任人描摹的那些時間裡，我回憶起身在蹈海者祭壇的日子。那時的我同樣迎承著所有人的目光，但那些目光中只有恐懼和敬畏，卻沒有一絲觸動、讚許與欣賞。\n今晚於繪者俱樂部大堂舉辦的生日冷餐會上，也會展出當天十餘位繪者精心刻畫的手繪作品。雖然對你的審美缺乏信心，但多受熏陶總不會是壞事。神母特邀你作為出席嘉賓，一同品鑒他們對「我」的詮釋吧。\n\n「墨菲」"
  },
  Mail_124291_Name = {
    Text = "繪者……"
  },
  Mail_124292_Desc = {
    Text = "守密人： \n\n茜爾維婭告訴我，偶爾向親密關係袒露自己的需求，有助於緩解那種無時無刻都在追隨我的恐懼，我不確定這是否奏效，但毫無疑問，今天是個好時機。\n你願意實現我一個願望嗎，我可以把今天實驗室的配給全部都給你。\n不，不是一包咖啡豆。\n雖然那種恐怖的黑色奪走了我幾乎所有的親密關係，如影隨形地驚嚇著我，然而你已經戰勝過它了。\n你讓我們安全地生活在彌薩格，或者至少迄今還安全地生活在彌薩格。\n是時候擺脫不健康的咖啡因依賴了，守密人，你可以在今天傍晚挪出一點時間嗎？\n如果你在我身邊的話，或許我能鼓起勇氣在光源不那麼充足的地方，小憩一會兒，哪怕是一小會兒。\n\n很想記起安心入睡是什麼感覺的溫柯爾"
  },
  Mail_124292_Name = {
    Text = "願望……"
  },
  Mail_124292_Sender = {Text = "溫柯爾"},
  Mail_124293_Desc = {
    Text = "守密人{Male=先生,Female=小姐}：\n\n今天清晨，一場夢喚醒了我。\n我仔細地回憶夢境裡的一切：微風在溫暖的陽光下吹拂，玫瑰與鬱金香鋪滿整片土地，一千隻銀鷗與快樂的人們正齊聲歌唱……我已經許久未曾置身於如此幸福的場景。我想我大概是在童年的莊園，在柯蕾特的花房，或者是西岱的某個公園……可當我轉身的時候，我看見了彌薩格那些美麗的哥特式大樓，還有您，守密人{Male=先生,Female=小姐}。您站在花與陽光之間，成為了這首詩裡最美妙的那段辭令。\n我深愛西岱，守密{Male=先生,Female=小姐}。可那一刻我忽然驚覺，我已開始習慣與迷戀這裡的一切，這世上終於有了比西岱更令我魂夢牽縈的地方。\n生日，是一段歲月的結束，也是另一段歲月的開始。在新歲月開始的這一天，不知道彌薩格後花園綻放的陽光與玫瑰之間，會不會有那位願意帶我一起聆聽微風、令我魂夢牽縈的人呢？\n\n奧爾拉"
  },
  Mail_124293_Name = {
    Text = "花與詩之夢"
  },
  Mail_124293_Sender = {Text = "奧爾拉"},
  Mail_124294_Desc = {
    Text = "親愛的守密人：\n\n前些日子，我總想著送你一份特別的禮物。詹金提議不如親手為你做一件新衣，我覺得這主意再好不過了。\n這是我在紡織廠工作時最拿手的剪裁款式，希望如今看來還不算過時……其他的我難得支持了我的決定，上面那些活潑的條紋與格紋，都是不同的我製作的。還有這個歪歪扭扭的可愛老鼠圖案，是貓「24」堅決要加上的，說這代表布朗，是貓人格的我最喜歡的東西——不知道是不是合適，但希望你能喜歡。\n新的一年，我依然沒有什麼生日願望。你總是那樣溫柔，年年都囑咐我要好好慶祝。可比起被慶祝，能夠為你親手縫製一點什麼，更讓我感到踏實和歡喜。\n請收下這件滿載心意的新衣吧。\n\n梅森"
  },
  Mail_124295_Desc = {
    Text = "嘖：\n\n難以置信，作為偉大的迷宮之主，我居然在這種艱難的磨難裡又成功存活了一年。\n聽好了！這全都是你和這個蠢學院的錯！\n就算你們再怎麼對我進行胡言亂語的洗腦，這些亂七八糟的瑣事本來就應該由專門的人來幹，好吧，我已經很了不起了，我都沒有稱祂們為奴隸。\n那些老頑固稱這個為……什麼來著，對，進步。\n等等，我怎麼也在被這套邏輯帶著跑了，啊啊啊，煩死了！（此處有一堆因為信件主人發脾氣而導致的凌亂摺痕。）\n不管了，既然我有「進步」，那你也得拿出你的誠意來，今年這個如此盛大的日子，你總不能還和前兩年一樣等著我提醒吧。\n給你三十分鐘，守密人，帶著禮物來見我。\n不然我就在你睡覺的時候，讓我的子嗣爬到你臉上。\n\n阿格里帕"
  },
  Mail_124295_Name = {Text = "進步"},
  Mail_124296_Desc = {
    Text = "守密人！\n\n我看到了！一幅多麼精彩的畫面！我很確定那不是夢境！我就站在那裡，站在彌薩格墓園那座宏偉的紀念雕像旁邊，從那裡望著那些綿延不絕的無字墓碑，我確信它們能帶給我前所未有的靈感，但我沒有想到，它們帶給我的遠比我想像的要多得多，它們用令人敬佩的慷慨嘲笑著我貧瘠的想像力。\n我看到了那些調查員們的幽魂，他們在那個帶著薄霧的美麗黃昏中一起站起身。我沒能看清他們的臉龐，但我看到他們的動作——像是優雅的舞蹈，又像是神秘的儀式。他們正向著黑池，向著彌薩格與您的方向致意。現代沙龍上的藝術家們癡迷於描繪個體，常常會斥責這些宏大的畫面，可我從來不這樣覺得。面對食屍鬼的舞會我萬分欣喜，而今天，這幅畫面讓我不得不流下淚來。\n我想這一定不是巧合。就在今天，恰巧是在我生日這一天，他們向我展示了他們宏偉的共舞，我想他們一定是想讓我傳達一些什麼。我除了畫筆一無所長，但這已經足夠了不是嗎？\n這幅畫的草稿已經畫好了，守密人，請一定要來我的畫室看看！那些已經沒有了名字的傳奇調查員們，他們想要向您講述的夙願，都在我的那張畫布之上了！\n我沒有貿然為這幅畫命名，我想，這個資格只應屬於您。\n另：我真的不是去翻找屍體的，我向您保證！\n\n皮克曼"
  },
  Mail_124296_Name = {
    Text = "調查員的夙願"
  },
  Mail_124297_Desc = {
    Text = "您好，守密人：\n\n您有沒有在害怕，或者說——既害怕，又期待著妾身會在妾身生辰這天，借著慶祝的名義，帶來一些什麼呢？\n虛與委蛇的親昵，突如其來的香豔夜晚，或者詭譎又令人迷醉的昏沉幻境？\n啊，通通沒有，哪怕是妾身，偶爾也會說些嚴肅的無趣話題。\n您應該很清楚妾身是什麼樣的存在，耽於享樂，哪怕樓宇將傾。\n愛和欲，醫治不了乏味這門世間最大的病症，但作為引出權力和混亂鮮味的藥引，卻再精妙合適不過。\n奈何這千百年的時光，大概是妾身對戲摺子研究得實在太過深入，總會有些庸人剖心挖肝，說我看見了你孤苦無依的寂寞靈魂。\n呼。\n即使是喜愛逢場作戲的妾身，也經常覺得有些反胃。\n而您……您是為了什麼與妾身連結呢，為了控制，為了約束，為了借力？\n您要守護更多的東西，就必然需要更高的權柄，而對權柄的渴望，則會催生更大的野心，它何時會成熟，何時又會被吸吮入腹……真是令妾身光是想想就興味盎然，甘願在您身邊流連更多、更多年月。\n噓，不用告訴我答案。\n在每年此日，擄去您一夜的夢，品嘗揣摩您的野心是否在滋長，您的意圖是否有偏移，便是妾身送給自己最好的生辰賀禮。\n萬望勿怪。\n\n「千扇」"
  },
  Mail_124298_Desc = {
    Text = "守密人：\n\n訓練、戰鬥、巡邏，從我進入軍隊服役的那一刻，就已經習慣了用所有集體需要的事務，填充自己的所有時間。\n後來帶領亞蘭族在沙漠中遷徙，這些事務也愈加膨脹，以至於像定律一樣刻進了我的腦海，以至於來到彌薩格，我也始終把集體日程的優先級位於私人事務之前。\n但在與其他人，尤其是與你的相處中，我意識到，無論是作為喚醒體，還是作為人類，我們都需要一些只屬於自己的時間，用來體會那些與重要之人的相處。\n因為這種可貴的關係，錨定了我們在時間的存在，也使我們的存在真正具有無可替代的意義。\n雖然有些冒昧，我已經取消了今日所有的集體事務，騰出了一整天。\n只需要幾個小時，不，就算是一小時，或者幾刻鐘，只要你願意分出一些私人時間給我，它都將成為我度過這個特殊日子的意義。\n\n艾爾瓦"
  },
  Mail_124298_Name = {
    Text = "私人時間"
  },
  Mail_124298_Sender = {Text = "艾爾瓦"},
  Mail_124299_Desc = {
    Text = "小傢伙：\n\n一年時光對你來說或許漫長，但對於原質之海的穿行者而言，那不過是時光無垠的汪洋裡轉瞬即逝的一捧海水。幸運的是，在這海水里還有一些讓人印象深刻的晶瑩水滴。\n解憂小鋪的折扣日，自然是其中最值得珍藏的那一顆。並不僅僅因為它會帶來金券，更重要的是，我知道在這一天，有一位客人一定會來到這間小店。\n所有人與人的連接都是生意，而一切生意也都是人與人的連接。每位客人都會在一個特定的時間走進屬於他們的小店，每個小店都會在特定的時間迎來屬於它們的客人。在漫長的時光裡，我見過無數珍寶，而到了最後，這些幼稚的時刻將成為最為珍貴的藏品——它們是這漫長時光存在的緣由。\n這一年時光裡，最珍貴的那個新藏品正在珍藏展櫃中，靜靜地等待著那位屬於它的客人。\n早點過來吧，小傢伙。\n解憂小店已經早早歇業。今天，它的門隻為一人而開。\n\n達芙黛爾"
  },
  Mail_124299_Sender = {
    Text = "達芙黛爾"
  },
  Mail_124300_Desc = {
    Text = "守密人：\n\n不知你是否還記得，我們一同位於門扉前的片刻時光？那天我將真理揭開了一條狹縫，為你展示出宇宙的真實。\n意外的是，在你經歷遙望無數世界的永遠時，我竟在轉瞬即逝的須臾間，出現了一絲無法理解的情緒。\n我時常思考那一瞬間的感覺是什麼，為什麼通曉真理的我會產生無法理解之物。\n我思考了許久，以現實世界為基準裁量體系而言，那是足以被稱作「永恆」的時光。\n在這相對宇宙而言都略顯漫長的時間裡，我意識到了，這或許就是尚未被定義的奇蹟。\n在這特殊的日子，我想邀請你與我連結，透過我的目光，去觀測一些我未曾觀測過的存在，這一次我們所觀測的……將不再是被既定的一切。\n我們將一同尋找，這真理之外的未來。\n\n塔薇"
  },
  Mail_124301_Desc = {
    Text = "守密人：\n\n今年也與往年一樣，我停下了所有其他事務，安靜地與自己獨處，試圖重新撰寫、翻新那些與故國有關的回憶。\n它們離我更遠了，即使我逼迫自己習慣這副類人身軀，想盡辦法一遍遍記敘與穿越海洋相關的知識、經歷，在這個日漸消逝的世界中，遺忘依然比銘記容易太多太多。\n唯一的慰藉，即是如今我們這些遠離了利莫里亞的旅人，依然還有此處可以停留，能夠遵循吾王的旨意，安靜地追隨，安靜地等待。\n我深知您為此犧牲與付出的一切，我不知該如何對您表達我的感激，在此身得以回到利莫里亞之前，若有任何能用到我的地方，我同樣願意為此獻出我所有的光亮。\n\n您真誠的法洛思"
  },
  Mail_124301_Name = {Text = "燈塔"},
  Mail_124302_Desc = {
    Text = "親愛的守密人：\n\n自加入彌薩格那天起，紛繁的規矩就纏上了我。不許帶僕從在會場散步，不許在校園廣場踩踏學生的面頰，不許在禮堂舉辦多人集體活動……\n彌薩格那些討厭的衛道士們禁錮了我，這並非伊薩拉烏的女王應當享有的生活。我理當享用我應得的一切，醉人的美酒、柔軟的背脊，還有心愛的僕從……在這個我理應肆意的生辰之日，這樣的念頭自然地生髮出來。\n夜已深，我對瑣事的耐心已然耗盡。我不會派你去執行午夜任務，也不會讓你自行猜測。我需要你待在我的身邊。\n現在就來我的莊園，不要猶豫，脫下你所有不必要的衣物和頭銜。\n今晚，以及以後的每個夜晚，你都屬於我。\n\n你可以把這當作你的第一項永久職責。\n\n旺達"
  },
  Mail_124302_Name = {Text = "規矩"},
  Mail_124302_Sender = {Text = "旺達"},
  Mail_124303_Desc = {
    Text = "守密人：\n\n汀克特告訴我，她用個人演唱會的收入計劃了一場生日後的星際旅行，想帶我一起去。可是……如果我也同行，她一定會分神照顧我。我不願讓她的快樂因我而打折扣。\n她那麼熱愛生命裡的光，迷戀這宇宙中萬千的色彩與流動的星河。若是帶上我，她大概就無法那樣自在地歌唱、盡情地凝視了吧……\n所以……能不能請你幫我勸勸她？請讓她獨自去旅行，去不同的星球開演唱會，去擁抱她嚮往的所有風景……或者由你代替我參加這次旅行？畢竟汀克特和我都很感謝你，想要回報你的恩情……如果你願意的話……\n只是，請不要告訴她這是我的意願。我不願成為她自由旅途裡的那道牽絆。\n\n菲茵特"
  },
  Mail_124303_Name = {
    Text = "關於旅行"
  },
  Mail_124304_Desc = {
    Text = "恩人：\n\n與波呂克斯一同生活在彌撒格的這些日子，如此寧靜，如此明亮，彷彿是一場幻夢……\n波呂克斯他現在雖然依舊守著那些禮節，說著些文雅端正的話，我卻能清晰感到，他正一點一點變回從前那個他。那些屬於「聖子」的、令人屏息的距離感，正在柔軟的日常中悄悄消融。這一切溫柔的轉變，都要歸功於您。\n我時常在想，該用什麼來報答這份恩情呢？我不像波呂克斯那般手巧，能編出令您驚歎的禮物。飛行的樂趣，您也已與我體會過多回。關於如何在這個特別的日子與您分享喜悅，我默默思考了許久。\n也許……您會喜歡我的羽毛嗎？常有人說，它擁有一種能令人心情寧靜的柔軟。所以，若您有一日感到疲倦，或只是想要一處安靜的角落，請隨時來到我身邊吧。我的羽翼，永遠願為您垂下。\n\n卡斯托爾"
  },
  Mail_124304_Sender = {
    Text = "卡斯托爾"
  },
  Mail_124305_Desc = {
    Text = "我的小·囚·犯：\n\n聽說彌撒格最近正在流行一款角色扮演遊戲，什麼女巫、狼人呀……嘖，聽起來一點都不浪漫呢~我倒是想到了一個更好玩的遊戲！\n這樣，你來扮演囚犯、我來扮演看守。當我揮動小皮鞭時，我要聽到大聲的呻吟聲哦~蠟燭在你的身軀之上流淌，帶來滾燙的痛感與快樂……啊，光是想像一下那幅畫面，就已經開始感到甜蜜了呢~\n哎呀，看到這兒，你一定又皺起眉頭了吧？真是不乖哦，今天可是我的生日呀~親愛的小囚犯，總該滿足我一點點任性的願望吧？\n實在不行的話……那……換你來當看守，我來做你的俘虜，怎麼樣？我會滿足你的啦~\n\n潘狄婭"
  },
  Mail_124305_Sender = {Text = "潘狄婭"},
  Mail_124306_Desc = {
    Text = "守密人：\n恩人，今天是我的生日。在這個特別的日子裡，我想向您說說我的近況：在戈利亞和蘿坦老師的指導下，我好像……越來越能觸碰自己血脈中的力量了。它不再沉睡，而是隨著每一次練習，在我身體裡低鳴、奔湧，逐步解放。\n\n\n\n我說不清具體何時才能完成最終的蛻變，成為更純粹的深海族裔。也許明天，也許下個星期，也許下個月……但請您知道，無論這個過程還有多長，路上還有多少磨難，您當初鼓勵我的話，我一直…都牢牢記得。我會繼續努力的。\n\n還有一件事我必須表示抱歉，我剛剛從彌薩格郵政處獲知，隨郵件發出現金的話，需要額外繳納2塊手續費。\n為了補上去年份額，我會從積蓄中再支出一筆來。它們對我來說得來不易，但深海的血脈有承諾必定兌現。\n\n凱刻斯"
  },
  Mail_124306_Name = {
    Text = "手續費……"
  },
  Mail_124306_Sender = {Text = "凱刻斯"},
  Mail_124307_Desc = {
    Text = "守密人：\n\n聽好了，今晚無論如何，跟我一起去「那家店」。\n偽裝用的衣服已經寄給你了，務必、千萬，不能讓別人認出我們！\n「那家店」的限量甜品開售了，那個不知道哪裡來的可惡傢伙肯定收買了一批人，不能讓他們知道本小姐的行蹤。\n雖說那個傢伙為了不讓我買到，把倫蒂尼恩所有蛋糕店的限量款都預定了，但是嘛……哼哼。\n本小姐已經提前買通了「那家店」的主廚，讓他把最最好吃的那款，從菜單上給去掉了。\n哼，本小姐今天就要讓那個傢伙知道，有些事情可不是單純靠金錢就行的。\n到時候我們悄悄從後門溜進去，把經過三重加密的鐵盒打開，就能得到那份限量款中的限量款了。\n作為報酬，我會把一塊（劃掉），一半的蛋糕分給你！\n今晚十一點，我在房間等你，你必須、一定要來！知道了麼！\n千萬要保密，不然洩露了消息讓那個傢伙知道了我們的行蹤，就一切都完蛋了！\n\n墨菲"
  },
  Mail_124307_Name = {
    Text = "搶糕大作戰"
  },
  Mail_124308_Desc = {
    Text = "守密人：\n\n很遺憾地通知你，倫蒂尼恩劇院已經完全取消了卡茜亞大師的魔術表演，原因有：票價過高、大家最近見到的怪事太多導致對魔術缺乏興趣、連續幾場表演都有觀眾失蹤至今未歸、經常有員警找到劇院老闆要求卡茜亞大師暫停表演前去配合調查等等等等。\n最近受到黑池異動的影響，我的表演確實偶爾有些小失誤，這些都是小事，但第二點是卡茜亞大師絕對無法容忍的！\n我為此冥思苦想，終於想到了一個完美的新表演！什麼屍體操縱、死者復生、維度穿越、情緒感染、巨大觸手……通通不值一提！之前受那只可惡的維度獵犬影響，時間的操控一向是本行業的禁忌，但在那只惡犬被封印之後，卡茜亞大師的魔術事業將重新登上一個新的臺階！\n演出時間就定在今晚，完全免費，守密人在第一排正中間的座位已經預留，還有驚喜的互動環節在等待著你！享受你作為新時代最偉大的魔術演出裡第一個互動觀眾的榮幸吧！\n為了重拾卡茜亞大師的榮耀！\n\n卡茜亞"
  },
  Mail_124308_Name = {
    Text = "卡茜亞，讓魔術再次偉大！"
  },
  Mail_124308_Sender = {Text = "卡茜亞"},
  Mail_124309_Desc = {
    Text = "主人：\n\n茜爾維婭姐姐剛才來告訴我，今年的生日，她們會帶我去乘坐摩天輪。\n莉莉在畫本上讀到過，摩天輪是一種很大很大的輪子，坐在上面就可以慢慢慢慢地轉到天上，看小鳥在旁邊飛來飛去，聽起來就非常幸福。\n不過茜爾維婭姐姐說“實際上有一些區別”。莉莉也不明白是怎麼回事。\n她還說，摩天輪要去的地方太高了，我最好能帶上一位監護人。\n莉莉不懂監護人是什麼意思，但莉莉想和主人一起去雲朵之間旅行。\n午飯後，我和茜爾維婭姐姐會在宿舍外等你。\n\n莉莉"
  },
  Mail_124309_Name = {Text = "摩天輪"},
  Mail_124310_Desc = {
    Text = "守密人（這次我終於寫對了！厲害吧！）：\n\n又到了寫這些肉麻東西的時候，我都已經習慣了。比是 此時此克 現在，我和布朗正為今天請你吃什麼頭疼呢！\n東區小巷裡的街頭美食當然好吃，但今天我打算帶你和布朗吃點好的——也就是你們西區佬愛吃的那些東西。\n比如那些沾滿了醬料和香料的私家菜，量又小，盤子又大，還貴得離譜，簡直就和搶錢一樣。想到這裡，我就覺得錢包開始漏風了，那一定是金錢離開時，留下的闖傷。\n但你是除了姐姐和布朗外，我最重要、最喜歡的人，東區人可不會對自己人吝嗇，所以今天所有花銷都由我和布朗支付。\n可別小看我們，我們可是靠送牛奶送報紙傳話跑腿還有其他業務掙了不少錢的，你就放心點吧！\n\n你的好夥伴詹金和布朗"
  },
  Mail_124310_Name = {
    Text = "今天我和布朗買單！"
  },
  Mail_124311_Desc = {
    Text = "親愛的守密人：\n\n你一定已經聽說了茜爾維婭徹底摧毀彌薩格地下賭場的豐功偉績吧？但今天是我的生日，要是沒有什麼腎上腺素飆升的好活動，豈不是浪費了一年一度的好日子？\n經過反復斟酌，我決定特邀你作為我的好華生，和我一道出手拿下近日裡從西岱流竄至此、盜竊大博物館寶藏的暗夜怪盜。\n我在校外那間「阿波羅吧」小酌的時候，偶然聽到過他們眉飛色舞地吹噓自己搜刮昂貴珠寶的戰績。酒保沒往心裡去，我可是聽出來了，祖母綠、藍寶石、鑽石冠冕，和失竊物完全一致。為了避免打草驚蛇，我好好地在他們身上做了記號，準備等他們返回據點，來一個人贓俱獲。\n今晚七點，校門口彌薩格專列停車點，我們不見不散。\n\n萊克"
  },
  Mail_124311_Name = {
    Text = "狩獵計劃"
  },
  Mail_124311_Sender = {Text = "萊克"},
  Mail_124312_Desc = {
    Text = "守密人：\n\n彌薩格的時光轉動得似乎比其他的地方都更加輕盈。幾次掌聲，幾次謝幕，一年的時間便又過去。\n這一年裡，我有了一些新的習慣。以前當我站上舞臺的時候，即便是再擁擠的劇院在我眼中也空無一人。我在空曠的舞臺上，對著空曠的劇場舞蹈，整個世界迴蕩著的只有一雙舞鞋的聲音。而現在，每當帷幕拉開，我都會看見你。萬千的座椅空空如也，獨你一人望向我。在你的目光裡，我的舞重新擁有了意義。\n一年過去，你的舞姿依然是那麼笨拙，可你在台下那些躍動的目光，卻能輕易地超越台上那些庸凡的舞步。那些目光是一道溪流，將我日漸凡俗的舞步一一清洗。在這些舞者與觀眾的共舞裡，我正逐漸靠近那個我一直所追尋的殿堂。我終於領悟到，對於舞蹈而言，觀眾與舞者同樣重要。\n好幾個月時間裡，我一直在為一支舞做準備。它沐浴著你的目光孕育，在你的剪影裡誕生。如今，它已經準備好。\n我想，它會期望在今晚，看到你成為第一個見證它的人。\n\n莉茲"
  },
  Mail_124312_Name = {
    Text = "舞者與觀眾"
  },
  Mail_124312_Sender = {Text = "莉茲"},
  Mail_124313_Desc = {
    Text = "守密人：\n\n得益於此地的接納，這一年裡，我與王交談的時日頗多。儘管神國的降臨仍然遙遠，但利莫里亞的時光，似乎正在彌薩格續延。\n你與王都曾告訴我，信仰不應該是我生命的全部。我曾固執己見，但最近經歷的事，似乎讓我的心態有所轉變。過於頻繁的禱告，或許會令吾主感到叨擾。除了虔心的侍奉之外，吾主或許也希望祂的信徒有著屬於自己的淺薄生活。\n明悟了這一點後，我嘗試去做了一些微小的改變。我拜訪了倫蒂尼恩所有有名的糕點師，請他們教授了我烘焙的方法。他們有一些不傳之秘，我也已通過吾主的賜福讓他們開了口。昨日，我第一次進行了一些嘗試，幾名信徒告訴我他們覺得味道很不錯，但他們的味覺與忠誠一樣令人懷疑。\n我想邀請你今日來我的庭院裡品嘗。我相信你的品味，也相信你的坦率。如果不好吃的話，希望你能直言不諱，我將認真加以改進。\n不勝感激。\n\n彌利亞姆"
  },
  Mail_124313_Name = {
    Text = "另一個專長"
  },
  Mail_124313_Sender = {
    Text = "彌利亞姆"
  },
  Mail_124314_Desc = {
    Text = "守密人閣下：\n\n關於生命與死亡的意義，想必你已經聽得厭煩了吧？在葬骸城那些亡靈們絢麗的記憶裡，我學會的最重要的事是，比起探尋進食的意義，更重要的，在於面前餐桌上的食物本身。\n在人類的遠古時代，我們的祖先便已經探尋出了一切關於進食的內涵——激情，欲望，享用。並非為了活著而進食，是為了進食而活著。遺憾的是，那些原始純真的欲望在漫長的時光裡被逐漸遺忘，這個群體變得越來越複雜。\n因此，我將今天的晚宴主題命名為「純粹」。在這個具有儀式感的日子裡，一切複雜的事務都將離我們遠去。這張餐桌之上，只有純粹的、原始的激情與欲望，只有品鑒者與食物，只有你我。\n請收下我最誠摯的邀請。你不會拒絕我的，對嗎？\n\n杜勒賽因"
  },
  Mail_124314_Name = {
    Text = "純粹的晚宴"
  },
  Mail_124314_Sender = {
    Text = "杜勒賽因"
  },
  Mail_124315_Desc = {
    Text = "我最親愛的守密人大人：\n\n我的心好像正在生長……我知道這對喚醒體而言聽上去很奇怪，但它與之前不同了，我要怎麼向您形容呢？\n無論那些好人們如何溫柔地、憐惜地對待我，嘗試溫暖我，在哥哥離開之後，我的胸口始終空洞，我越在太陽下行走，越被那些溫暖抓撓。反而陰暗和潮濕更讓我安心，彷彿只要一直待在陰冷的地方，哥哥嚴厲和令人疼痛的愛意就一直沒有離開。\n可是現在，在這些與您愈加親密的年月之後，每次見到您，每次那些您贈予的疼痛落在我的皮肉上，傳導到我的骨頭上——啊啊，我胸膛裡的幸福日漸增長。只要您毫不憐惜地責打我，侮辱我，蹂躪我，我就知道，這個世界上始終有我真正能容身的地方。\n這種幸福能延續到下一年嗎，再下一年呢？如果生日許下的願望都實現，我唯一的願望，就是被您一直用輕蔑的眼光審視著，還有疼痛……更多更多的疼痛。您揚手時，我首先感受到的將是那股熟悉的、殘酷的、幸福的香氣。\n\n非常非常希望被您責打的雷婭"
  },
  Mail_124315_Sender = {Text = "雷婭"},
  Mail_124316_Desc = {
    Text = "守密人\n\n儘管我很想知道您最近的練習情況，但請放心，今天並非是來督促您進行音樂訓練的。\n今日清晨，我如往常般前往音樂室，但我遲到了三十五分鐘。清晨七點進行音樂訓練，這個習慣我維持了數十年，它在今日輕易地打破了。原因是在路過學校走廊時，我聽見了一陣知更鳥的啼鳴。\n維持多年的習慣被打破並非一件容易接受的事，於我而言更是如此。奇怪的是，我並未如想像般那樣因此而對自己感到失望與憤怒。剛開始的時候，我感到一陣慌張。但隨後，我不得不承認，縈繞在我腦海中的旋律是愉悅。\n倫蒂尼恩總是在知更鳥的啼鳴中被喚醒，這個聲音我每天都能聽見，奇怪的是，這麼多年來，這是我第一次注意到它們。我在走廊上靜靜凝聽它們的歌聲，在那三十五分鐘裡，我竟覺得這宇宙至高的旋律就藏在它們細小的喉管裡。\n或許是這裡的生活令人懈怠，或許是這裡的氣氛讓人變得柔軟。無論如何，我想它一定與您有關。\n我用了十分鐘便欣然接受了這個變化。生命如同音樂一般有其亙古的節奏與變化，誕生之日，或許便是這些變化註定發生的節點。我也想感謝您，讓我有這樣的機會去靜下心聆聽我曾忽視之物。愉悅，沒錯。我想，這會是我邁入一個新的樂章的開始。\n為此，我想邀請您在今日黃昏的時候與我一同去校外的密林。自然在黃昏時的聲音與清晨不同，但我想，它們都會是我們音樂生命裡新的啟迪。\n\n哈姆林"
  },
  Mail_124317_Desc = {
    Text = "貴人：\n\n我剛剛看到了菲茵特寫給您的那封生日郵件……果然，姐姐她總是這樣為他人著想，只是姐妹之間從來沒有虧欠，我也從未將她視作我的拖累，若沒有她的保護，我也不會擁有如今開巡迴演唱會的機會。\n尊敬的貴人，您一直是我最重要的聽眾。所以這次，我也悄悄為您準備了一張船票——誠摯地邀請您與我們一同踏上這次星際旅程。若有您同行，相信姐姐心裡的負擔感也會減輕許多。\n另外請您放心，旅途中我們絕不會打擾您的私人時光。我和姐姐都希望，您能盡情享受這段旅程，自由地去感受每一片星雲、每一場未知的相遇。\n\n汀克特"
  },
  Mail_124317_Name = {
    Text = "旅行邀約"
  },
  Mail_124318_Desc = {
    Text = "守密人： \n\n生日又近，思緒卻總不經意間飄回西岱。尤其懷念那些藝術展上的雕塑。它們靜默的姿態，曾無數次叩擊我靈感的大門。\n在工作室裡終日與雕塑為伴，缺乏藝術的交流，長久以來，也覺乏味。去年此時，為給自己慶生，我雕砌了無數個雕塑蛋糕。起初的興味盎然，如今也已復歸於平靜。\n而今行動不便，重返西岱已成奢望。若你恰有前往調查的計劃，可否為我留意藝術展中的新作？我渴望借由你的眼睛，再次觸碰那片多元而包容的藝術之美。\n作為報答，我願為你再創作一個雕塑，就叫《守密人在西岱》，怎麼樣？\n\n珊"
  },
  Mail_124318_Name = {
    Text = "西岱懷想"
  },
  Mail_124770_Desc = {
    Text = "守密人：\n\n由於每年我進入實驗室的權限都會被取消，以至於這個日子以一種並不令人愉快的方式變得特殊，為了不將時間浪費在缺乏效率的瑣事上，我去了一趟檔案館。\n在那裡我發現了兩樣東西，其中一本是作業本，上面佈滿了毫無價值的空白。\n另一本也是作業本，它讓我發現我低估了知識汪洋的浩渺，因為上面的推演過程和結論，讓我知道了世界上居然還有存在比不存在價值更低的事物。\n而這兩本作業本，上面都寫著同一個名字，我們偉大的彌薩格守密人%player%。\n艾瑞卡告訴我，你想知道該送我什麼生日禮物。\n你可以送我一個答案。\n我也很想知道，哪個答案的事實會更震驚我。是單純地被髮揮到極致的懶惰和敷衍，還是你認真學習了一整個學年，最後在徒勞的絕望中留下了這些學術垃圾。\n如果是前者，只要有充分的理由，並且能證明你已經全盤掌握了課堂上教授的知識，我可以替你向學院提交免作業申請。當然，這並不代表我支持這種可能會令你徹底怠惰的散漫，但只要你能一直通過我的考驗，我不是那種老古板，並不介意給我的學生一些特權。\n如果是後者，作為你的第一監護人，相信我，無論你是多麼難以塑形的材料，我們都能在我掌握的技術中，找到一項，用以提高你過於貧瘠的智識，救你脫離無知而努力的痛苦境地。\n今天下午四點，我會在檔案館，親自考察你對課堂知識的掌握，不要遲到。\n\n朵爾"
  },
  Mail_124770_Name = {Text = "特權"},
  Mail_124770_Sender = {Text = "朵爾"},
  Mail_124771_Desc = {
    Text = "彌薩格的小狗：\n\n今年你也困在那些循環往復的日常裡，闖禍，拯救世界，結交朋友，學習新知識，繼續為世界捏造一些一切如常的假像。\n原來即使把你的腦子從身體裡摘出來，靈智從一個維度抽離到另一個維度，也並不會影響到你荒唐到讓人發笑的奔走和忙碌。\n真是又忙又吵啊，親愛的小狗狗。\n你不相信那些事實，你非要延續他們的痛苦，讓滅亡的過程延續得更拖沓一些，你的目的是什麼，你到底是在裝傻，還是人類真的能傻成這樣呢？即使我確實剖開過你這個身體的腦葉皮層，這些對我來說依然是未解之謎。\n恭喜你，你真的讓我產生了一絲動搖，我居然開始懷疑，如果觀察你為我帶來了如此巨大的樂趣，那麼一切還能說毫無意義嗎？\n像你擅長做的那些毫無意義的事一樣，毫無意義地祈禱吧，祈禱對象是誰都無所謂。\n祈禱你能一直桎梏住我，小狗狗，這樣我和你，都能在毫無意義的世界中，找到些許樂趣。\n\n「朵爾」"
  },
  Mail_124771_Name = {Text = "祈禱吧"},
  Mail_124771_Sender = {
    Text = "熔燬·朵爾"
  },
  Mail_124772_Desc = {
    Text = "搭檔：\n\n在每年生日這天給你寫信，好像不知不覺就成了一種慣例。\n我還記得，第一個給你寫信的生日，也是父親第一次答應我自己安排生日行程，我邀請你和我一起外出，再後來，我們一起經歷了太多個第一次。\n很多事物在那之後都改變了許多，仔細想來，又好像並沒有什麼改變，我們依然行進在我們所認定的那條道路上，我們的身邊依然有彼此陪伴，以及，你依然是對於我來說，最重要的那個搭檔。\n所以，雖然父親剛剛送來了一個蛋糕，詢問我晚上是否願意出席他為我舉辦的宴會，我對今晚也有一些其他安排。\n倫蒂尼恩上映了一部新電影，受歡迎得異乎尋常，不過學院和協會已經共同確認過，其中不存在任何靈性反應。\n這說明它的確只是一部非常精彩的「普通」作品。\n我正好有兩張票，你可以假設我沒有破例去麻煩索蕾爾夫人，因為它的票實在太過難買。\n那麼，搭檔，你願意把這段時間留給我嗎？或許，我們可以暫時從那些我們日日在處理的異常狀況中脫離出來，陪伴彼此度過一個「普通」的晚上。\n之後的每一個明天，當我們醒來，不論世界發生什麼，我都會和你一起面對。\n\n拉蒙娜"
  },
  Mail_124773_Desc = {
    Text = "守密人：\n\n得益於我與那個我之間的特殊聯繫，以及我和你之間的連結，即使沒有時刻陪伴在你身邊，我也對你過去一年的動向略有知曉。\n你活躍於另一個世界，似乎依然給它帶來了名為「希望」的改變，即使日復一日地在黑池中仰望著，這種如同光芒一樣的能量，也同樣溫暖到了我。\n我開始重拾起了之前的日程，但和之前不一樣，現在我並不是再以徒勞掙扎的心態，去面對那種註定的寂滅。你教會了我新的東西，在註定的終點之前，每個存在為了延續而拼盡全力的過程，正是文明、靈魂、意志之所以有意義的原因。\n不論對於我所在的世界來說，這段時間有多麼短暫，我會繼續嘗試下去。哪怕僅僅只是為了再見到那些熟悉的面孔，和他們交談幾句，這種嘗試也並不是毫無意義的。\n直到你停止之前，我都會繼續走在這條路上，請允許我任性地將它視作某種與你並肩的方式，這樣，或許你能在不斷行進的路上，偶爾想到，始終有這樣一個我，在全力做著與你一樣的事情。\n\n「拉蒙娜」"
  },
  Mail_124774_Desc = {
    Text = "殺掉目標很簡單，善後卻是件麻煩事。\n本來今年想遵循去年的慣例，再幫你殺個人。\n然而我注意到你一直沒有使用我送給你的上一份禮物，經過認真思索，雖然不知道是不是出於這個原因，不過我發現了自己的疏漏。\n你完全可以放心，雖然對於過去那些雇主，我一向只提供殺死敵人的服務，但為了避免各種各樣的麻煩，對於銷毀痕跡這件事，我也很有經驗。就算你想殺掉的傢伙處於那些繁瑣的規律和秩序的保護下，你也不需要有任何心理負擔，我會把一切都處理好的。\n我保證，沒有任何人能追查到你頭上。\n想好人選之後，就把名字告訴我，無論我在哪裡，都會立刻趕去幫你解決祂。\n祝你節日快樂，也希望你在我出生的這天感到快樂，守密人。\n\n\n希洛"
  },
  Mail_124774_Name = {
    Text = "經常殺人的人都知道\n……"
  },
  Mail_124775_Desc = {
    Text = "好吧，顯然你們沒有準備停止這種行為，據我所知，那個我也已經習慣了「贈送禮物」的慣例。\n但有一天你會為這種善意後悔的，相信我。\n現在想想，那可能也是我最後悔的一件事，該死，我可沒想過我會為了殺人後悔。\n沒人比我更清楚，所謂歉意的毫無價值，不過在那一天到來之前，我會盡力做些什麼來彌補，僅僅只是因為我想做。\n當你將來因為那件事怨恨我的時候，不用為此感到任何心理負擔。\n我會全盤接受你們的怒火。\n\nH"
  },
  Mail_124775_Name = {
    Text = "你會後悔的"
  },
  Mail_124775_Sender = {
    Text = "血鏈·希洛"
  },
  Mail_124776_Desc = {
    Text = "守密人：\n\n又到了誕生的這天，按理說是慶祝擁有生命的日子，所以每當這天來臨，我都會生出一些奇妙的感覺。\n我的出生似乎就是為了追逐死亡，當脫離死亡這個主題後，生命……或者說意識依然在延續的瞬間，對我來說到底意味著什麼呢？\n生前，痛苦和愧疚的拉扯，和我的生命是如此難以分割地糾纏不清，以至於彷彿直到死亡來臨後，生命才第一次真正屬於我。\n去年、今年，或許還有今後的每一年。我擁有了漫長到幾乎無盡的時間來體會，每一天都與前一天相似，又與前一天不一樣。在生命不再被痛苦與目的纏繞的時候，它的終點會變成什麼樣子，或者所謂的終點，還會再到來嗎？\n這個命題太龐大了，我有些想不明白。\n但想要記錄下這些陌生思緒的情緒是如此真實，我又覺得答案好像昭然若揭。\n至少對我來說，是這些切實的、珍貴的瞬間，不論我的思緒是多麼紛雜，不論我怎樣地難以找到根系，我明確地知道，它們能夠飄向哪裡，被哪裡接納，而我也同樣迫不及待地想將它們表露給您。\n或許明年的今天，我能找到一些更加自我的意義，不過現在，我希望能夠自私地保留這些小小的，只有您和我知曉的依賴。\n是的，守密人，您和彌薩格的大家，是我內心無人知曉的根系。\n感謝您，一如既往地，願您永遠歡樂，永遠安寧。\n\n寧菲亞"
  },
  Mail_124776_Sender = {Text = "寧菲亞"},
  Mail_124777_Desc = {
    Text = "餘最近發明了一種新的放鬆方式——神國午休。\n不同於一般短暫、倉促的午休，在進行神國午休時，余會離開久坐的青石王座，將腕觸構建成阻絕聲音的球體，再用特製海水填滿整個空間。\n這些海水不僅可以發出余想要的香氣、變成余想看的景色，更可從各個方向以合適的強度支撐餘的身體。\n因此，無論餘擺出何種動作，都可以體驗到這般，如置身最高等羽絨床榻內的溫暖包裹感。\n屆時，餘便可以在心儀的芬芳中放鬆心神，享受與世隔絕的寧靜，枕靠餘最喜愛的枕頭安然入睡。\n作為余最中意的臣子，餘認為生辰當日，最適合同你分享這份閒適。若你有意，可來上次跟你說過的秘密地點。無需擔心你的安危，余會單獨為你開闢一個空間，讓你免受餘外溢夢境的影響。\n別忘記帶上你最舒適的枕頭。\n\n圖魯"
  },
  Mail_124777_Sender = {Text = "圖魯"},
  Mail_124778_Desc = {
    Text = "我的明燈：\n\n我與卡斯托爾已經適應了彌薩格的生活，逃離了教會血腥的爾虞我詐後，我感覺我正在找回過去的自己。\n雖然現在日常言行間還是不可避免的摻雜一些「聖子」的影子，但相信過不了多久，我便可將那傲慢和疏離完全洗去，僅保留對神明的謙卑和貫徹將行之路的決意。\n早些時候我收到了一份有些意外的禮物，是一本裝裱精美的書籍，講的是有關離鄉之人回到故鄉，找回自己童年的故事。與之一同送來的還有一張紙條，上面寫著「祝你早日找回最初的自己」。\n這句話映入眼簾的第一幕，過往那些回憶便浮上心頭——彌薩格大家的關心，明燈你的指引，還有兄長他……溫暖的擁抱。\n因此今年生日，我想邀請彌薩格的大家，一同來參加我和哥哥的生日宴會。沒有大家的幫助，我們絕無找回最初時光的可能。\n我用最近一段時間積攢的積蓄包場了一間飯店，那裡的主廚對世界各地的菜系都有涉獵，相信每位都可以在那裡品嘗到自己最熟悉的味道。\n\n波呂克斯"
  },
  Mail_124778_Sender = {
    Text = "波呂克斯"
  },
  Mail_124779_Desc = {
    Text = "我決定接受郊外的那家地下競技場的邀請，去打一場生死不論的比賽。\n雖然在鱒魚俱樂部的日子很好，可這太平淡了，每天不是殺魚就是殺魚，也許我確實徹底征服了鱒魚，但征服鱒魚可算不上征服！\n我體內的戰士之血在沸騰，它們一直渴望一場令人血脈賁張的戰鬥，而現在，機會來了。\n跟我聯繫的那個禿頭說給我找來了三條納泰巨蟒，兩頭鬼面熊，四隻瑟里納森鱷和一堆我記不住名字的奇怪生物，足以讓我盡情廝殺一整晚。\n我特地讓他們把比賽安排在了今天，為的就是能在生日當天向你展示——我，尤烏哈希，最後的羅馬戰士，征服世上一切猛獸的盛況！\n今天灑滿場地的將不再是鱒魚邊角料，而是鮮血和異獸猛禽的屍塊！\n\n尤烏哈希"
  },
  Mail_124779_Name = {
    Text = "征服猛獸"
  },
  Mail_124779_Sender = {
    Text = "尤烏哈希"
  },
  Mail_124780_Desc = {
    Text = "「銀鑰騎士」：\n\n守密人！剛剛我正在改裝「幻影號」的時候，莫絲突然給我送了一大——包零件，說是給我的生日禮物，我才想起來今天是我生日！\n所以我趕快寫了封信給你，真是的，我怎麼又把今天忘記了，明明我已經寫了……寫了多少張紙條來著？\n不過這些都不重要，重要的是，我想起來之前說的生日當天要幹什麼了——我要騎上「幻影號」，帶著你和莫絲一起繞整個倫蒂尼恩一百圈！\n雖然莫絲完全不懂機械，但她那袋零件實在太多了，多到我可以找齊所有需要的零件。現在改裝後的「幻影號」，已經是超級加強原型版了（暫時的）！\n我給這場冒險起了個名字，叫做諾締拉與守密人與莫絲與「幻影」的冒險，怎麼樣，是不是很直接很好記？這樣我就肯定不會忘記這場冒險啦。\n嘿嘿，真是令人期待呀，守密人再稍微等一下哦，「幻影騎士」諾締拉和「漩渦騎士」莫絲馬上就到！\n「幻影」冒險團，出擊！\n\n正在開足馬力衝過來的諾締拉"
  },
  Mail_124780_Name = {
    Text = "「幻影」出擊！"
  },
  Mail_124780_Sender = {Text = "諾締拉"},
  Mail_124793_Desc = {
    Text = "尊敬偉大<Del:可愛>的守密人{Male=先生,Female=小姐}：\n\n咳咳，好久沒有聯繫,我們親愛的守密人{Male=先生,Female=小姐}想我了麼~\n現在你可是彌薩格的大名人啦，所有學生都在學習你的英勇事蹟，任何能稍微跟你沾上一點點邊的東西都能在黑市賣出天價！\n不過這也正常嘛，畢竟誰讓你是「活著的傳奇」，彌薩格唯一的守密人呢？\n這一年裡彌薩格也發生了很多有趣的事——奧瑞塔跟幾個薑餅成為了朋友，朵爾教授為了給腦缸換個造型搞炸了十七個實驗室，卡斯托爾被阿格里帕騙去幫她考試，結果那是門常識課，最終成績比她自己考還差！\n哦對，還有那只可惡的小耗子，居然把我寶貴的膠捲偷走了，那可是我好不容易才拍到的「24」小姐的貓形態！\n除此之外還有很多，我把它們整理了一下，作為校報的新年特別刊一起寄給你啦。\n什麼？你好奇我是怎麼聯繫到你的？嘿嘿，這是秘密哦，我才不會說是我用了很多獨家機密跟某位一看就很難對付的夫人換的呢！\n新的一年裡就讓我們一起努力吧，新年快樂，%player%！\n\n漢娜·皮斯利"
  },
  Mail_124793_Name = {
    Text = "新年特別刊"
  },
  Mail_124793_Sender = {
    Text = "漢娜·皮斯利"
  },
  Mail_124794_Desc = {
    Text = "蒼白使者：\n\n銀霜將至，請允許我先在這裡向你表達最真摯的祝福。\n\n上次我去莉莉安濟貧院探望孩子時，有些孩子偷偷問我「冬渡使者真的存在嗎？」。\n我很好奇這些孩子為何會有這種想法，如果我沒記錯，去年應該每位孩子都收到了來自「冬渡使者」的禮物。\n結果孩子們對我說——「我看到那個帥帥的男人把禮物交給了戴安娜院長，他看起來一點都不像冬渡使者！」。\n想來應該是勳爵閣下為濟貧院贈送禮物時，不小心被孩子們發現，才產生了後續的這些小小疑惑。\n\n因此今年銀霜夜，我準備了兩套非常傳統的冬渡使者服飾，想請蒼白使者你與我一同扮演冬渡使者，為這些孩子送上禮物。\n我相信一定會有孩子在晚上偷偷睜開雙眼，記下我們紅衣紅帽的形象，再於冬渡節興高采烈地告知大家——「我看到冬渡使者了！」。\n同時我也特地為你準備了一份禮物，希望你能喜歡。\n冬渡節快樂。 \n\n薩爾瓦多"
  },
  Mail_124794_Sender = {
    Text = "薩爾瓦多"
  },
  Mail_124991_Desc = {
    Text = "尊敬的守密人：\n「多重療癒·復刻」復刻活動已結束、現將守密人剩餘的活動貨幣「記憶拼圖」按照每個兌換「薔薇金券」× 40 的比例進行回收、請守密人記得查收。"
  },
  Mail_124991_Name = {
    Text = "記憶拼圖回收"
  },
  Mail_124991_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_125448_Desc = {
    Text = "親愛的守密人：\n「海城舊聞」活動已結束、現將守密人剩餘的「梨膏糖」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_125448_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_126321_Desc = {
    Text = "尊敬的守密人：\n「織者自縛」活動已結束，現將守密人剩餘的「絲絨座票根」按照每枚兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
  },
  Mail_126321_Name = {
    Text = "絲絨座票根回收"
  },
  Mail_126321_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_126934_Desc = {
    Text = "守密人：\n\n又到了這個特殊的日子。呵，不必擔心，今年我不會對你施加心理暗示，我只是想邀請我最特別的患者，去某個地方散散心。\n那裡有繁茂的樹林，清澈的河水，充滿了自然的氣息，能夠令你忘卻鋼鐵森林的疲憊。還會有柔軟的地毯，溫暖的火爐，明亮的燈光，助你舒緩城市快節奏的壓力。\n我們可以在那裡漫步、讀書、談天說地，無論你想要傾訴什麼，我都很樂意傾聽。\n啊，光是想像那樣的情景，就已經讓我心潮澎湃……\n我知道，此時此刻，你一定會有些不安。畢竟，我無法保證自己不去享受你那滿是甜蜜的痛苦回憶。但你仍舊會來的，對不對？\n不單是因為今天是我的生日，也是因為，你需要著我，需要向我傾訴，需要我的傾聽。\n乖孩子，我明白的，而且，我也會等待著你。來，忘記繁忙的日常和沉重的責任，享受這安寧的一刻。\n\n克萊門汀"
  },
  Mail_126934_Name = {
    Text = "安寧的一刻"
  },
  Mail_126934_Sender = {
    Text = "克萊門汀"
  },
  Mail_126935_Desc = {
    Text = "又是無聊的一天。\n我試過了很多法子——非利士傳統的宴會，和倫蒂尼恩那些幫派玩一些小孩子把戲，沒有一個能配得上作為巨人之王誕臨之日的禮物。\n非利士人以戰鬥與殺戮為樂，曾經的這個日子，我與最強大的戰士們在營地中歡聚、戰鬥，用力量與鮮血紀念這偉大的一天。\n和平。乏味的和平。我理解你們這些人對於和平的嚮往，並非每個人都有一顆屬於戰士的野心。不過，不要以為這些虛假的和平會影響到偉大的非利士之主。\n曾經屬於我的一切，領土，財富，權力，非利士不滅的榮耀……在我奪回它們那一天，我會邀請你的，守密人。我會讓你坐在我身旁最尊貴的賓客席位上，看著偉大的巨人之王重獲他的榮光。\n本來打算直接結束這乏味的一天，不過我剛剛聽說，那些被打散的幫派組建了一個聯盟，要在今天的晚宴上圍剿巨人之王。\n相比非利士人的戰爭，這只是個幼稚的遊戲。不過在這無聊的和平日子裡，能有這樣的餘興節目，也值得讓我感到欣慰。\n來重新見識下非利士之主征戰的英姿吧。站在我身旁，或者站在我對面，怎樣都行。\n不過要快一點。太晚的話，就只有收屍的份了。\n\n戈利亞"
  },
  Mail_126935_Name = {
    Text = "餘興節目"
  },
  Mail_126935_Sender = {Text = "戈利亞"},
  Mail_126936_Desc = {
    Text = "尊敬的守密人：\n\n您好。為了更好地服務彌薩格師生，艾瑞卡於前幾天自行進行維護及升級，您幸運地被選為測評本次升級結果的人選。本次評估以線下方式進行，需要你對自動人偶艾瑞卡最新安裝的LY-S-761號情感模組進行功能評價。該測試預計會佔用您90分鐘，請您提前做好規劃，避免日程衝突。\n以下是本次測評的內容：\n1.請與艾瑞卡進行一段至少15分鐘的開放式深度聊天，話題圍繞「生日」進行，以測評艾瑞卡對特定情感的理解範圍與深度。\n2：請模擬「贈送生日禮物」場景與艾瑞卡互動，以測評其情感識別與共情回應的準確性、靈活性及舒適度。\n3：請在測評中後期，有意提及艾瑞卡於前期對話中涉及的個人細節（例如她對於生日的態度、認知等），以測評其長期互動記憶與關聯能力是否正常運行。\n\n請您在上述測評完成後，對艾瑞卡說「艾瑞卡，生日快樂」以結束測評，人偶將自動進入資料上傳模式。\n感謝您的參與，完成測評後，艾瑞卡會贈送特殊小禮物。也請您在未來繼續支持，您最貼心的助手艾瑞卡會永遠陪伴在您的身邊。\n\n艾瑞卡"
  },
  Mail_126936_Name = {
    Text = "生日升級測評"
  },
  Mail_126937_Desc = {
    Text = "哈啊，今天是怎麼回事，怎麼無論我走到哪裡，大家都在有意識地迴避我？甚至我還沒有開口，就連連擺手，說自己這裡不舒服，那裡疼痛，搞得我都沒有辦法開口要求決鬥了。\n難得「生日」這天不需要什麼理由，就能理直氣壯和別人戰鬥，這樣一來，豈不是和平常日子沒什麼兩樣？\n嘁，去年不應該把他們打那麼慘的。但這也是沒辦法的事情，畢竟從這顆星球誕生前，我就在不斷磨煉自己的劍技，尋常人無法承受，也是理所當然的。\n不過，你和他們不同，你可是守密人啊！\n所以你知道我想說什麼吧？還是去年那個地點，讓我們痛痛快快打一場吧。這次，不會有人打擾我們的戰鬥了。\n\n蘿坦"
  },
  Mail_126937_Name = {
    Text = "唯一的對手"
  },
  Mail_126937_Sender = {Text = "蘿坦"},
  Mail_126938_Desc = {
    Text = "最最最親愛的主人：\n\n您聽說了嗎？今天市長豪宅會舉行一場超豪華的舞會，所有紳士淑女都以能參加這個舞會為榮。\n當然啦，作為女僕，珈倫沒有資格參加。但是您，彌薩格守密人，我親愛的、最親愛的主人，您配得上世界上一切美好的事物，當然也配得上這次舞會。\n所以珈倫已經替你接受邀請啦，還貼心地為你叫了馬車，打點好了一切，到時候你只需要和珈倫一起前往市長家就可以了~\n珈倫會穿上自己最漂亮的衣服，帶上自己最閃耀的首飾，讓大家都見識到萬能女僕的厲害，為您長臉，為您增光！\n啊，當您看到這封信時，我應該已經在您的門外等候了，那些馬車啊，送來新衣服和首飾的僕人啊，也已經就位，唯一的小問題就是，這些服務還未付帳……\n但我最善良可愛的主人絕不會為這些小事而煩惱，對不對？市長還在等著我們呢~\n\n您最可愛、最耀眼的女僕\n珈倫"
  },
  Mail_126938_Name = {
    Text = "豪華舞會"
  },
  Mail_126938_Sender = {Text = "珈倫"},
  Mail_126940_Desc = {
    Text = "守密人守密人！前幾天，詹金說她找到了和奧瑞塔家很像的地方，好像叫做水……唔，奧瑞塔忘記了。\n總之，詹金說那裡會有海豚、小魚、水族館和好多好多水母，還說它們都願意成為奧瑞塔的朋友哦！\n奧瑞塔喜歡朋友，奧瑞塔想要很多很多朋友，所以奧瑞塔想在生日的時候，邀請自己最喜歡的朋友，也就是守密人一起去。\n快點收拾東西和我出發吧，奧瑞塔已經等不及了。\n\n想要認識很多很多新朋友的奧瑞塔"
  },
  Mail_126940_Name = {
    Text = "水族館的新朋友！"
  },
  Mail_126940_Sender = {Text = "奧瑞塔"},
  Mail_126941_Desc = {
    Text = "守密人：  \n\n謝謝您今日凌晨陪我在海邊散步，那些拍擊的海水，明亮的星空，都令我感覺心安，也會令我想起了……很久很久以前的事情。\n那時候，船員們禁止與我交談，所以大多數時間裡，我只能眺望不斷變化的海面，和盤旋在空中的海鳥。海員們望著那些海鳥飛翔的樣子，會無意識向我許願。\n偶爾，他們想要化為飛鳥，飛回家鄉，飛回所愛之人的身旁；偶爾，他們想要航行快點結束，用船上的貨物，換取富足的錢財；偶爾，他們也會祈禱遇到浪漫的愛情，或是邂逅傳說中的海妖人魚……\n但無論是多麼繁雜的願望，到了深夜也會變得統一，化為安眠的渴望。這時候，我會回應他們的祈望，令海風平和，令海水溫柔。\n所以，如果守密人你也難以入眠，請不要凌晨再在海邊獨自徘徊，而是來尋找我吧。\n我想要分擔您的壓力，成為一個有用的人，而庇護你安眠，就是現在我所能做到的。\n這也是……我於這特殊的日子許下的「願望」。\n\n希萊斯特"
  },
  Mail_126941_Sender = {
    Text = "希萊斯特"
  },
  Mail_126942_Desc = {
    Text = "承命運洪恩，彌薩格大學守密人，賢明仁德之主君：\n\n萬安！\n寫這封信時，我一直在猶豫，但誠實亦是騎士的美德之一。作為主君的騎士，我需對您獻出全部的忠誠，絕無隱瞞，故我也必須對你說實話——\n在生日這一天，主君，我請求您來到我的房間，為我閱讀睡前故事。\n請允許我……靠在主君的身邊，在您所講述的那些夢幻而美好的故事中入眠。\n其實，這曾是我幼年時的期願之一。但騎士的訓練容不得一刻怠惰，我也早已過了聽故事的年紀，所以，我一直將它埋在心裡，從未訴之於口。但您……主君您是不同的，我不想對您隱瞞什麼……\n如果主君您覺得不妥，也請告知於我。從此我不會再提出這樣過分的請求，加倍刻苦訓練。\n等待您的回復。\n\n奧吉爾"
  },
  Mail_126942_Name = {
    Text = "騎士的請求"
  },
  Mail_126942_Sender = {Text = "奧吉爾"},
  Mail_126943_Desc = {
    Text = "小煤球：\n\n今天，莫絲，生日！\n朋友說，生日，寫信，給小煤球，小煤球，會來，玩！\n莫絲，不會，寫信。但是，朋友，會！\n朋友，教，莫絲。莫絲，開心！\n其實，莫絲，忘記了，生日。\n但是，莫絲，想跟，小煤球玩！\n所以，莫絲決定，今天，就是生日！\n小煤球，貝殼，收集，金色，白色，都有~\n看到小煤球，開心~朋友，做飯，好吃~\n小煤球，老地方~\n讓朋友，做了，大餐！一起吃！\n莫絲，等你~\n\n莫絲"
  },
  Mail_126943_Name = {
    Text = "生日！來玩！"
  },
  Mail_126943_Sender = {Text = "莫絲"},
  Mail_126944_Desc = {
    Text = "守密人： \n\n前幾日，您說過想要向流星雨許願，所以我特意安排了此次航行。感謝您接受了我的邀請，我會按照約定，準時在海邊等待您的到來。\n請您放心，此次為短期航行，我也已經徹底查清了附近的海域，保證帶領您平安航行到流星雨降落的位置，並協助您獲取隕石。\n這樣，您就可以親手碰觸到流星許願，而在這樣近的距離下，流星也一定會傾聽到您的心願，實現您的心願吧！能夠成為引領您許下心願之人，將是我做過的最特殊的事情之一，我深感榮幸。\n再次感謝您，是您讓我在這個特殊日子找到了新的「領航使命」。請您務必按時赴約，我會一直等候您的到來。\n\n克珀珊特"
  },
  Mail_126944_Name = {
    Text = "觸手可得的心願"
  },
  Mail_129637_Desc = {
    Text = "展信安：\n\n不記得第幾次穿過鐘樓後的花圃時、我曾偶然留意過其中的玫瑰園。\n此後我數次踏過此地、經歷黑池不安湧動的時刻、死亡與對峙的時刻、時序迴流逆轉的時刻、它們都凌然地、靜靜地伫立在那裡、一如既往。\n這一畫面喚醒了不屬於我的記憶中、拉蒙娜曾想贈予你的那捧玫瑰、我也因此稍感安心。\n儘管你我二人遙隔維度、但我始終相信、無論遭遇何種困境、你與那個「拉蒙娜」總能保持冷靜無畏的姿態、找到破局之路。\n畢竟、無論世情如何變遷、玫瑰們總是兀自綻放。\n\n「拉蒙娜」"
  },
  Mail_129806_Desc = {
    Text = "守密人：\n\n海城的宅邸裡、華燈已上。不知您此刻身在何處、身側何人？\n歲初、古國最重要的日子、一個慶賀團圓與新生的節日。這一天、妾身已經歷過許多次、但從未感到過膩煩。寒冬已過、萬物生長、人們是如此地盼望、盼望著能像這片土地一樣、把一切的不堪都拋諸昨日、迎接一個新的開始。\n那些陳舊的傷口與欲念、並非能夠輕易拋棄之物。辭舊、迎新、多麼美好的祝願啊……或許疼痛會重新生長、欲念將永不消逝、可今夜、至少今夜、人們將舉杯歡慶、慶賀一個新的世界、新的自己。\n因此、在舊年與新歲交替之時、人們便以煙火相迎。\n在一切有趣的事物中、煙火是妾身的摯愛之物。所有人都看著它、看它燃燒、升空、綻放、如同仰望神明一般、仰望那短暫的、無與倫比的輝煌。\n您有注意過嗎？在仰望煙火的時候、每個人的心裡都是乾淨的。他們忘記了仇恨、忘記了苦難、忘記了所有的髒污不堪。一切人心都變成寧靜的湖、纖塵不染的湖面上、只有煙火美麗的倒影。\n嘘……不要問煙火之後是什麼。新生或許是種奢求、但、不要因此辜負了它的綻放。\n在所有不堪的事物裡、煙火是最為純淨的東西。今夜、妾身願將自己那份也贈予您。\n抬起頭來、不要眨眼。看著那些璀璨的星辰升起、在煙火綻放的時候、迎接一個新的自己吧、守密人。\n\n「千扇」"
  },
  Mail_129806_Name = {Text = "煙火"},
  Mail_130223_Desc = {
    Text = "尊敬的守密人：\n「顛倒的新生」活動已結束，現將守密人剩餘的「純白鱗粉」、「紅色鱗粉」、「耀光鱗粉」按照每枚兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
  },
  Mail_130223_Name = {
    Text = "鱗粉回收"
  },
  Mail_130223_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_131005_Desc = {
    Text = "親愛的守密人：\n「默斯克斯的呼喚」活動已結束、現將守密人剩餘的「海螺一號」、「海螺二號」、「海螺三號」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_131005_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_131093_Desc = {
    Text = "親愛的守密人：\n「燃燒的盛宴·復刻」活動已結束、現將守密人剩餘的「原生脛骨」、「圓葉菊石」和「螺旋遺蹟」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_131093_Name = {
    Text = "燃燒的群宴貨幣回收"
  },
  Mail_131093_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_131767_Desc = {
    Text = "吾@2！@3乃@2至高@3混@4與毀@2！高呼@4……！\n\n哎呀呀！看看你都幹了些什麼！！！你觸碰到了至高神明的禁忌！這下好了、祂的低語已經響徹你所在的世界、黑色的災難將從你的通訊器開始蔓延、吞沒你身邊的一切……\n小可憐、你的莽撞真的讓我很難辦。但也不用太絕望、不幸中的萬幸、你遇到了我——偉大的教派仙女、神明應選之人、至高之神的代行者、宏大教派的法定繼承者、苦難的解救者、神王的摯友！我是善意與關愛之神的意志、見不得這世間的苦難、我將用我至高無上的力量、拯救每一位愚笨的小搗蛋鬼。\n噢、本仙女看見了你嘲諷的眼神。沒有關係、善神愛世人、從不介意世人的愚鈍。對救世主的不信任、是每一個信徒的必經之路。這些見面禮、便是神的代行者對你的恩賞。\n現在、光明的道路已經為你指明：帶上你的誠意、去到位於@3城的@2大教堂、向善意之神獻上你的忠誠、你便將獲得夢寐以求的力量、從這噩夢的詛咒之中解脫。當然、需要一並獻上的還有你的財富。請不要誤會、善意之神從不在意世俗的回報、但祂的信徒們辦事也是需要花錢的。不要吝嗇這些俗氣的東西、親愛的信徒、一分錢一分貨。\n高呼善意之神的名號、等待著神蹟降臨的時刻吧！\n\n偉大的教派仙女、神明應選之人"
  },
  Mail_131767_Name = {
    Text = "請勿觸碰本@2"
  },
  Mail_132339_Desc = {
    Text = "尊敬的守密人：\n「神王甦醒·復刻」活動已結束，現將守密人剩餘的「疲憊緒思」、「悲愁緒思」、「歡悅緒思」按照每個兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
  },
  Mail_132339_Name = {
    Text = "神王復甦貨幣回收"
  },
  Mail_132339_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_132458_Desc = {
    Text = "尊敬的守密人：\n        感謝您對「忘卻前夜」的支持和認可，為了讓守密人在彌薩格大學有更好的遊戲體驗，誠邀您填寫以下體驗調研問卷。為感謝您的配合，我們準備了「銀芯」× 200 作為獎勵，完成問卷即可領取。問卷截止時間8月17日9：00，請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議，您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_132458_Name = {
    Text = "版本體驗調研問卷V2.5.3"
  },
  Mail_132458_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_132578_Desc = {
    Text = "尊敬的守密人：\n在{s1}賽季的「疾馳的歡愉專列」中，你獲得頭銜為「{s2}」。\n你將獲得以下額外獎勵，請記得查收。"
