  Mail_132605_Desc = {
    Text = "吱吱吱，吱吱吱吱吱！\n（守密人，愚人節快樂！）\n吱吱吱，吱吱！\n（證件照，留念！）\n「雜亂的潮濕海獺爪印」\n「一大堆火漆滴蠟失敗留下的模糊貝殼拓印」\n                                                         ——一個端端正正的海獺爪印落款"
