  },
  Mail_133703_Desc = {
    Text = "尊敬的守密人：\n{s1}版本已結束，已自動將守密人剩餘的「空幻之芯」按照每 1 個兌換「無垢之芯」× 1 的比例進行轉換。本次共轉換了「無垢之芯」× {s2} ，請守密人記得查收。"
  },
  Mail_133703_Name = {
    Text = "「空幻之芯」過期轉換"
  },
  Mail_133703_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_133704_Desc = {
    Text = "尊敬的守密人：\n{s1}版本即將結束，請各位守密人及時使用剩餘的「空幻之芯」，本期學期課題結束後會將守密人剩餘的「空幻之芯」按照每 1 個兌換「無垢之芯」× 1 的比例進行轉換。"
  },
  Mail_133704_Name = {
    Text = "「空幻之芯」過期提醒"
  },
  Mail_133704_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_134024_Desc = {
    Text = "尊敬的守密人：\n「每日試訓」已被移除，現將守密人剩餘的「代理憑證」按照每枚兌換「薔薇金券」× 10000 的比例進行轉換，請守密人記得查收。"
  },
  Mail_134024_Name = {
    Text = "代理憑證回收"
  },
  Mail_134024_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_134067_Desc = {
    Text = "守密人：\n\n今天有件特別的事想和你商量。\n我想隨便在街上走走，就那樣普普通通地看看各種有趣的東西，隨心所欲地到處逛逛，度過平凡的一天。\n\n然後呢，我去問了教務處。結果他們說，出於安全考慮，只有在你陪同的情況下才允許出校。\n還說不要嚇到別人，也不要在外面什麼都往嘴裡塞。真是失禮啊。\n嘛，就是這麼回事，總之能不能出去走走？大家一起哦。\n\n……不知怎的就想到，蒲公英的種子啊，\n總有一天會乘著風，踏上前往自己命運之地的旅途，\n也許就是明天，也許是很久很久以後的事。\n想著想著，就覺得趁現在和大家一起多做些事情，好像也不錯呢。\n\n總之呢，我在宿舍前面等你。拜託啦！\n\n沙耶"
  },
  Mail_134068_Desc = {
    Text = "守密人：\n\n我覺得，今天是特別的一天。但記憶的輪廓，卻還是那麼模糊。\n唯有「沙耶」這個名字，勉強將我牽繫在這個地方。\n\n那種感覺不是寂寞，也不是悲傷，並非那樣鮮明的情感。\n如果硬要給這份心情起個名字的話……大概，會是「空白」吧。\n什麼都沒有，無盡地澄澈透明，靜謐的時光。\n\n如果有一天，乘風飄揚的蒲公英種子，\n在這個世界的每一個角落，只是潔白地、安靜地飄落……\n那時候，我或許終於能夠覺得，這個世界是\"特別的\"。\n\n那時候，瀰漫於倫蒂尼恩的灰色的霧，夕陽時燃燒的火紅的霞，還有你總是在學校廣場裡仰望過的天空，都會被蒲公英所覆蓋，變為純白的顏色。變為屬於我的顏色。\n\n所以……如果，你願意給予我什麼的話。\n那不必是禮物，只是一段\"記憶\"就好。\n\n我，在蒲公英盛放的純白世界裡，\n只是靜靜地，等待著那一刻的到來。\n\n當你某一天再次在彌薩格廣場仰望天空的時候，\n請將掠過視野邊緣的那一縷白色絨毛，\n與曾經和你交談過的我的身影，稍稍重疊在一起吧。\n\n沙耶"
  },
  Mail_134068_Name = {
    Text = "蒲公英的約定…"
  },
  Mail_139809_Desc = {
    Text = "尊敬的守秘人：\n        感謝您對「忘卻前夜」的支持與認可，為了讓守秘人在彌薩格大學有更好的遊戲體驗，誠邀您填寫以下體驗調研問卷。為感謝您的配合，我們準備了「銀芯」× 200 作為獎勵，完成問卷即可領取。問卷截止時間5月16日9：00，請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聆聽每一位守秘人的建議，您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
