  Mail_141372_Desc = {
    Text = "尊敬的守密人：\n「永遠的厄波揚斯」活動已結束，現將守密人剩餘的「新鮮的」獵物「」「碩大的」獵物「」「古老的」獵物「」按照每枚兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
