  },
  Mail_141372_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_141470_Desc = {
    Text = "尊敬的守密人：\n「鏡像囚徒·復刻」活動已結束，現將守密人剩餘的「常識之書」、「數理之書」、「文學之書」按照每枚兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
  },
  Mail_141470_Name = {
    Text = "鏡像囚徒貨幣回收"
  },
  Mail_141470_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_141507_Desc = {
    Text = "守密人：\n\n誕生之日，於你而言，這或許是一個重要的日子吧？\n於我而言，命運之網上每一天的重量都是均等的。是其他的故事，為這個日子賦予了特殊的意義。\n我在這一天誕生，在這一天領悟預言，在這一天得到編織命運的紡輪，在這一天看到那些繁複的命運絲線、還有絲線盡頭的噩夢。\n對命運的編織者，這一天碌碌無奇。對舞台上的演員，這一天值得慶賀。而在所有的身分裡，更令我歡悅的，是作為演員的自己。\n守密人，今日，命運劇院的燈光皆已熄滅，只有一個舞台燈火輝煌。你曾提到過，想要更多的看到我曾經歷過的命運。而現在，這座舞台將要上演的，便是一段關於我自己的故事。\n我並不知道它將要上演的是哪一段。我將回憶送上舞台，她將在那些強烈的時刻中，選擇一段你最期待看到的，在今夜的舞台上呈現。\n那故事或許令我痛苦，或許令我難堪，但這些並不重要，不是麼？我想，偶爾讓紡輪自己編織，做一個純粹的觀眾，是一件令人愉悅的事。\n這場演出唯一的入場券，現在已經在你的手上。帶著這封信件前來吧，守密人。今夜，一段再無他人知曉的故事，等待著你的到來。\n\n阿拉克涅"
  },
  Mail_141507_Name = {
    Text = "隱秘的故事"
  },
  Mail_141833_Desc = {
    Text = "尊敬的守密人：\n「新月與深雪」活動已結束，現將守密人剩餘的「紅蘋果」、「金蘋果」、「糖蘋果」按照每枚兌換「薔薇金券」× 40 的比例進行轉換，請守密人記得查收。"
