  },
  Mail_142101_Desc = {
    Text = "好久不見，%player%：\n\n當你收到這封信的時候，我應該正經過亞格羅的上空，每年的這個月，我的巡獵旅程總是會更遠一些。\n沒有什麼比敵人的慘叫和痛嚎更適合作為生日配樂了，何況我準備了足夠的牢籠，只要還有蠢貨敢信奉那些除了痛苦，不會帶來任何救贖的偽神，無論天涯海角，我都會讓他們意識到自己的錯誤。\n偶爾，在魘穿過雲層，能夠看見月亮的時候，確實會有些荒唐的念頭從我腦海裡一閃而過。\n比如這種時光會在何時突如其來、無可違逆地被迫停止，就像生活當初毫無徵兆地陷落一樣。\n不過隨後我就會被自己逗笑，當我踏入它的那天，我就在一條沒有退路的征程上，我相信你一定明白我的意思，小朋友。在這個世界上，沒有比你和我境況更相同的人。\n我們都選擇了一些沒有選擇的選擇，好消息是，我們都很享受自己的選擇。\n新的一年，只要吹響我送給你的獵哨，我依然會隨時出現在你身邊。\n當然，如無意外，還是先讓我專心享受這趟旅程吧，下個月，我會帶給你紀念品和一些新的見聞。\n祝你一切順利，祝你快樂。\n\n你親愛的「舅舅」"
  },
  Mail_142101_Name = {Text = "見聞"},
  Mail_142101_Sender = {
    Text = "你親愛的「舅舅」"
  },
  Mail_143935_Desc = {
