  },
  Mail_146401_Desc = {
    Text = "曆法是一種無聊的發明。所有日子都沒有什麼區別，包括今天。\n按照你們的曆法，今天是我誕生的日子。誕生這個詞對我而言不算準確。我是一塊從混沌中被撕扯出來的殘骸，在無數場戰鬥中磨礪成形的刀刃。鑄就我的不是母體，是每一個曾與我交鋒的對手。而你，是他們中至關重要的一位。\n你們很重視這樣的日子。宴會，禮物，祝詞——我不需要這些。\n我只需要一場戰鬥。\n這段時間以來，你做過許多不可思議的事情。但我知道，你所展示出的，還遠遠不是你的極限。\n今天黃昏，訓練場。帶上你的武器，我會在那裡等著你。不必在意勝負，不必顧慮傷亡。劍刃毫無保留相撞的那一刻，是我唯一期待的賀禮。讓我看看，一塊@4的碎片，究竟能做到些什麼。\n我想，你會讓我感到驚喜的，我的「對手」。"
  },
  Mail_146401_Sender = {
    Text = "蝕滅·蘿坦"
  },
  Mail_146873_Desc = {
    Text = "親愛的守密人：\n「臨時文本」活動已結束、現將守密人剩餘的「臨時文本」、「臨時文本」、「臨時文本」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
