  Mail_148478_Desc = {
    Text = "尊敬的守密人：\n        在第 {s1} 期「學期課題–高階課題」中獲得的獎勵尚未領取，現以郵件的附件將未領取的獎勵發放給您，注意及時清理背包後領取。"
