  Mail_148478_Name = {
    Text = "{s1} 期高階課題未領取獎勵補發"
  },
  Mail_148478_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_148514_Desc = {
    Text = "尊敬的守密人：\n        在 Ⅴ1.4.3.5 版本更新中，我們於「異夢視界：褻瀆」新增了關卡「新王」。由於部分守密人未及時知悉這一更新內容，誤以為「異夢視界：褻瀆」已全部通關完成。\n        為此，在本次 Ⅴ2.6.2 版本更新中，我們已為更新前已通關「新王」後續關卡的守密人補齊「新王」關卡的通關進度，並同步補發相應的首通獎勵，請查收。"
  },
  Mail_148514_Name = {
    Text = "「褻瀆」進度補齊"
  },
  Mail_148514_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_148515_Desc = {
    Text = "親愛的守密人：\n\n嗒哒~是不是出乎預料呢？這是本仙女在彌薩格的第一個生日，所以——\n居然！沒有任何促銷郵件、禮拜邀請，甚至連末日預言也沒有~\n不過不必失望，本仙女當然是有給最特殊的教徒準備一些更珍貴，更好的福利啦。\n作為千星熔解的仙女教母，當然能夠預料到那些理所當然的疑惑和防備，雖然那會讓本仙女感到些許傷心難過，不過，為了普及教派的福澤，輕微的犧牲總是在所難免。\n所以，請退一萬步思考，來試一試嘛，反正也不會有什麼損失，萬一是真的呢？對不對？\n這可是一年僅一次，無論如何都不該錯過的機會哦~\n不需要任何供奉，也不需要任何許諾與交換，僅僅只需要與仙女教母共進一場甜蜜的下午茶，您就能夠得知冰雪之下，到底埋藏著多少對您真摯的感情。\n這難道不是一個具有誘惑力的提議嗎？\n備註：請務必攜帶足夠用於買單的至少10、100、1000雷歐坊，多多益善。\n\n在那家我們都知道的店等待著您的\n卡拉布"
  },
  Mail_148515_Name = {
    Text = "☆☆☆超級福利郵件☆☆☆"
  },
  Mail_149949_Desc = {
    Text = "此信已在陰陽兩界流轉千遍，切勿刪除！\n\n七月半，鬼門開，陰風起，幽魂歸。\n吾乃磐龍古國扈城■■■，一紙陋是也！\n奉中元敕令、持招魂符牒，今夜降咒於此。見字之人，魂將入冊，名已上簿，若不在子時前轉與五十位陽世之人，必將——\n文書臨存檔前一息崩壞……\n啵啵奶茶必短三顆珍珠……\n銀芯通訊器電量永遠卡在1%，充之不盈……\n\n乖乖照做，咒自解，符自焚，厲鬼不纏，燈亦長明。\n轉發！！立刻！！！"
  },
  Mail_149949_Name = {
    Text = "【中元警告】膽敢刪信者，必遭……"
  },
  Mail_149949_Sender = {Text = "一紙靥"},
  Mail_149985_Desc = {
    Text = "主君：\n\n唐突來信，希望不會令您感到冒昧。但有些心事，只有對您才能傾訴。\n昨夜，我久違地做了一場夢，在夢裡，我回到了舊日的家中。一切都那麼親切，父親溫柔寬厚的手掌，女傭在清掃時哼出的鄉野歌謠，還有那匹屬於我的白色矮種馬......我本以為，它們早已被我遺落在記憶的泥沼，重新在夢中見到，還是那樣的溫暖。\n醒來後，我看見窗外彌薩格的師生正閒聊著路過，如此寧靜美好，一時間竟讓我覺得，這幅畫面和夢裡也沒什麼不同。 同時，我還發現，那附著在我身上的無形之物，自今晨起一直十分安靜。難道說，生日這天真的會遇上些幸運的事嗎。\n若當真如此，或許，我也可以在今日貪心一次......\n我知道人們往往喜歡在生日當天許願，作為對一整年的期許。我早已不敢奢望獲得誰人的生日祝願，但的確有一個想要獲得的機會。\n正如主君將信任交付給我一樣，我也不會對您有所保留，因此，請准許我將願望告知與您：\n如果下次主君有任務安排的話，請任命我為護衛，與您同行吧。\n無論如何，我希望在您最需要幫助的時候，永遠能第一時間擋在您的身前，成為您最堅實的護盾。\n這便是我為今年許下的心願。\n\n奧吉爾"
  },
  Mail_149985_Name = {
    Text = "生日願望…"
  },
  Mail_149985_Sender = {
    Text = "負誓·奧吉爾"
  },
  Mail_18019_Desc = {
    Text = "親愛的守密人：\n系統檢測到當前賬號進行了一次退款行為。製作組已於{s1} 根據您的退款訂單對應的虛擬貨幣部分進行了扣除。若相應貨幣在扣除後出現負數，則需要恢復為正數後才能正常適用。\n如有疑問請和客服聯繫。"
