  },
  Mail_20231_Desc = {
    Text = "親愛的守密人，相位對弈的新賽季開始了，您的段位從 {s1} 重置為{s2}。新賽季段位獎勵已重置，可通過提升段位獲取更多榮譽與獎勵！{s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "相位對弈賽季郵件"
  },
  Mail_20231_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_21453_Desc = {
    Text = "親愛的守密人：\n\n冒昧打擾，不知您最近還好嗎？\n抱歉在百忙之中打擾您，詹金他們給我準備了一個小型生日宴，我想了很久很久，還是決定自己來給您送出這封邀請函。\n工坊收留的孤兒大多記不住自己的出生日期，莎拉小姐就把我們出現在孤兒院的日子定為我們的生日。只有我不一樣，莎拉小姐說，我是在一個極度寒冷的冬夜被丟在濟貧院門口的，她想要我的一生不再冰冷蒼白，所以選了一個溫暖的日子作為我的生日。所以，這是一個我的、被關心被愛護著的日子。這對我來說是重要的一天，我希望守密人也能來與我一同度過，這是我的一個小小心願。當然，不能被滿足的話也沒關係，因為守密人有很多事情要處理，艾繼絲知道的。\n如果這份邀請給您添了任何麻煩，請您一定要告訴我，並接受我誠摯的歉意。但如果、萬一您真的能騰出時間來的話，也非常非常歡迎您來參加他們的胡鬧，說不定、有可能會非常有趣，畢竟是詹金準備的嘛。\n\n艾繼絲"
  },
  Mail_21453_Name = {
    Text = "百忙之中打擾…"
  },
  Mail_21453_Sender = {Text = "艾繼絲"},
  Mail_21454_Desc = {
    Text = "喂：\n我一直搞不明白，出生的日子到底有什麼好值得慶祝的？值得大家如此大動干戈？\n去年的今天，有個學生來問我的生日日期。笑死人了，我誕生那時，這個星球上還沒有時間的概念，更別提生日了。但她纏得我實在沒辦法，我就告訴她「是晝夜交匯平分的時候」，也不知道她最後是怎麼理解的。\n寫這封信，是為了提醒你，今晚12點後記得把我房門口那些花收起來，熏死人了！\n\n蘿坦"
  },
  Mail_21454_Sender = {Text = "蘿坦"},
  Mail_21455_Desc = {
    Text = "艾瑞卡今天送來了一大包咖啡，說是我的生日禮物，還說裡面是你今年一整年的配給。<Del:但 你是自願的嗎 如果不>\n 如果這是朵爾還是誰給你做的惡作劇，那雖然很捨不得，我還是可以把它……還你。畢竟那可是咖啡！我少喝兩杯都困得不行，一整年不喝？你怕不是會睡得和圖魯一樣。倒不是說他不好，就是，黑色的東西會在夜裡出現……總之，如果你需要的話，隨時可以將咖啡拿回去，當然如果你把咖啡留在這裡，<Del:我也 那就>我想我會非常高興的。這樣我就終於可以做我想做的那個實驗：將咖啡因提取並濃縮成可以通過表皮吸收的藥劑，貼在身上一直保持清醒，一直一直……\n\n\n很希望進行這個實驗的溫柯爾"
  },
  Mail_21455_Sender = {Text = "溫柯爾"},
  Mail_21456_Desc = {
    Text = "生日？\n非要說的話，我的生日可不是什麼好日子。成百上千個無辜的生命在這一天死去，就為了讓我「出生」，然後去殺死更多的人。\n所以，這一天也沒什麼值得慶祝的。不過我明白你們人類都是很注重「儀式感」的生物，剛好我手上有一筆錢——放心，是我在鱒魚俱樂部出賣汗水賺的辛苦錢，不是什麼非法收入。\n收下這筆錢，拿去給自己買個禮物吧，就當是慶祝我的生日了。\n\n尤烏哈希"
  },
  Mail_21456_Sender = {
    Text = "尤烏哈希"
  },
  Mail_21457_Desc = {
    Text = "守密人：\n\n在彌薩格地界內，存在慶祝生日的習俗嗎？\n我那記憶中的故國……每年都會舉辦盛大的儀式，以慶祝王的誕辰。\n久而久之，「生日」的特殊意義就被賦予了所有人。\n在久遠的過去，每逢生日這天，同僚與親友們都會不遠萬里來到我身邊。\n那被親愛的人們簇擁圍繞的感覺……那如同被太陽擁抱著的溫暖……也許正是我無法割捨過去的原因吧。\n啊……扯遠了，我打擾到您工作了嗎？\n我準備了一些過去常用的茶點，想要與您分享。\n如果您願意賞光，請在晚飯後來找我吧。\n\n法洛思"
  },
  Mail_21457_Name = {
    Text = "不滅的光…"
  },
  Mail_21458_Desc = {
    Text = "今天確實是個值得紀念的日子：這一天，偉大的戈利亞之主、巨人之王降臨於世；這一天，海洋為之震顫，星辰為之失色。\n聽說校園裡不允許鋪張浪費，那就按以往規格的十分之一來操辦我的生日晚宴吧——十份烤乳豬、一百串烤章魚以及能演奏戈利亞民謠的樂隊，對了舞女最好也給我來一打……\n什麼，這些都不被允許？\n那就只要舞女吧……不用一打，四五個就夠了。\n什麼，這也不允許？！\n這樣寒酸的規格可配不上我的身分。現在我宣佈，晚宴計劃取消！\n\n戈利亞"
  },
  Mail_21458_Name = {
    Text = "晚宴計劃……"
  },
  Mail_21458_Sender = {Text = "戈利亞"},
  Mail_21459_Desc = {
    Text = "守密人——\n\n今天在茜爾維婭女士那邊做記憶訓練的時候，她問起了我的生日。你也知道我的，剛剛放下的扳手我轉頭就能忘了，怎麼可能記得生日！更嚴重的是，這還是一個只有我知道的東西，我！這生日算是沒啦。\n\n不過薩爾瓦多神父說具體的日期不重要，重要的是我慶祝什麼每一天什麼的，所以我決定了，今天就是我的生日！我已經和一個人（我忘了是誰了，應該不是你吧，守密人？）約好了在食堂門口舉辦派對，你可一定要來哦！\n\n\n\n絕對絕對會記得這個生日日期的諾締拉\n\n\n\n一張和信一起送來的紙條：\n\n那孩子寫完信就風風火火地走了，把信和一些說是要給你的禮物都忘在了桌上。\n東西我都附在信封裡了，期待晚上和你在派對上相見。放心吧，我會提醒她今晚到場的。\n\n——茜爾維婭"
  },
  Mail_21459_Name = {
    Text = "我決定的生日！"
  },
  Mail_21459_Sender = {Text = "諾締拉"},
  Mail_21460_Desc = {
    Text = "小傢伙： \n\n原質之海中沒有星辰日月，也沒有四季交迭，因此，我的生日應當被記載為【不明】。\n但今天的確是個重要的日子，畢竟，這副形貌還是繼承自某個懷有「心願」的人類的。她喜歡熱鬧，所以開設了這間小店，但又因為四處調查，她的生日往往都是由我一人陪伴。為了圓她生前的心願，解憂小鋪今天將會舉辦燭光餐會，誠邀各位忠實客戶到場。\n當然，解憂小鋪也會為所有光臨者提供一個小小的折扣，還請小傢伙不要錯過。\n\n達芙黛爾"
  },
  Mail_21460_Name = {
    Text = "人間心願…"
  },
  Mail_21460_Sender = {
    Text = "達芙黛爾"
  },
  Mail_21461_Desc = {
    Text = "當年被從家人身邊帶時，養母…執政官夫人把寫著我出生的陶片摔得粉碎，把我曾為提洛人的過去摔得粉碎。真正的生日，自然已經無從說起了。\n拉伊一別後，我也思考了一番……如果把我逃離牢籠、開始復仇的那一夜作為我的「生日」，你覺得如何？\n雖然現在已經沒有紀念年長一歲的必要，但作為時間更迭的一個提示，似乎也不錯。"
  },
  Mail_21462_Desc = {
    Text = "測試，測試。\n尊敬的守密人，你好。如果你收到此封信件，說明你的意見對艾瑞卡而言至關重要，並被選中參與自動人偶艾瑞卡的語言模組功能年度檢測與維修計劃。本次評估以簡答題的形式進行，需要你對自動人偶艾瑞卡最新安裝的EA-L-1033號語言模組進行功能評價，不會佔用你太多時間，還請你不必緊張和驚慌。\n簡答題：\n請問你是否看懂了本封信的大意？\n\n請將回復直接填寫在簡答題下方的空白處，並將信件重新裝回信封。\n感謝你的參與。\n\n艾瑞卡"
  },
  Mail_21462_Name = {
    Text = "測試，測試……"
  },
  Mail_21463_Desc = {
    Text = "守密人：\n\n你是這所學校裡難得清醒的人，你的目光能夠穿透這殘缺之身，看見真實的我。\n這樣的你，一定能向那些小孩解釋清楚：我不是什麼美人魚，此身終蹈海越山，成就完美之軀。\n……算了，也不為難你。但至少今天，不要讓他們玩我的尾巴了。\n今天的日子，算得上特殊。如果你有時間，我會有些事想親口說給你聽。\n\n凱刻斯"
  },
  Mail_21463_Name = {
    Text = "完美之軀…"
  },
  Mail_21463_Sender = {Text = "凱刻斯"},
  Mail_21464_Desc = {
    Text = "守密人：\n\n我在俗世意義中的生日，是父親當初收養我的日子。\n過去他總是格外重視這天，每年都要大辦舞會——穿著束腰跳舞，可比揮劍三千次還要累。\n但這是他身為父親的心意，我不希望辜負這份來之不易的愛。\n不過今年，他終於答應讓我自己安排生日行程了。也許在父親眼裡，我已經不是需要放在眼皮下看顧的小孩了。\n對了，你能陪我去鐘樓頂嗎？聊聊天，吹吹風。\n聽說，今夜會是個滿月夜。\n\n拉蒙娜"
  },
  Mail_21464_Name = {Text = "滿月…"},
  Mail_21465_Desc = {
    Text = "親愛的、最親愛的主人：\n是的沒錯，今天就是珈倫@1歲的生日了哦（女士的年齡要保密）！\n為此珈倫準備了一場無與倫比的盛大派對，還邀請了所有能邀請到的小夥伴~！雖然最後答應來的只有奧瑞塔、奧吉爾和莉莉……\n不過沒關係，有人的地方就有派對，有派對的地方就有珈倫！珈倫為此還精心準備了「改良版」蟾蜍燉菜、蒜香泥煤蛞蝓以及咖喱蝙蝠湯，主人一定要來嚐嚐哦~\n\n悄悄問一句，主人一定準備了禮物給珈倫吧？記得要亮閃閃的喲！\n\n您永遠謙卑的女僕\n珈倫"
  },
  Mail_21465_Name = {
    Text = "禮物……"
  },
  Mail_21465_Sender = {Text = "珈倫"},
  Mail_21466_Desc = {
    Text = "親愛的<Del:守密人>西區佬：\n這是一封<Del:邀清喊 要請漢 邀請喊 邀請>總而言之是請你來吃免費蛋糕，順便慶祝我的生日！其實也是為了感謝你之前幫我找到姐姐，還把我帶到這裡來，給我和布朗一個可以安心待著的地方。\n（上面這些是艾繼絲要我寫的，可肉麻了。我們之間的交情可用不著這些，對吧，守密人？）\n總之，今晚在你宿舍後面的院子裡，我、布朗和艾繼絲親手準備了一些好東西，等著你來一起分享！當然其實主要是艾繼絲在做，她做東西可好吃了，廚房裡的太太們都誇她有天賦呢，你要是不來的話，保管你後悔。\n\n你的老夥計詹金和布朗"
  },
  Mail_21466_Name = {
    Text = "親愛的西區佬…"
  },
  Mail_21467_Desc = {
    Text = "守密人：\n\n在人們還在神的國度里居住時，我們就已經開始用舞蹈表達自己的情感——狂歡的旋轉，悲慟的步伐……有人說舞蹈的歷史與人類的歷史一樣漫長，它見證了我們的輝煌，也見證了我們的頹喪。\n\n我曾說過我不會再舞蹈，但……我畢竟是為舞蹈而生的。所以，僅是今天，你願意與我一同起舞嗎？與我沉浸其中，感受軀體最深處的律動。\n\n我會在舞蹈室等你。\n\n\n\n莉茲"
  },
  Mail_21467_Name = {
    Text = "共舞的邀請"
  },
  Mail_21467_Sender = {Text = "莉茲"},
  Mail_21468_Desc = {
    Text = "尊敬的守密人：\n\n在我還沒成為喚醒體前，我的生日都是和戰友從軍營外帶酒進來，躲在堆放物資的帳篷裡就著配給的黑麵包偷偷慶祝，然後在被長官發現前把瓶子扔到外面的草叢裡。\n\n但彌薩格不是軍隊，在這裡，我們可以盡情放縱。不知你是否願意與我分享一瓶佳釀，一同慶祝我的生日呢？\n如果你願意的話，在今晚月亮越過鐘樓的時候，到宿舍的天台上來吧。不知道你是否注意過，那裡有著全彌薩格最好的景色。\n\n\n\n艾爾瓦"
  },
  Mail_21468_Name = {
    Text = "分享佳釀……"
  },
  Mail_21468_Sender = {Text = "艾爾瓦"},
  Mail_21469_Desc = {
    Text = "海灘海灘海灘海灘！\n欸？信件開頭要寫收件人——好麻煩！明明守密人在冰箱上貼的便籤都不寫收件人！\n今天是奧瑞塔的……誒……多少歲生日來著？總之是奧瑞塔的生日！\n這些是奧瑞塔的寶藏！都給你！帶奧瑞塔去海灘玩吧，拜託拜託拜託了！\n就當、就當是給奧瑞塔的生日禮物吧，好不好嘛~\n\n奧瑞塔"
  },
  Mail_21469_Name = {Text = "海灘！"},
  Mail_21469_Sender = {Text = "奧瑞塔"},
  Mail_21470_Desc = {
    Text = "貴人：\n\n過去與姐姐在荒星時，我們總是擁抱著，吸食著同一株植物的能量，以此作為我們誕生的紀念。\n那些日子雖然苦澀，可如今想起來，也不免感到歡欣與溫暖。\n今天又是紀念我們誕生的日子，如果可以的話，我能用一首歌來交換一段枝條嗎？\n一段甜蜜的，能夠代表我與姐姐的過去，能夠代表我與您的未來的枝條……\n\n汀克特"
  },
  Mail_21471_Desc = {
    Text = "承命運洪恩，彌薩格大學守密人，賢明仁德之主君：\n萬安！\n前幾日，我見有貨車出入學校馬廄，竟是送來了一匹溫血馬。想起上次與主君執行調查任務時，您曾說自己沒有過策馬的經歷。溫血幼騍最是溫順，讓初學者適應馬背是最適合不過。\n乘著馬，追逐黎明與黃昏，那是我記憶中最愜意的片段。若主君垂信，願與我同騎，我想將這份愜意分享於您。\n\n奧吉爾"
  },
  Mail_21471_Name = {
    Text = "溫血馬…"
  },
  Mail_21471_Sender = {Text = "奧吉爾"},
  Mail_21472_Desc = {
    Text = "舊國曆法，與倫蒂尼恩今日所行大不相同。\n余出生在第二個夏月的第五個滿星日，選在今日慶賀，乃實驗室負責人測算之結果。\n舊國尚存時，主祭會操辦一切。大興祭祀後，便是舉國歡慶，進入長達七日的假期。\n雖非余所求，但余亦沒有理由阻止歡愉的蔓延。\n今日並非彌薩格的公休日，守密人的職責也注定了你不會有規律的休息日。\n但，若以為余祝壽為由申請假日，想來管理處也不敢有微詞。\n度過一個閒適的午後吧。\n\n圖魯"
  },
  Mail_21472_Sender = {Text = "圖魯"},
  Mail_21473_Desc = {
    Text = "守密人：\n\n奧瑞塔說，壽星都是要許願的。\n而我恰好是一個從不許願的人。\n因為我的想法總能實現。這並非幸運，而是更像某種……命中註定的指引？\n就像上個月隨希萊斯特出海時，我又「恰好」拾到了一塊美麗的化石。\n當地居民都叫它「海百合」。它的手腕就像風車一樣迎著水流，正慵懶地享受著夏日午後的太陽。\n脆弱、美麗。看到它時，腦海中很自然地浮現出了你的模樣。\n這次我依然沒有許願——\n你一定會喜歡的，對吧？\n\n珊"
  },
  Mail_21475_Desc = {
    Text = "守密人：\n\n過去與埃爾頓航行時，他會在每年的這天做一桌菜，並想要我「許願」。\n來到這裡前，我不理解「願望」是什麼。現在，我不知道我能有什麼「願望」……\n或許，找到「願望」，也可以作為「願望」嗎？\n\n希萊斯特"
  },
  Mail_21475_Name = {Text = "願望…"},
  Mail_21475_Sender = {
    Text = "希萊斯特"
  },
  Mail_21476_Desc = {
    Text = "守密人：\n\n奧瑞塔告訴我，你會實現所有在生日時許的願望，是嗎？\n應該不會是真的吧？要實現所有人的願望，也太麻煩你了。\n不過，如果能許願的話……我想讓汀克特能有更廣闊的舞臺。\n會太難實現嗎？唔……那、那換成，「接下來一年裡，我的餐桌上不會再出現西芹」，可以嗎？\n\n菲茵特"
  },
  Mail_21476_Name = {Text = "願望…"},
  Mail_21477_Desc = {
    Text = "親愛的守密人：\n\n告訴你一個秘密：這個生日其實是假的。至於我真實的出生年月……就讓它消散於風中吧。\n生病以後，哥哥總會在生日的那天，讓管家偷偷為我準備一個小蛋糕。\n沒有生日歌，也沒有祝福，就好像過生日是一件可恥的事。\n現在，一切都不同了，我可以走在陽光下，可以大聲唱歌，還可以過生日。\n這只是一些微小的快樂，卻令我感到懷念。\n謝謝你，守密人。\n\n（當然，如果您和大家都能對我粗暴一些、再粗暴一些……就更完美了。）\n\n雷婭"
  },
  Mail_21477_Name = {
    Text = "一個秘密……"
  },
  Mail_21477_Sender = {Text = "雷婭"},
  Mail_21478_Desc = {
    Text = "我的小·囚·犯：\n\n我已經好久·好久·好久沒有揮動鞭子了——\n被困在這所無趣的學校裡，被困在校服裡，潘狄婭的心裡癢癢的，就好像有調皮小貓在抓撓一樣。可非但沒人理解我，那些職工還千方百計阻止我「找樂子」——真是太過分了!\n哎呀，今天可是個特殊的日子，很適合讓我的鞭子再接觸到柔軟的肌膚，讓我聽見疼痛的吟唱……如果今天你有空的話，不如，來找我聊聊天吧~？\n\n潘狄婭"
  },
  Mail_21478_Name = {
    Text = "鞭子的聲音…"
  },
  Mail_21478_Sender = {Text = "潘狄婭"},
  Mail_21479_Desc = {
    Text = "<Big:魔法大師卡茜亞的週年紀念演出，只在今天！>\n\n為了感謝各位觀眾多年來的支持與鼓勵，為了回饋各位觀眾在過去給予的所有快樂，魔法大師卡茜亞決定在今天晚間8點整，於彌薩格大學中庭（菲力浦斯雕像旁）進行特別週年紀念演出！今晚，你將見到比以往更絢爛的舞臺，更刺激的演出，以及——也是最重要的——更神通廣大，讓你不能相信自己的眼睛的華麗魔法！即使是彌薩格之腦親臨現場，也將被這超乎想像的魔法所折服，這是來自卡茜亞大師的保證！\n\n機會難得，僅在今晚，且完全免費！卡茜亞大師與你不見不散！\n\n<Small:PS:演出期間或之後若出現精神萎靡，心情低落等症狀，卡茜亞大師概不負責。>\n<Small:PPS:任何與彌薩格之腦相關宣傳皆以屆時實際情況為准，卡茜亞大師保留對節目及節目效果的所有解釋權。>"
  },
  Mail_21479_Name = {
    Text = "魔法大師卡茜亞的週年紀念演出！"
  },
  Mail_21479_Sender = {Text = "卡茜亞"},
  Mail_21480_Desc = {
    Text = "喂，今天可是我的生日，禮物呢？\n什麼，你忘記準備了……？哼，我就料到會是如此。\n喏，這本日曆你拿著，上面清清楚楚地寫了我的生日、我的忌日、第一天來彌薩格的紀念日，還有嬉樂節、農神節……的日期，這些節日我們都要一起過的，總之下次可別忘了！\n\n如果你又忘了的話……我好像也不能把你怎麼樣，哼。\n總之還是不准忘了。\n\n阿格里帕"
  },
  Mail_21481_Desc = {
    Text = "守密人：\n\n我本不想寫這封信，但艾瑞卡的運行似乎出了問題，在我寫完這封信前，她的警報響個不停。\n生日於我而言是一個無意義的日期，實驗的成功率並不會比其他日子更高，我的諾斯指數也不會因這個日期產生任何變化。但拉蒙娜執意要讓這天成為我的「休息日」，並限制了我今天進入實驗室的權限。\n我無處可去，為此，今天我會對你過往的報告進行全面審查。\n請在晚餐後來一趟檔案室。注意，不要試圖將任何蛋糕帶入檔案室，紙質檔案是非常脆弱的。\n\n朵爾"
  },
  Mail_21481_Name = {
    Text = "晚餐後…"
  },
  Mail_21481_Sender = {Text = "朵爾"},
  Mail_22435_Desc = {
    Text = "親愛的守密人：\n最初選擇在晨光熹微的校園中讀詩，是因為覺得這個時間段的行人更少，更容易沉浸在詩歌的世界中。後來，我也慢慢愛上了清晨矇矇亮的天色，晶瑩剔透的露水，與清脆婉轉的鳥鳴。\n讓我沒想到的是，竟然有許多師生在默默地關注著我，並私下裡組成了詩歌同好會。今日是我的生日，恰逢同好會的水仙花含苞待放，以此為契機，他們預備組織一次詩歌鑒賞會，於校園中共同賞景讀詩。\n此情此景，期望您能來一同欣賞。 \n\n寧菲亞"
  },
  Mail_22435_Name = {
    Text = "讀詩會邀約"
  },
  Mail_22435_Sender = {Text = "寧菲亞"},
  Mail_23897_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.21的更新中，我們對「調查行動」困難難度、「意識潛遊」戰鬥關卡普通和困難難度，以及「無光之境」中各界域的輪轉間隙Ⅰ-Ⅳ 每關的首通獎勵進行了調整。詳細的調整內容可在「V1.0.21在線維護公告」中查看。\n        根據您之前的調查和挑戰通關記錄，我們將按調整後的獎勵為你一次性發放之前未能領取的獎勵內容。具體請見附件。"
  },
  Mail_23897_Name = {
    Text = "V1.0.21調整補償"
  },
  Mail_23897_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_24199_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.24的更新中，我們重新開放了在V1.0.16中暫時關閉的「調查行動」第五章。本著公平的原則，我們將根據調整前後的獎勵變化，以及每位守密人的調查記錄情況，發放相應的補償。根據您的調查記錄，您的補償已發放到附件。"
  },
  Mail_24199_Name = {
    Text = "V1.0.24第五章重新開放補償"
  },
  Mail_24199_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_24200_Desc = {
    Text = "尊敬的守密人：\n        在V1.0.24的更新中，我們重新開放了在V1.0.16中暫時關閉的「調查行動」第五章。本著公平的原則，我們將根據調整前後的獎勵變化，以及每位守密人的調查記錄情況，發放相應的補償。根據您的調查記錄，您本次無需補償。"
  },
  Mail_24200_Name = {
    Text = "V1.0.24第五章重新開放補償"
  },
  Mail_24200_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_24202_Desc = {
    Text = "親愛的守密人：\n        感謝您對《忘卻前夜》的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調查問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_24202_Name = {
    Text = "版本體驗調研問卷V1.0下"
  },
  Mail_24202_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_24280_Desc = {
    Text = "你好，守密人：\n你在昨日幻夢深潛的調查排名中，獲得「{s1}排行」的第{s2}名，調查頭銜為「{s3}」，以下為排名獎勵，請守密人記得查收。"
  },
  Mail_24280_Name = {
    Text = "幻夢深潛每日排行獎勵"
  },
  Mail_24280_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_24877_Desc = {
    Text = "守密人：\n\n我的每個生日，都是一場最盛大的沙龍，高朋滿座，賓客盡歡。\n但這次，我倒有些別的想法——\n坐了太久的主位，偶爾也會想嚐嚐當客人的感覺。\n是又一場精緻的沙龍，還是一餐家常晚飯，一切由你來決定，如何？\n不過，如果選擇再開一場沙龍，可別邀請那些名流貴胄了。\n難得的好日子，我不想掛著偽裝的笑臉。\n\n<Del:紅夫人>索蕾爾"
  },
  Mail_24877_Name = {
    Text = "由你決定…"
  },
  Mail_24877_Sender = {Text = "索蕾爾"},
  Mail_24878_Desc = {
    Text = "主人： \n\n今天是莉莉的生日，阿格里帕說要「大鬧一場」。\n過去媽媽和莉莉過生日並不是這樣的，媽媽會給我戴上尖頂帽，一起拍手吹蠟燭。\n莉莉不知道，怎麼做才是正確的，請主人下命令。 \n\n莉莉"
  },
  Mail_24878_Name = {Text = "困擾…"},
  Mail_25147_Desc = {
    Text = "尊敬的守密人：\n        在V1.1.0的更新中，幻夢深潛本週積分獎勵下架，替換為新的「每週試煉」。本著公平的原則，我們對此前已解鎖「幻夢深潛」，但未全部領取本週積分獎勵，且1月15日5：00 前登錄遊戲的守密人，我們補償未領取的本週積分獎勵。請查收。"
  },
  Mail_25147_Name = {
    Text = "V1.1.0幻夢深潛本週積分獎勵補償"
  },
  Mail_25147_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_25148_Desc = {
    Text = "尊敬的守密人：\n        在V1.1.0的更新中、相位對弈（beta）的「每週獎勵」下架、替換為「每週試煉」、與幻夢深潛的「每週試煉」為同一進度與獎勵。本著公平的原則、我們對此前已解鎖「相位對弈（beta）」、但未完成或未領取本週「每週獎勵」、且1月15日5：00（UTC+8） 前登入遊戲的守密人、我們補償融蝕之珠×1000。請查收。"
  },
  Mail_25148_Name = {
    Text = "V1.1.0相位對弈每週獎勵補償"
  },
  Mail_25148_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_25414_Desc = {
    Text = "尊敬的守密人：\n\n誕生之日的重量，於每個人而言都不盡相同。但守密人的生日，對整個彌薩格來說可都舉足輕重。\n茜爾維婭女士在宿舍區為您準備了生日晚宴，訶勒特院長和德克斯特勳爵都會出席。知道你的精神疲勞尚未緩解，我已經替你整理好了正裝，就掛在門口衣櫃中，參會前可以直接換上。\n今年很榮幸能以搭檔的身分與你共度，希望來年亦是如此。\n願銀鑰指引前路。\n\nP.S.訂製小蛋糕已經由艾瑞卡派送至你的宿舍。\n\n願意做你永遠的搭檔 拉蒙娜"
  },
  Mail_25414_Name = {
    Text = "誕生之日…"
  },
  Mail_34667_Desc = {
    Text = "尊敬的@1@2：\n\n世界遺忘了你的名字。\n所以我喚醒你，正如你喚醒我。在終焉降臨之前，你和我於世間行走、見證，然後銘記和遺忘。\n今日是你的誕生之日，是你散佚的記憶碎片中偶然拾得的一頁。為此，當獻上喟歎與祝福。\n當世界回憶起你完整的形貌，你會作何感想呢？又或是仍一無所知，一無所覺？\n我在不存在之地等待你的答案。\n\n@2"
  },
  Mail_34667_Name = {
    Text = "誕生之日…"
  },
  Mail_35231_Desc = {
    Text = "親愛的守密人：\n        感謝您對《忘卻前夜》的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調查問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
