  Mail_36865_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.4的更新中，我們對「幻夢深潛」每週試煉的獎勵進行了調整，不再提供「融蝕之珠」「擬態凝晶」和「薔薇金券」獎勵。本著公平的原則，我們對更新前已解鎖「幻夢深潛」，但未全部領取本週試煉獎勵，且3月11日5：00 前登錄遊戲的守密人，我們補償本週試煉中未領取的原「融蝕之珠」「擬態凝晶」和「薔薇金券」獎勵。請查收。"
