  Mail_36867_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.4的更新中， 「超驗存在」掉落的獨特技能升級素材和擬態凝晶數量有所提高。本著公平的原則，對更新前已領取本週「超驗存在」獎勵的守密人，我們將按守密人已領取獎勵的關卡推薦等級，補發與提升掉落相等價值的「擬態凝晶」。請查收。"
