  },
  Mail_36871_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_39293_Desc = {
    Text = "尊敬的守密人：\n        在V1.2.7的更新中，通關意識潛遊「如歌的雕琢」「蒼白後裔」「一步之遙」普通模式新增了解鎖全新鑰令「蝕骨的擁抱」「湖畔回眸」「跨越回溯之扉」。對更新前已完成以上篇章普通模式的守密人，我們將補發對應的鑰令。請查收。"
  },
  Mail_39293_Name = {
    Text = "V1.2.7意識潛遊鑰令補發"
  },
  Mail_39293_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_39548_Desc = {
    Text = "親愛的守密人：\n\n對永恆的生命而言，紀念生辰似乎並無必要。和無垠的時間長河相比，你們人類稱之為難忘或是精彩的回憶都顯得有些……微不足道。\n而你們卻發明了無數的節日和慶典來紀念這些「微不足道」——當然，這也是人類引發我興趣的原因之一。你們確實足夠可愛。\n不過，與你的相遇顯然不能算在這些「微不足道」的瞬間裡，因為你與他們不同……而這種「不同」將在未來掀起何種風暴，我亦十分期待。\n好了，請原諒我的絮叨……既然今天是我的生辰，那麼我請求行使一下「壽星的權利」。\n至於需要你做什麼，噓……切勿心急，謎底就在我的臥室裡，請於今夜午時獨自前往。\n\n旺達"
  },
  Mail_39548_Name = {
    Text = "壽星的權利……"
  },
  Mail_39548_Sender = {Text = "旺達"},
  Mail_39549_Desc = {
    Text = "今天是墨菲大人的生日——生日，就應該要有宴會與慶典！\n後勤管理處那些人做得還不錯，但他們實在是不太會做戲，還遮遮掩掩的——本小姐早就看到他們在往喚醒系倉庫裡放蛋糕裝飾了。唔……你應該不會懲罰那些職員吧？他、他們做得是真的很不錯，就是沒有藏好驚喜而已……\n就寫到這裡了，好像有人在找我出去——他們最好不要用蠢兮兮的彩紙糊本小姐一身。\n順便一提，切蛋糕的時候，你會在吧？\n\n墨菲"
  },
  Mail_43571_Desc = {
    Text = "親愛的守密人：\n        在V1.2.10的更新中、「霧都紀行」活動任務【完成調查主線第 1 章「東區秘事」困難難度】和【完成調查主線第 2 章「以蠟像之名」困難難度】新增了獎勵：「銀芯」× 1000。對更新前已領取完以上任務獎勵的守密人、我們將補發對應的銀芯。請查收。"
