  Mail_44571_Desc = {
    Text = "尊敬的守密人：\n「靈魂的牧人」將於4月18日9時結束【GMT+8】。活動結束後相應活動入口將關閉，包括聖堂之路、聖堂義賣現場等，逾期未使用的義賣券將自動消失。守密人記得在活動結束前及時在聖堂義賣現場中購買商品。"
