  },
  Mail_44690_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_44831_Desc = {
    Text = "尊敬的守密人：\n        在V1.3.0的更新中，通關特遣紀錄「雨鎮幽影」「薔薇禮讚」「故事的魔法」普通模式新增了解鎖全新鑰令「灰霧真容」「玫瑰的勝利」「仲夏之夢」。對更新前已完成以上篇章普通模式的守密人，我們將補發對應的鑰令。請查收。"
  },
  Mail_44831_Name = {
    Text = "V1.3.0特遣紀錄鑰令補發"
  },
  Mail_44831_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_44836_Desc = {
    Text = "親愛的守密人：\n        在V1.3.0的更新中、我們對「幻夢深潛」每週試煉 1 勝、3 勝增加了獎勵：「代理憑證」×1。對更新前已領取以上獎勵的守密人、我們將補發相應數量的「代理憑證」。請查收。"
  },
  Mail_44836_Name = {
    Text = "V1.3.0每週試煉獎勵補發"
  },
  Mail_44836_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_44837_Desc = {
    Text = "可敬的蒼白使者：\n\n幾個孩子今日送來了花束與糕點，我這才想起，遠在洪積曆法之前百餘年的今天，我蒙受父神的恩賜，領受生命來到人世。那是多麼久以前的事了啊，童年的記憶早已模糊，唯有本多薩教堂內熏香的味道還縈繞在我腦海之中，揮之不去。而今即使教堂還在，熏香的配方也不會是當年的那個了。\n\n抱歉，傷春悲秋並非我來信的目的。我用孩子們帶來的糕點準備了一場茶歇，希望你能來與我一同分享——倒不是為了慶賀我的生日，而是為了慶賀生命存在的每一天，希望存在的每一天。\n\n不知你的生日是何時呢？請務必在一杯茶後告訴我。\n\n\n\n薩爾瓦多"
  },
  Mail_44837_Name = {
    Text = "蒼白的使者……"
  },
  Mail_44837_Sender = {
    Text = "薩爾瓦多"
  },
  Mail_44843_Desc = {
    Text = "尊敬的守密人：\n        在V1.3.0的更新中，我們下架了「核心課題」的特權：在「幻夢深潛」和「相位對弈（beta）」獲得守密人經驗翻倍。為表歉意，我們將為購買了本期「核心課題」的守密人提供每日「守密人經驗」× 240 的補償，持續到本期學期課題結束。請查收。"
  },
  Mail_44843_Name = {
    Text = "V1.3.0核心課題獎勵補發"
  },
  Mail_44843_Sender = {
    Text = "彌薩格校務處"
  },
