  },
  Mail_47308_Desc = {
    Text = "尊敬的守密人：\n在昨日幻夢深潛中，你通關最高難度為「{s1}」。\n在昨日相位對弈中，你獲得頭銜為「{s2}」，並有對弈勝場。\n綜合以上挑戰成績，你將獲得以下融蝕之珠獎勵，請記得查收。"
  },
  Mail_47308_Name = {
    Text = "深潛對弈融蝕之珠獎勵"
  },
  Mail_47308_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_48005_Desc = {
    Text = "親愛的守密人：\n\n冒昧打擾，希望我糟糕的筆跡不會破壞您的好心情，我實在是不太擅長書寫……\n寫這封信是為了告訴您，我的生日似乎到了。為此我做了一些小餅乾，希望您也能嘗一嘗。\n說實話，我不確定這個日期是否正確。感染融蝕後，有關我存在的痕跡正在一點點消失。朵爾小姐曾問我，清醒地看著自己被大家遺忘，是一種什麼樣的感覺？\n這很難形容……就像是站在一片漆黑裡，一條發光河流的邊緣，人們都在河流的另一頭互相說話、各自忙碌，在我面前匆匆走過。我只能看著他們，卻發不出一點聲音。\n這是一種很孤獨的感覺。幸運的是，那些人裡不包括您。\n至少您還記得我的故事，不是麼？\n\n另，十二個小餅乾已隨信附上。\n\n梅森"
  },
  Mail_48005_Name = {
    Text = "冒昧打擾……"
  },
  Mail_48145_Desc = {
    Text = "尊敬的守密人：\n「多重療癒」活動已結束，現將守密人剩餘的活動貨幣「記憶拼圖」按照「人格解析」無限兌換的比例進行回收，請守密人記得查收。"
