  },
  Mail_48914_Name = {
    Text = "版本體驗調研問卷V1.6.3"
  },
  Mail_48914_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_48915_Desc = {
    Text = "親愛的守密人：\n        感謝您對「忘卻前夜」的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調研問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。問卷截止時間9月30日9：00、請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_48915_Name = {
    Text = "版本體驗調研問卷V1.6.1"
  },
  Mail_48915_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_49931_Desc = {
    Text = "親愛的守密人：\n「慾海翻波」活動已結束、現將守密人剩餘的「豐穰種核」按每枚兌換「薔薇金券」× 20的比例進行轉換、請守密人記得查收。"
