  Mail_49931_Name = {
    Text = "豐穰種核回收"
  },
  Mail_49931_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_50344_Desc = {
    Text = "小樹苗：\n\n風帶來了你的氣息，比剛認識你那時，聞起來更甜了些。\n你在我的愛中長大，被我的愛滋養成熟……就像蜂和蜜糖一樣。\n今天是個特殊的日子，能來與我見一面嗎？\n我已經依你要求，乖乖等待很長一段時間了……是時候該給我一些獎勵了，你說對嗎？\n\n泰旖絲"
  },
  Mail_50344_Name = {
    Text = "蜜糖一樣的…"
  },
  Mail_50344_Sender = {Text = "泰旖絲"},
  Mail_51376_Desc = {
    Text = "親愛的守密人：\n「故事的魔法」活動已結束、現將守密人剩餘的「飄零的靈感」按照每枚兌換「薔薇金券」× 60的比例進行轉換、請守密人記得查收。"
