  },
  Mail_51376_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_51777_Desc = {
    Text = "親愛的守密人：\n「故事的魔法·復刻」活動已結束、現將守密人剩餘的「飄零的靈感」按每枚兌換「薔薇金券」× 25的比例進行轉換、請守密人記得查收。"
  },
  Mail_51777_Name = {
    Text = "飄零的靈感回收"
  },
  Mail_51777_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_53149_Desc = {
    Text = "我早已決定，將餘生的每日都獻給那一位……權當是為我愚笨之行的贖罪。\n淺薄之身的「生日」，不值一提，不足掛齒。\n今天與過去的、未來的任何一天都沒有區別，我會一如既往前往禮拜堂。\n但，如果您想讓我在今日離開禮拜堂，作為彌薩格的客人，我自是不會違背主人的意志。\n若，您想見證我的祈禱，也隨時歡迎您來……誠惶誠恐，不勝歡迎。\n\n彌利亞姆"
  },
  Mail_53149_Sender = {
    Text = "彌利亞姆"
  },
  Mail_53151_Desc = {
    Text = "親愛的守密人：\n「沉淵之祀」活動已結束、現將守密人剩餘的「祀者之淚」、「祀者之血」和「祀者之髓」按照每100個兌換「薔薇金券」× 2500 的比例進行轉換、請守密人記得查收。"
