  },
  Mail_54803_Desc = {
    Text = "親愛的守密人：\n        在V1.5.1的更新中、我們提高了「成長紀錄」守密人等級21-80級的「銀芯」獎勵、並為「界域精通」Ⅰ~Ⅴ 階段完成任務追加了「調查徽章」× 1000 的獎勵。對更新前已領取完上述獎勵的守密人、我們將補發對應的「銀芯」或「調查徽章」獎勵。請查收。"
  },
  Mail_54803_Name = {
