  },
  Mail_54803_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_55168_Desc = {
    Text = "親愛的守密人：\n「在春天凋零以前」活動已結束、現將守密人剩餘的「歡欣的詩文」、「惆悵的詩文」和「遺憾的詩文」按照每200個兌換「薔薇金券」× 5000 的比例進行轉換、請守密人查收。"
  },
  Mail_55168_Name = {
    Text = "詩文回收"
  },
  Mail_55168_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_56101_Desc = {
    Text = "守密人%sirormadam%：\n\n今天凌晨，一朵玫瑰在初春的鳥鳴裡盛開了。\n它本應是一個含苞的春枝，卻在聖瓦倫丁節，在我誕生的這一天，盛開在一個不屬於它的季節。\n我回憶起了西岱。每年生日這天，西岱的街頭總是很熱鬧。我聽到花開的聲音，聽到人們令人臉紅的情話。可我已經很久沒有機會觸碰到它們了……直到今天。\n您相信巧合嗎，守密人？我想，巧合是一種語言，而玫瑰是一種修辭。今天，在彌薩格紛繁的花園裡，這朵玫瑰綻放著，它的花瓣大方地舒展開，就像是一首令人心醉的詩。\n所以，今天，守密人……您願意和我一起，來看看這朵玫瑰的盛開嗎？\n我和花，都期待著您的到來。\n\n奧爾拉"
  },
  Mail_56101_Name = {
    Text = "一朵玫瑰開在春天……"
  },
  Mail_56101_Sender = {Text = "奧爾拉"},
  Mail_57328_Desc = {
    Text = "親愛的守密人：\n「群星正位」活動已結束、現將守密人剩餘的「無識之胚」、「無欲之胚」和「無厭之胚」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人查收。"
