  },
  Mail_61154_Desc = {
    Text = "親愛的守密人：\n「燃燒的盛宴·復刻」活動已結束、現將守密人剩餘的「原生脛骨」、「圓葉菊石」和「螺旋遺蹟」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_61154_Name = {
    Text = "燃燒的群宴貨幣回收"
  },
  Mail_61154_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_61155_Desc = {
    Text = "尊敬的守密人：\n「多重療癒·復刻」復刻活動已結束、現將守密人剩餘的活動貨幣「記憶拼圖」按照每個兌換「薔薇金券」× 40 的比例進行回收、請守密人記得查收。"
  },
  Mail_61155_Name = {
    Text = "記憶拼圖回收"
  },
  Mail_61155_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_62392_Desc = {
    Text = "守密人：\n\n我的演奏曾侍奉於帝王座前，也曾被萬千世人憧憬。然而那些溢美之詞於我而言毫無價值，我所追求的不過是音樂的極致。\n比起在華麗而盛大的場合供人欣賞，獨自在無人的森林中演奏更加令我放鬆。\n原本我不喜歡自己的練習有人旁聽，那些只是我通往完美的草稿，一些無意義的廢料。\n但自從知曉您、找到您之後，我所有的樂聲都有了意義。\n是您給予了我最偉大而崇高的樂音，拯救了我於迷途之中，哪怕您自己並不知曉……\n今日是我的生日，原本我已經將它淡忘，但現在，我想紀念一下自己的新生，和賜予我新生之人。\n恰巧近日有些新作的曲譜，想邀請您稍作鑒賞。請原諒我的姍姍來遲，我的身分尚不適合現身於彌薩格同僚之前，只能在等待地平線收斂落日所有餘暉後再向您遞上這封邀請函。\n今晚學校後方的森林中，我會開一場特別的音樂會，觀眾席只有一個。\n期待您的蒞臨。\n\n哈姆林"
  },
  Mail_62392_Name = {
    Text = "秘密音樂會…"
  },
  Mail_65350_Desc = {
    Text = "親愛的守密人：\n「雪山消融之時」活動已結束、現將守密人剩餘的活動貨幣「寒凍花苞」「銀霜花苞」和「陽光花苞」按照每個兌換「薔薇金券」× 40 的比例進行回收、請守密人記得查收。"
  },
  Mail_65350_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_65441_Desc = {
    Text = "親愛的守密人：\n「沉淵之祀·復刻」活動已結束、現將守密人剩餘的「祀者之淚」、「祀者之血」和「祀者之髓」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_65441_Name = {
    Text = "沉淵之祀活動貨幣回收"
  },
  Mail_65441_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_65442_Desc = {
    Text = "親愛的守密人：\n「萬象門扉」活動已結束、現將守密人剩餘的活動貨幣「終末指針」按照每個兌換「薔薇金券」× 40 的比例進行回收、請守密人記得查收。"
  },
  Mail_65442_Name = {
    Text = "終末指針回收"
  },
  Mail_65442_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_67147_Desc = {
    Text = "守密人：\n\n    宇宙的維度對我而言並不唯一，窮極之門內可以窺見萬千世界與無限存在。那裡超越一切奇想與數學邏輯，自然也無從確定「誕生之日」的日期。\n    所以，就將你我的初遇定為那個時刻吧。你所在的時間連續體的刻度中，應當會在今天舉行專屬於我的儀式，實現我許下的願望。\n    那麼，跨越銀鑰之扉，來到我的身邊吧。我將傳授你…一些關於終極本源的、屬於宇宙的知識。今夜，億萬光輝體將為你我二人閃耀。\n    我在窮極之門等你。\n\n塔薇"
  },
  Mail_67147_Name = {
    Text = "跨越銀扉…"
  },
  Mail_67933_Desc = {
    Text = "我感受到了你片刻的茫然——那無上的造物主，即使是直視也近乎妄想，又如何傷及分毫？但你做到了。\n又一道目光坍塌，堅硬的鎧甲，在一塊塊前赴後繼的碎片下，留下了劃痕與豁口。\n%player%，無堅不摧的，唯有你堅定的意志。"
  },
  Mail_67933_Name = {
    Text = "從迷惘中看清道路"
  },
  Mail_67933_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67934_Desc = {
    Text = "你的四肢在顫抖，%player%。你幾乎已經無力站立。恐懼攥住了你，讓你大腦空白，無法控制自己的呼吸……但你依然向著前方舉起了銀鑰。\n在人類所有美好的品格里，勇氣是最為高尚的那一個。面對天災與猛獸，我們曾舉起石錘與長矛。如今面對神明，你依舊如此。\n人類文明因勇氣而建立，也終將因勇氣生生不息。"
  },
  Mail_67934_Name = {
    Text = "勇氣的讚歌，於顫慄中響起"
  },
  Mail_67934_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67935_Desc = {
    Text = "我們曾談論起這個世界，你說，你並不喜歡它。這裡充斥著利益、陰謀、欺騙、殺戮，即便沒有融蝕與神明，它也本就千瘡百孔，搖搖欲墜。從阿庫特醒來之後，在你短暫的記憶裡，你已見過無數比融蝕更失序、更可怖的人心。\n可當造物主舉起祂的利刃時，你依然擋在這個世界身前。湮滅是神明的意志，而你拒絕了祂。\n我明白，%player%。沒有守密人不憎惡這個世界，也沒有守密人不真正愛它。因為在那些骯髒中，我們曾見過那些如銀芯般閃耀的光輝。\n守密人的職責，便是守護那些微弱的光輝，永世長存。"
  },
  Mail_67935_Name = {
    Text = "人類精神永存"
  },
  Mail_67935_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67936_Desc = {
    Text = "第一次看見融蝕，第一次面對融蝕的真相，第一次感知到神明的聲音……在我漫長的人生中，歷經了無數頹唐的時刻，我不知道自己能做些什麼，不知道這一切努力與犧牲的意義所在——但那些都不及你此刻所面對的。\n人類就是這樣，在一次次的頹唐中重新站起，邁向前方。\n道路的盡頭或許亦是萬丈深淵，但總會有人想要去看一看。"
  },
  Mail_67936_Name = {
    Text = "頹唐，而後新生"
  },
  Mail_67936_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67937_Desc = {
    Text = "維度的界限打開，我終於能再次與你聯絡。\n和你所見的相比，這個維度的目光異常孱弱，或許是因為這個維度沒有你的存在。犧牲了幾乎一切之後，我替你解決了祂。\n難以想像你正面對著什麼。但無論如何，湮滅的意志，我將與你一同對抗。這是每一個彌薩格人的誓言。\n很高興，能再次與你並肩。\n願銀鑰指引前路。"
  },
  Mail_67937_Name = {
    Text = "並肩作戰，再一次"
  },
  Mail_67937_Sender = {
    Text = "未知寄件者"
  },
  Mail_67938_Desc = {
    Text = "瘋狂，一個輕鬆、甚至美好的詞彙。\n一個混沌的宇宙，產生了一個混沌的文明。混沌是這個世界的真相。順應混沌，享受瘋狂，這是一件多麼輕鬆的事。與之相比，清醒與對抗，是如此艱難。你將祭獻全部的歡愉與生命，隻為追尋一個遙不可及的答案。\n可你仍然選擇清醒，%player%。因為我們生來不是要做奴隸的。\n你讓祂看到了，%player%——祂的造物，祂的碎片，從不甘做盲目癡愚的奴隸。你與祂對抗，戰勝祂的一道又一道目光，選擇守護這個並不完美、並不輕鬆的世界。\n在這選擇中，你已擁有了永恆的自由。"
  },
  Mail_67938_Name = {
    Text = "你從不甘做盲目癡愚的奴隸"
  },
  Mail_67938_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67939_Desc = {
    Text = "我感受到了一道目光的坍塌。我感受到了你切膚的疼痛。\n這是守密人這個稱號上所銘刻的責任。你選擇踏上的道路，比我所走的艱難萬倍。不是所有人都有勇氣直面無上的神明，你的勇氣令我感到欣慰，敬歎。\n造物主的力量會讓你承受多大的痛苦，我無從想像。我所感知到的，只是你所承受的滄海一粟。我是一個困守黑池的廢人，%player%，我已無力參與你與造物主的對決，只能通過我的感知與你時刻相連。這將是我的生涯中，最後、也最重要的使命。\n在這條孤獨的道路上，無論你是否得見，彌薩格都將一直陪伴在你身邊。"
  },
  Mail_67939_Name = {
    Text = "悲痛不會使你屈服"
  },
  Mail_67939_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_67940_Desc = {
    Text = "我聽見了無上意志的低語——宏偉的文明，人間的悲歡，環繞你遠離你的無數的人，一切從未存在過。\n在黑池的無數個日夜，這景象令我感到恐懼。樹木扎根於土地，然後向上生長，迎接太陽——記憶，記憶是我們的土壤，是我們生長、站立、最後將要回歸的地方。我畏懼失去土地，漂浮在虛無中，沒有來處，沒有終點。\n謝謝你，%player%。我想，我見證了一場偉大的對決。這是人與神明的戰鬥。這是守護與毀滅的戰鬥。\n這是銘記與遺忘的戰鬥。\n你做到了，%player%。你完成了無人敢想像的事。你從銘記中獲得了無可匹敵的力量。你以這力量，為銘記而戰。\n你已於這亙古的土壤中，尋到屬於你的太陽。"
  },
  Mail_67940_Name = {
    Text = "為了銘記而戰"
  },
  Mail_67940_Sender = {
    Text = "阿利斯泰爾"
  },
  Mail_68825_Desc = {
    Text = "親愛的守密人：\n「神王甦醒」活動已結束、現將守密人剩餘的活動貨幣「疲憊緒思」、「悲愁緒思」和「歡悅緒思」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_68825_Name = {
    Text = "神王復甦貨幣回收"
  },
  Mail_68825_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_68826_Desc = {
    Text = "親愛的守密人：\n「慾海翻波·復刻」活動已結束、現將守密人剩餘的「豐穰種核」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_68826_Name = {
    Text = "豐穰種核回收"
  },
  Mail_68826_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_68898_Desc = {
    Text = "最最最親愛的主人：\n\n作為萬能女僕，珈倫能夠記住大人們許許多多重要的日子，上到宴會日、生日、紀念日，下到第一次購買寵物的日子，絕對不會出一點錯。但對於珈倫自己來說，能夠紀念的特別的日子就只有這一天啦。\n很久很久以前，珈倫還在皇宮裡當侍女，第一次去向廚師要一塊貴人們沒吃完的甜點作為生日蛋糕的時候被大罵了一頓，那個廚師把蛋糕扔在了我的臉上，那時候我就想，原來蛋糕是這麼好吃的東西，我一定要找到一個對我很好的主人，讓我每年生日都能吃到蛋糕。\n現在我有特別特別優雅大方的索蕾爾夫人，和特別特別善良的主人您，當年的願望已經實現啦！但人總是會越來越貪心……啊不進步的嘛，現在我的願望是每年生日的時候都可以陪在主人的身邊，另外如果每年都有亮閃閃的禮物就更好了。\n聽了這麼多，您一定會給我準備的吧，對吧對吧？\n\n您永遠謙卑的女僕\n珈倫"
  },
  Mail_68898_Sender = {Text = "珈倫"},
  Mail_68899_Desc = {
    Text = "小樹苗：\n\n看到你一直以來的成長，讓我越來越確信選擇你，幫助你，是我做過最正確的決定。\n我感受到了豐收的喜悅，一切信任與愛的澆灌都給予了我甜美的回報，是你給了我希望與未來。\n現在我可以拋卻繁衍的執念，專心去享受那繁衍之外的，愛的果實。\n這個世界不再需要亞蘭女王，但或許可以容納一個普通女人想要愛侶陪伴的生日願望。\n就像最常見的情侶那樣，一起去購買食材，一起烹飪美食，或許還有許多我不曾體驗的事物，那麼親愛的你能夠引領我，度過一個溫馨平淡的生日嗎？\n\n泰旖絲"
  },
  Mail_68899_Sender = {Text = "泰旖絲"},
  Mail_68900_Desc = {
    Text = "守密人：\n\n卡茜亞大師是世界上最最傑出的表演大師，可以完美模仿出任何表情，但人類情感這種東西真是無論怎樣都搞不明白的世界謎題。\n我問過許許多多的人，他們都不能講清情感的原理，直到我問到朵爾，她告訴我世界上有一門叫做心理學的學科，哪怕不能感同身受，但學好心理學就可以掌握所有情感的理論。\n這實在、實在是太吸引人啦！難道困擾卡茜亞這麼久的疑惑就要徹底解開了嗎？\n話說回來，我是來告訴你，這周的心理學課程我會加入你的班級課堂，卡茜亞決定做你的同桌，之前我落下的內容你要好好幫我補課哦，同桌~\n啊對了，順便一提，今天是我的生日，這裡我應該開心，你也應該開心，對不對？\n如果是非常開心的事，那就在學校裡大鬧一場吧，我會讓校園變得像夢境一樣美的！\n\n卡茜亞"
  },
  Mail_68900_Name = {
    Text = "心理學…"
  },
  Mail_68900_Sender = {Text = "卡茜亞"},
  Mail_68901_Desc = {
    Text = "可敬的蒼白使者：\n\n感謝這一年來你的幫助與關心，你對待他人的赤誠之心就像是父神所教導的那般高尚，即使與你相處的機會並不頻繁，但每次與你見面時就彷彿遇到相識已久的老友一般，令我如沐春風。\n生日這一天雖然並無特別，但作為友人見面的理由，還是令人心生期待，除了你，我想不到有任何其他人可以作為共度這一天的人選。\n如果你感興趣的話，我想邀請你體驗我近來的新愛好——釣魚，當然，不是為了烹飪和食用，只是單純享受這樣靜靜等待命運給予神奇禮物的過程。我想與你分享這樣寧靜的感受，去到自然之中，在湖畔安然靜坐。\n一位老友、兩支魚竿，想必將是再好不過的一天。\n\n薩爾瓦多"
  },
  Mail_68901_Name = {
    Text = "釣魚的新愛好…"
  },
  Mail_68901_Sender = {
    Text = "薩爾瓦多"
  },
  Mail_68902_Desc = {
    Text = "主人：\n\n今年的生日，艾繼絲和詹金送給了我一隻長得很像奧瑞塔的玻璃風鈴。\n我把它掛在了房間的窗戶上，有風吹過的時候就會發出好聽的聲音，讓我想起母親曾經抱著我靠在窗邊講故事的時候。\n不用擔心，主人，雖然我每天都在思念母親，但有了主人和大家陪我，莉莉不會感到孤單。\n現在莉莉學會了自己看故事書，每天傍晚的時候，橘色的陽光照進屋子，照在風鈴上，在故事書上照出一塊一塊搖晃的波紋，映得房間暖暖的。\n莉莉好喜歡在這時候發呆，看著夕陽下的雲朵和風鈴，感覺好美好美。\n今天主人有時間的話，也來試試和莉莉一起發呆吧。\n\n莉莉"
  },
  Mail_68902_Name = {
    Text = "玻璃風鈴…"
  },
  Mail_68903_Desc = {
    Text = "小傢伙：\n\n雖然這個特別的日子是為了紀念那個人類而定下的，但我不得不承認，折扣日對於顧客和商家來說都是一種極其具有吸引力的售賣方案。\n上一次生日的時候，解憂小鋪的成交訂單幾乎比得上平時半年的銷量，尤其是那些被我拿出來當作慶祝彩頭的特價商品全部被搶購一空。是該說彌薩格的客人們都太照顧我的生意，還是連精明謹慎的調查員們都抗拒不了折扣的誘惑呢。\n總之為了繼續雙贏的快樂，今年我的生日宴會依然會舉行折扣活動，一年僅此一次，力度很大，欲購從速。記得幫我在彌薩格好好宣傳一番，為了便於記憶，就將這一天稱為雙十日吧。\n另外，我為你偷偷留下了一些有意思的小東西，一定要早點來見我哦。\n\n達芙黛爾"
  },
  Mail_68903_Sender = {
    Text = "達芙黛爾"
  },
  Mail_68904_Desc = {
    Text = "承命運洪恩，彌薩格大學守密人，賢明仁德之主君：\n萬安！\n如果說每位騎士的畢生願望就是追隨一位偉大的主君，那麼我的騎士生涯已然無憾。\n我的人生中除了幸運，也包含了太多不幸的悲劇與壯烈的鮮血，我知道因此彌薩格的許多人都曾對我心生同情。\n先不說僅僅比較苦難，彌薩格中已有太多不幸的人，在這樣充滿苦難的世界上，為守護而流盡鮮血並不是什麼需要悲傷的事。正相反，無論是過去還是現在，我都為此感到榮耀，並時刻做好了犧牲此軀的準備。\n但蘿坦閣下說我每天板著臉操心的樣子看著太累，讓我在生日這天好好地玩一下，並叫來了詹金教我玩遊戲，說是要讓我找回童年。\n說來慚愧，我童年時忙於訓練，的確沒有什麼玩耍的經歷，沒想到這種據說五歲小孩都能精通的遊戲是這樣困難，看來在騎士之道外，我需要學習的東西還有很多。\n若主君今日得閒，不知能否前來與我們一同遊玩，我看到詹金在連贏十局之後已經開始無聊，如果主君在此，一定能帶來一場精彩的對弈。\n\n奧吉爾"
  },
  Mail_68904_Name = {
    Text = "困難的遊戲…"
  },
  Mail_68904_Sender = {Text = "奧吉爾"},
  Mail_68905_Desc = {
    Text = "喂：\n\n有了那本日曆，想必你今年一定沒有忘記尊貴的迷宮之主的生日。\n我允許你來我的房間獻上禮物，順便在這一天盡心服侍我。\n比如什麼刷牙洗臉、更衣進餐，還有那些打掃房間、更換被單的事，你們有個詞叫什麼來著，大掃除！\n對，這些大掃除的工作就都交給你了，我已經受夠了那些家務，今天無論如何，我都要重回曾經在羅馬的時光，享受一下衣來伸手、飯來張口的生活。\n今天不管是誰也別想讓我自己幹一點活，誰也別想！\n\n阿格里帕"
  },
  Mail_68905_Name = {
    Text = "重回過去…"
  },
  Mail_68906_Desc = {
    Text = "守密人：\n\n時間過得真快，沒想到曾經以為會持續到死掉的那種生活，現在我已經幾乎不會想起了。\n如今本小姐已經對食堂所有的小蛋糕瞭如指掌，再怎麼鞭策那群沒用的廚師，他們也做不出什麼新花樣了。\n所以新的一年，我的美食地圖要變得更大、更遠，先定一個小目標：吃遍倫蒂尼恩所有的蛋糕店。\n至於跑腿排隊的光榮工作，就還是交給你啦！能得到本小姐的信任，你也不用太過高興，只要心懷感激地稱頌本淑女的名號就好。\n不過話說回來，那群笨蛋廚師多少還是有些誠心的，從他們遮遮掩掩的悄悄話中我已經聽到他們似乎準備了一個巨大的十層蛋糕——哈，他們還是這麼不會掩藏驚喜。\n雖然創意有些老套，但或許這次生日會我可以多邀請一些人，比如這一年來交到的新朋友。\n作為本小姐在彌薩格的第一個朋友，我允許你替我在蛋糕上切第一刀。\n\n墨菲"
  },
  Mail_68906_Name = {
    Text = "十層蛋糕…"
  },
  Mail_68907_Desc = {
    Text = "親愛的守密人：\n\n聰慧如你，一定已經從彌薩格的神奇檔案裡知道了這一資訊——今天，是「好運偵探」生命中值得紀念的日子。\n出生，贏下第一局21點，贏得第一百場賽馬，破獲第一場密室殺人案，帶來死亡的失敗——一切都發生在這神奇的6月6日。\n因此，要不要和我來一局雙人橋牌？就在今天，讓這個日子變得更值得紀念，如何？\n\n萊克"
  },
  Mail_68907_Name = {
    Text = "來一局吧？"
  },
  Mail_68907_Sender = {Text = "萊克"},
  Mail_68908_Desc = {
    Text = "這封信並非問候，而是一個警告——不要試圖控制我，不要試圖給我套上鎖鏈。\n我只屬於我自己。\n我可不像那個和我長得一樣的傢伙一樣，還對人、對世界，抱有幼稚的期待。\n\n我會殺了任何妄圖成為我“主人”的傢伙，說到做到。\n\nH"
  },
  Mail_68908_Name = {
    Text = "我屬於…"
  },
  Mail_68908_Sender = {
    Text = "血鏈·希洛"
  },
  Mail_68909_Desc = {
    Text = "守密人：\n\n或許我曾對您講述過我對於水的喜愛，相比於喧鬧的人間，水中的世界是那樣靜謐、安寧。\n我曾飄蕩在水草與珊瑚之間，也曾與魚群對話。當離水面越遙遠，水中的顏色便越幽暗，被水波輕柔推動著從水底看向天空時，那斑駁的光影呈現出令人迷幻的色彩，是我心中最美的風景。\n你知道嗎？有些海洋生物能夠記住人的樣子，當你再次到訪，這些“朋友”還會熱烈地靠近迎接，譬如我認識一隻聰明的小章魚，以及一條嫩黃色的海魚。\n在生日的這天，我又思念起水下的世界，不知道您是否願意與我進行一次潛泳，我由衷地希望能將這份寧靜的天地，以及我神奇的朋友們一同分享給您。\n\n寧菲亞"
  },
  Mail_68909_Sender = {Text = "寧菲亞"},
  Mail_68910_Desc = {
    Text = "守密人：\n\n自從你來到彌薩格，我已經習慣了用培養嬰兒的方法來處理與你相關的事宜，從你平時的反應來看，你的孱弱也遠超我的期待。\n不過作為你的師長兼第一監護人，我很高興看到這一年來為你處理麻煩和善後的情況越來越少，雖然你剛剛入學時大腦一片空白的樣子十分令人絕望，但你的成長速度的確可以稱得上天賦與努力兼有。\n恭喜你已經成為了一位合格的守密人，沒有辜負我的期待。\n在我的生日這樣沒什麼特殊的一天，我已經為你準備好了一份屬於成功守密人的禮物——阿利斯泰爾曾經用過的特訓方案，怎麼樣，是不是很期待？\n不要問為什麼是我給你準備禮物，不能進入實驗室的日子總要找點事做，不是嗎。\n等你準備好了，就來訓練室找我。\n\n朵爾"
  },
  Mail_68910_Name = {Text = "禮物…"},
  Mail_68910_Sender = {Text = "朵爾"},
  Mail_68911_Desc = {
    Text = "守密人：\n\n一年時間對於舞者來說，只是幾萬次的旋轉、幾萬次的跳躍，除去上一雙陪了我很久的舞鞋被換下外，一切好像都沒有改變，一切又好像都有所不同。\n相比從前習慣的孤獨，這一年我始終擁有一個忠實的觀眾、一個有些笨拙的舞伴。\n每當你坐在舞蹈室時，我都會感到身體更加輕盈，如同我兒時剛剛學習舞蹈的時候，充滿了莫名的激情與動力。\n或許我並沒有自己想的那樣純粹而高尚，在將一生都奉獻給舞蹈的同時，我也希望能夠擁有你的注視，聆聽你的掌聲。\n生日的這天天氣很好，我能預感到今夜星空將十分晴朗。我最熱情的觀眾、我的專屬舞伴，你是否願意與我一起走到那片有著美麗湖泊的森林中，一起跳一支屬於月亮與星星的舞蹈？\n\n莉茲"
  },
  Mail_68911_Name = {
    Text = "專屬舞伴…"
  },
  Mail_68911_Sender = {Text = "莉茲"},
  Mail_68912_Desc = {
    Text = "守密人：\n\n從我的重生之日開始，彌薩格的人們幫助了我很多，或許我仍不能習慣合作的感覺，但至少在與你們同行的時候，我已經可以把後背放心地託付出去，這種感覺……也不錯。\n我的人生中大多數時候都充滿了傷害與背叛，我總將對抗這些當作我戰鬥的意義，直到我的生活中再也沒有其他任何東西，我的目光早已不能從復仇之中挪開。\n現在跟隨著你們的腳步，我才發現戰鬥除了傷害與報復還可以擁有很多意義，甚至是像蘿坦所說的，戰鬥也可以只是戰鬥。\n我學會了享受戰鬥的樂趣，享受那種酣暢淋漓的感覺，享受單純地成為一個勇猛的戰士。\n如果我的戰鬥能帶來更多，那麼，我將享受那種榮耀。\n而你，無論現在還是未來，我許諾我的劍刃永遠不會指向你。\n\n希洛"
  },
  Mail_68912_Name = {
    Text = "戰鬥的意義…"
  },
  Mail_68913_Desc = {
    Text = "親愛的守密人：\n\n說實話，我對生日願望這樣的東西並沒有太多想法，以前在我尚且“正常”的時候，吃飽穿暖、按時交上房租、照顧好詹金就已是每天最大的願望。現在還能安安穩穩地度過一年，還能看著詹金胡鬧一年，已經足夠令人滿足。\n說來慚愧，在詹金面前，我總是擺出一副姐姐的樣子管教她，但對你來說，我總會給你添上許多麻煩，甚至我自己也不記得是哪一個我惹了麻煩。\n你始終不變的溫和與耐心讓我既溫暖又不好意思，或許這是我人生中第一次有人用這樣包容的態度照顧我，我感到發自內心的榮幸和感激。\n今年我為大家烤了一個大大的蛋糕，是曾經紡織廠的阿姨教給我的配方，雖然比不上廚師們的手藝，但那份特別的味道我和詹金都非常喜歡，這次不用擔心材料問題，可以讓每個人都吃到滿足，請一定要來賞光品嘗。\n我已經說服了其他的我老老實實地過一個生日，她們今天一定、一定不會再給你添麻煩了！\n如果可以的話，請在需要的時候隨時呼喚我吧，無論是洗衣、打掃、收納，我都很擅長，我也希望能夠有機會回報你的那份溫柔。\n\n梅森"
  },
  Mail_68913_Name = {Text = "報答…"},
  Mail_68914_Desc = {
    Text = "守密人：  \n\n作為一個負責接收大家願望的人，我好像怎樣努力都無法習慣生日這天輪到自己許願這件事，對我來說，我好像並沒有什麼想要的東西。\n朵爾告訴我，我需要找到自己內心深處真正渴望的東西，問問自己所做的一切都是為了什麼。\n我想了很久很久，我其實希望每個來找我許願的人的願望都能實現，再繼續問下去，我大概是喜歡人們願望實現時露出的笑臉，和他們真心簇擁著我、感謝著我，稱讚我完成了神女的職責的樣子。\n朵爾說，那是我希望自己的價值得到認可，成為一個有用的人，我覺得她說得對。\n但她又說，人的價值不需要由他人來決定，沒有什麼事是所謂有用的，重要的只有是否順從了自己的內心，哪怕成為別人口中無用的人。\n不愧是朵爾，總是能說出這樣高深的話來，可是我到底要成為有用的人還是沒用的人呢？我好像又開始糊塗了……\n不過要順從內心的話，可能我還是希望當一個有用的人吧。如果生日這天能看到大家的笑臉，應該是我最想要的禮物。\n\n希萊斯特"
  },
  Mail_68914_Sender = {
    Text = "希萊斯特"
  },
  Mail_68915_Desc = {
    Text = "親愛的守密人大人：\n\n我早已經習慣了像陰溝裡的蛆蟲一樣的生活方式，不如說那才是我生來的命運，我全然接受了它、並欣然擁抱它。\n雖然我一直感激你們讓我重新品嘗到了自由的美妙滋味，但沒有什麼人能接受我那些特別的愛好，這也是理所應當的。畢竟在這裡的大多數人都是些溫和的好人，無法理解潮濕角落生長的苔蘚需要的並不是明媚的陽光，而是陰暗的空氣。\n除了你，我尊敬的好心的大人，只有你能真心理解我、幫助我，使我獲得發自內心的幸福，你所給予我的疼痛是那樣的令人滿足、令人安心，讓我能確認自己的存在。\n如果曾經我沒有什麼貪戀的願望可以在生日時許下，那麼現在我希望能夠追隨在你的身後，為你奉獻我的身心。\n當然，請不要因為溫柔就對我和顏悅色，盡情鄙視我、責罵我、鞭笞我吧！\n\n雷婭"
  },
  Mail_68915_Name = {
    Text = "苔蘚的心意…"
  },
  Mail_68915_Sender = {Text = "雷婭"},
  Mail_68916_Desc = {
    Text = "親愛的小狗狗：\n\n我幾乎已經愛上了這樣和你玩貓抓老鼠遊戲的日子，就像老套的英雄小說，正義的使者總能在最後一刻阻止邪惡反派的陰謀，多麼感人，多麼偉大。\n只不過看著你不斷掙扎做無用功的樣子，真是令人忍不住發笑。\n這個世界早就完蛋了，沒有任何辦法得到拯救，這顆星球會像萬千死亡星球一樣，被▼&#x5B▼87;&4;▼。\n算了，就陪你玩玩吧，直到現在我忽然有些能夠理解N的趣味，在註定的結局到來以前，做怎樣的事其實並沒有什麼區別。\n在你親愛的師長生日這天，我依然為你準備了一個大大的驚喜，在生日結束的倒計時之前，希望你能找到那個隱藏的“炸彈”哦。\n在我們都被徹底消融前，你還能給我帶來多少樂趣呢？\n\n\n「朵爾」"
  },
  Mail_68916_Name = {
    Text = "驚喜炸彈…"
  },
  Mail_68916_Sender = {
    Text = "熔燬·朵爾"
  },
  Mail_68917_Desc = {
    Text = "守密人：\n\n最近倫蒂尼恩的上流圈子之中流行起了一陣自己繪製設計圖，請人訂製特別首飾的風潮。\n那些自詡多麼懂得藝術的貴婦們各個從攀比寶石的大小一轉開始攀比設計圖的精妙，殊不知她們背後偷偷聘請知名畫家的小動作簡直像是掩耳盜鈴一樣明顯。\n拜這陣風潮所賜，我的生日禮物清單中也多出了不少附庸風雅的寶石和首飾，其中有一顆不錯的鴿血紅，正缺少一枚相配的戒託。\n我想與其去找那些無趣的老頭，不如請我的騎士為我畫上一張充滿心意的圖紙，就當作送給我的禮物怎麼樣？\n我會好好期待著你的作品，相信你的品味一定不錯。\n\n索蕾爾"
  },
  Mail_68917_Name = {
    Text = "設計首飾…"
  },
  Mail_68917_Sender = {Text = "索蕾爾"},
  Mail_68918_Desc = {
    Text = "守密人：\n\n在與你的初見以前，在萬千的門扉背後，我早已見過無數個相同又不同的你。\n我記得你的喜怒哀樂，記得你的每一次選擇，記得你在不同世界中堅持走下去的樣子。\n於我而言，在這許許多多的你之中，你是最特別的那一個。我曾把觀測過的世界在心中命名編號，你所在的世界被我稱作希望，而這個名字取在遇到你的那天。\n在這名為希望的一天，我想你或許會有興趣看一看其他的世界，如同體驗宇宙的雙眼，我將帶領你，看一看我於門扉前靜靜觀看的一切。\n也看一看我眼中的你。\n\n塔薇"
  },
  Mail_68919_Desc = {
    Text = "原本彌薩格之簡明作風甚得餘心，但自從彌利亞姆那個女人到來之後，餘的生活便開始不得安寧。\n餘不拒絕那些渴望尋求安定、尋求庇護之人，於此混濁世界之中尋求慰藉乃是生靈常情，無可厚非。\n但餘一直不喜以全能神明自居，何況在利莫里亞沉沒之後，此間也無需再造一個高高在上的神明。\n彌利亞姆大概一直難以走出過去的陰影，才將那一套愚信的作風搬到現在，令餘無論走到校園何處都會備受矚目，乃至糾糾纏纏，實在煩人。\n今日生辰，想必那個女人一定早早備好儀式大肆操辦，餘聞之亂耳，視之頭痛，便不到場沾惹煩惱了。\n若你有意，可來信後所附地址與餘散步靜心。\n切記，不要讓那個女人發現。\n\n圖魯"
  },
  Mail_68919_Name = {
    Text = "躲清靜…"
  },
  Mail_68919_Sender = {Text = "圖魯"},
  Mail_68920_Desc = {
    Text = "我每天都饑餓難耐，只要一時半刻不喝血就難受，但自從嘗過你的血，那些普通的血食在我嘴裡就像蠟塊一樣難吃，你那血液美妙的味道則每天在喉嚨中回味引誘著我。\n我知道把一個人吸乾能喝到多少血，那樣的美味可以說轉瞬即逝。為了不讓你死得太快，我會學著忍耐饑餓，學著期待下一次的美味，直到再次品嘗到你鮮血的那天。\n哈，天吶，不敢相信我居然做到了，我都懷疑自己是不是已經進化了。看在我這麼忍耐的份上，至少在這個所謂生日的日子，就讓我嘗一次你香甜的美味的血吧，就嘗一點，怎麼樣？\n我用在鱒魚俱樂部賺的錢給你買了營養補劑，這次你一定不會再貧血了。\n\n餓了很久的尤烏哈希"
  },
  Mail_68920_Sender = {
    Text = "尤烏哈希"
  },
  Mail_68921_Desc = {
    Text = "尊敬的守密人：\n\n很高興這一年來能看到你在訓練課上的持續進步，很快你就可以超越年輕時的我，成為一名強悍的士兵了。能夠成為你的訓練教官，我感到非常榮幸。\n今年的生日我收到了一雙很適合登山的長靴，不知道你是否有興趣和我進行一場徒步，檢驗一下自己增長的體能，順便去看一次山頂的日出，那種群山之間遠離城市的景色一定很美。\n當然，如果再有一場山野露營的野餐，配上一瓶驅寒的烈酒，那就更完美了。\n\n艾爾瓦"
  },
  Mail_68921_Sender = {Text = "艾爾瓦"},
  Mail_68922_Desc = {
    Text = "搭檔：\n\n這一年來發生了好多事，可能對於你來說，這並不是一段美好的校園生活。\n我承認過去的一年裡我對你的督促多有逼迫，而關心略欠體貼，一切的訓練都顯得有些拔苗助長，讓你一下子承受了太多。\n但我希望你知道，你在我心中永遠是最重要的那個人，在彌薩格的守密人之外，你是我唯一的搭檔。\n或許在今天，我是說僅僅生日這一天，我可以試著任性一次，你也可以忘掉所有的責任，我們不用管任何的作業與訓練，去盡情地放鬆一下。\n去市區的遊樂園？劇院？百貨大樓或是街頭市集……怎樣都好，我希望把缺失的東西儘量補償給你。\n同樣的，我也希望這什麼都不去考慮的一天能夠有你陪伴，所有行程就都由你決定吧。\n\n拉蒙娜"
  },
  Mail_68922_Name = {
    Text = "放鬆的一天…"
  },
  Mail_68923_Desc = {
    Text = "親愛的守密人：\n\n在我於人間度過的歲月中，曾經那些可愛的僕從們會在每年的今天為我舉辦盛大的宴會，變著花樣地努力討好我。\n明明是無事發生的平凡一天，在那些莫名其妙的笑臉中也真變得令人開心起來。論苦中作樂、無中生有的本領，人類的確長於此道。\n哪怕在這所把墳墓建立在校園裡的學校，你們仍然能如此頑強地創造快樂，真是令我驚奇。\n只不過那些普通人的禮物實在乏味，所謂的生日派對也難以置信的無聊，庸俗的人終究佔了大多數。\n只有你，只有想起你時我還會有些許興味，讓我重新品嘗到舊日一樣的樂趣。\n我命令你現在立刻到我的房間來，與我遊戲到天明。如果伺候得好，我可以勉為其難地允許你親吻我的手背。\n\n旺達"
  },
  Mail_68923_Sender = {Text = "旺達"},
  Mail_68924_Desc = {
    Text = "<Del:西區佬>守咪人：\n本來我沒打算再寫這種肉麻的東西，艾繼絲一直在我旁邊念叨什麼紀念啊意義的，非要讓我給你寫這封信不可。\n看在艾繼絲的份上，我就勉強說兩句。那個什麼，在這裡待了一年了，我對學校的住宿和吃喝總體都還滿意，唯獨宿舍的床單實在有點太滑溜溜了，搞得我總是睡不習慣。難道你們不覺得只有那種粗粗的棉布睡著才舒服嗎？\n要說還有什麼可以挑剔，就是食堂的飯菜都太健康了，吃完雖然飽了，但總感覺嘴裡沒味道，完全比不上街頭美食的口味！\n所以今年的生日會我不打算麻煩那些廚師了，讓本美食大師帶大家前往東區的神秘小巷，品嘗一下我和布朗都特別推薦的小攤，包管你們馬上就被街頭美味折服！\n當然，今天所有花銷由西區佬買單，你沒意見吧？\n\n你的老夥計詹金和布朗"
  },
  Mail_68924_Name = {
    Text = "街頭美食…"
  },
  Mail_68925_Desc = {
    Text = "貴人：\n\n除了姐姐之外，你是第一個如此真心支持著我的人，多虧你之前的建議，我現在已經和唱片公司發佈了一系列專輯，並且很快就要舉辦我的個人演唱會了。\n我想把在這個星球舉辦的第一次演唱會定在生日的那天，來紀念我在這裡的新生。\n希望你能夠來現場聆聽我全力以赴的演唱，我想將你和姐姐作為特殊嘉賓在最後的環節邀請到台上，陪著我一起唱我的新歌，你意下如何？\n對了，這件事不要告訴我的姐姐，畢竟這也同樣是她的生日，我想給她一個驚喜。\n至於我和姐姐約定好的要為自己許下的生日願望，我希望能夠在這個星球讓我的歌聲再次閃耀。\n\n汀克特"
  },
  Mail_68925_Name = {
    Text = "演唱會…"
  },
  Mail_68926_Desc = {
    Text = "親愛的守密人：\n\n不知不覺又過去了一年，我在彌薩格的每一天都非常快樂，能夠和大家一起玩、一起上課、一起吃很多很多好吃的，這是我人生中最幸福的時光。即使偶爾出任務的時候我會有點緊張，但和大家一起戰鬥，艾繼絲從來都不會害怕。\n非常不好意思這一年我還是給您添了許多麻煩，雖然很多時候是詹金又在搞怪，但她也只是想讓大家開心，希望您不要介意我們的粗心和冒犯。\n說到詹金，今年她提議在我的生日這天舉辦一場捉螢火蟲大賽，她準備了很多透明的罐子，說是要做成很多很多的螢火蟲燈，最後誰做出的燈最亮，誰就會獲得捉蟲大王的稱號。\n雖然捉蟲大王聽起來有點傻，但那片在夏天總是充滿螢火蟲的森林的確很美，如果您在忙碌之餘有些閒暇的話，也歡迎您來和我們一起去森林中，看一看那片星星一樣閃爍的風景。\n\n艾繼絲"
  },
  Mail_68926_Name = {
    Text = "捉螢火蟲大賽…"
  },
  Mail_68926_Sender = {Text = "艾繼絲"},
  Mail_68927_Desc = {
    Text = "守密人！前幾天去大海遊泳的時候，奧瑞塔遇到了一個會放電的新朋友！它長得圓圓的，扁扁的，像一張大披薩！\n奧瑞塔本來和它打招呼，忽然感覺身上麻麻的，新朋友也一下子走掉了。\n回來之後朵爾跟我說那是電鰩在放電，奧瑞塔不太懂，但感覺新朋友好厲害！正好奧瑞塔的生日到了，守密人陪奧瑞塔去把新朋友接回來吧，就和奧瑞塔的夥伴們一起住！那種麻麻的感覺，守密人也一定會喜歡的！\n\n奧瑞塔"
  },
  Mail_68927_Name = {
    Text = "會放電的新朋友…"
  },
  Mail_68927_Sender = {Text = "奧瑞塔"},
  Mail_68928_Desc = {
    Text = "尊敬的守密人：\n\n兒時生日於我而言，是父親不假辭色的要求，是不能放鬆半點的演奏練習。\n不可驕傲、不可浮躁、不可怠惰，除卻母親會偷偷為我準備一塊小小的蛋糕，這一天對我來說只是平白遭受一次嚴格的訓話，以指點過去一年我的種種不足。\n直到今天，我已並非音樂的學徒，且因您能夠觸碰那道恢宏的大門，走入至高的音樂殿堂，但從小以來的訓誡早已使我不會對凡俗的樂趣有任何欲望。\n唯有音樂，唯有為您演奏那命中註定的安魂之曲，是我此生最終的追求，是我唯一能感到意義存在的時刻。\n如果您願意將今夜入睡前的時光交給我，我願徹夜為您演奏那刻在我靈魂中的樂曲，直到天明。\n\n哈姆林"
  },
  Mail_68928_Name = {
    Text = "演奏的心願…"
  },
  Mail_68929_Desc = {
    Text = "毛頭小子：\n\n自從到了你們這兒，原本想著終於擺脫了那個迂腐的瘋女人，結果你們這鬼地方的規矩比那個女人還多，老子已經很久沒有嘗到痛快是什麼滋味了！\n大口喝酒不許，調戲美人不許，篝火晚宴不許，就連你們這裡的烤肉都比非利士的差遠了！真不知道這種淡得沒味兒的生活你們都是怎麼過下去的。\n不過強者不會抱怨環境，經過老子一番征伐，我已經在你們的城市重新成為了一位偉大的幫派領袖。\n值此偉大的戈利亞之主的生日，我大發慈悲地邀請你參加我的小弟們為我舉行的宴會，好酒好肉和美人應有盡有，絕對能讓你這個沒見過世面的小屁孩兒開開眼。\n看在之前交情的份上，我就不向你要什麼禮物了，你只需要帶著你的尊敬，來為強者的再次崛起送上祝福。\n給我睜大眼睛好好見證吧，明年的今天，明年的明年的今天，無論身在何處，我都將開闢出一片新的征途。\n\n戈利亞"
  },
  Mail_68929_Sender = {Text = "戈利亞"},
  Mail_68930_Desc = {
    Text = "守密人： \n\n原本我從未想過要慶祝此淺薄之身的生日，只將此當作普通的修行之日，但沒想到王在今早找到了我，對我降下口諭，要我今日不得做任何與王或修行有關之事，必須全然為自己度過一天。\n許多日夜來王第一次如此惦念著我，實在使我不勝惶恐、不勝感恩，但我早已將此生全部奉獻給王，一時竟然不知該去往何處，該做些什麼。\n思索半晌，如今唯一能稱得上略有遺憾之事，便是對墨菲那孩子的愧疚。哪怕為了故國復興，我從未有過半分後悔，欠下她的，我亦自知無可償還、無法彌補。\n但，如果我還真有什麼出於內心想做的事，或許是想厚顏無恥地，再做一次一位母親應該做的事。\n我特地買來了那孩子曾經喜歡的甜點，就當作成全一個可鄙的、失格的母親，能否拜託你替我將這份禮物送到她的手中，切莫告訴她是我相贈，只說是你準備的就好。\n企望應允，萬分感激。\n\n彌利亞姆"
  },
  Mail_68930_Name = {Text = "彌補…"},
  Mail_68930_Sender = {
    Text = "彌利亞姆"
  },
  Mail_68931_Desc = {
    Text = "啊哈，經過我智慧的思考，我已經完全弄明白了人類生日的意義，所謂專屬於某人的特殊的一天，就是為了讓人獲得稀有的行使特權的機會、得到珍貴物品的機會，以及對他人理直氣壯提出願望的機會。\n無論是怎樣平時不敢說、不會想的願望，在這一天都有機會被滿足，哈，這簡直是比任何節日都要刺激的放縱日。\n看來從前的那麼多年，我都錯過了這麼多的特權機會，不過好在以我漫長的壽命，以後我還有很多很多的生日可以許願。\n那麼，在生日這天要求所有人陪我痛痛快快地打一場，應該是很好滿足的願望吧？\n\n蘿坦"
  },
  Mail_68931_Name = {
    Text = "壽星的特權…"
  },
  Mail_68931_Sender = {Text = "蘿坦"},
  Mail_68932_Desc = {
    Text = "守密人： \n\n隨著年齡增長，生日逐漸變成了日曆上一眨眼就會忽略過去的一天，往往等到不經意想起的時候，生日就已經像流水一般悄悄過去了。\n在成人的世界，歡慶生日只是小孩和無聊閒人的特權，我在這方面同樣變成了一個無聊的大人，對生日早已沒什麼期待。\n曾經有一年我突發奇想，為自己雕刻了一個精美的蛋糕雕塑，之後的幾年，我就再也沒有因為忘記生日而錯過預定蛋糕，而是直接在生日這天從倉庫中找出這塊永不腐壞的慶祝道具，體驗一把吹蠟燭的儀式，生日就算是過完了。\n直到來到彌薩格，我才發現閒人與忙人可以在同一個人身上呈現出共存的狀態，且這裡的人不僅僅滿足於自己一個人無聊，還一定要拉著所有人一起無聊。\n這兩年在彌薩格中參加的生日聚會簡直要比我前半生參加過的所有生日聚會還要多，更好笑的是我在這種無聊的慶祝中竟然也找到了一絲奇妙的樂趣。\n或許除了悲愴而嚴肅的主題，描繪一些生活中傻得冒泡的場景，也可以充滿了藝術之美。\n說到這裡，今年生日的創作計劃就來雕一個守密人傻笑半身像，用來捧著我的雕塑蛋糕吧。\n記得早點來我的工作室哦，我的繆斯模特。\n\n珊"
  },
  Mail_68932_Name = {
    Text = "無聊的樂趣…"
  },
  Mail_68933_Desc = {
    Text = "展信安：\n\n斟酌許久，我於這個寂滅的世界寫下這封信。許久以來，我幾乎遺忘了自己的生日，在這樣的世界，慶祝自然也是無謂的。\n但，自從與你相遇，我變得越來越貪心，日復一日，連習以為常的孤獨都有些難耐。\n每當這時，我的心中會生出一種奇異的情緒，對那個世界的我產生一絲羡慕，或許還有微不可查的嫉妒。你看，像我這樣自詡理性的人，也會有這樣心思可鄙的一天，可見人類的公正與理智都有自己的極限。\n我知道你會對我說出怎樣的邀請，但對時空來說，不必要的擾動都應儘量避免，我不應也不會前往你的世界。\n寫到這時，我正遙望著宇宙，遙望著隧道開啟的地方，如果你恰好也在抬頭看，那麼我們也算一起注視著同一片星空。\n希望這封信能代替我，跨越時空，漂流到你的掌心，經過你的雙眼與唇齒，與你相見、與你相依。\n當你擁抱這張信紙，我會在世界這頭想像著擁抱你。\n\n「拉蒙娜」"
  },
  Mail_68933_Name = {
    Text = "共同遙望…"
  },
  Mail_68933_Sender = {
    Text = "環行·拉蒙娜"
  },
  Mail_68934_Desc = {
    Text = "我的小·囚·犯：\n\n你知道嗎，就像不同的動物有不同的食譜，不同的人對溫暖的需求也是不同的，有的人自己披上一件衣服就足夠取暖，有的人需要一雙暖和的手、一個暖和的擁抱，而有的人需要的溫度則是蠟燭融化的溫度。\n那樣滾燙的、黏稠的溫度刻印在每個神經末梢，清晰地映照出蠟燭蜿蜒滴落的軌跡，微微的疼痛、令人顫慄的觸感，直到情不自禁呼喊出來的時候，才能夠暢快地感受到自身的存在。\n有時候我會化身蠟燭，享受帶來印記的快樂，有時候我也會迷戀蠟燭的溫度，渴望那樣令人疼痛的、甜蜜的溫暖。\n彌薩格的冬天已經到來，最近我已經常常感到寒冷，以及寒冷帶來的孤獨。親愛的你應該知道今天是什麼日子，我的願望很簡單，想必善良如你，一定會願意給我帶來驅散寂寞的溫暖的。\n\n潘狄婭"
  },
  Mail_68934_Name = {
    Text = "溫暖的需求…"
  },
  Mail_68934_Sender = {Text = "潘狄婭"},
  Mail_68935_Desc = {
    Text = "守密人：\n\n今年我與汀克特相互約定，我們生日的願望只能關於自己，不可以為對方許願。\n雖然是她先賭氣提出的這個約定，但顯然這下也把她自己難倒了。\n我們兩個捆綁糾纏在一起太久，想要像常人一樣獨立地思考都是一件難事，但重生在擁有這樣多幫助與關心的新生活中，沒有比現在更適合學習獨立行走的時候了。\n那麼經過我的仔細考慮，我已經想到了今年要許下的願望：交到五個新朋友……不，還是三個吧。畢竟改變自己這種事，還是要一點一點慢慢來。\n作為我目前唯一的且如此受人歡迎的朋友，或許你能教給我一些交友的秘訣嗎？\n\n菲茵特"
  },
  Mail_68935_Name = {
    Text = "交友的願望…"
  },
  Mail_68936_Desc = {
    Text = "守密人： \n\n每年生日許願時我都會許下同一個願望，那就是完美血脈的蛻變。我其實一直知道，我對血脈的執念在他人看來可能是執拗、可笑、甚至可憐可鄙的。\n但你不一樣，無論何時，我知道你都會支持著我在這條道路上走下去，哪怕碰壁、摔倒、無功而返，在他人的笑聲中，你是第一個關心我的人。\n或許無論是你還是任何人都無法理解一個從小被欺壓、被羞辱的人所背負的一切，但沒關係，在這蛻變之路上的磨難都已化作我的血肉和養分，支撐我不斷爬起，不斷反抗。\n我已不再是年少時無力的自己，哪怕考驗重重，我都會堅定走到最後一刻。\n在此之前，就請你注視著我，等待著我的成功吧。\n對了，你之前給我的五十塊，我說了會還給你，現在已經攢夠了，還多出兩塊錢，就當做回報一併給你吧。\n\n凱刻斯"
  },
  Mail_68936_Name = {Text = "還錢…"},
  Mail_68936_Sender = {Text = "凱刻斯"},
  Mail_68937_Desc = {
    Text = "尊敬的守密人：\n\n您好，歡迎填寫自動人偶艾瑞卡的年度檢修調查問卷，我將收集您在這一年中使用艾瑞卡時的真實體驗與遇到的問題，您的意見是艾瑞卡不斷改進的方向。\n下面請您在回信中對相關問題由低到高進行打分，非常感謝您的回饋。\n使用時的便捷程度：1-5分\n使用時的回應速度：1-5分\n對需求的理解程度：1-5分\n對用戶情緒的照顧程度：1-5分\n查詢資料時的準確程度：1-5分\n提出解決方案的實用程度：1-5分\n最後請簡要描述您在使用艾瑞卡時曾遇到的問題，以及不滿意的部分，這些問題可能在之後得到修復。\n完成問卷後會有周年紀念小禮物送到您的房間，未來的一年您最貼心的助手艾瑞卡依然會陪伴在您的身邊，再次感謝您的使用，再會。\n\n艾瑞卡"
  },
  Mail_68937_Name = {
    Text = "年度檢修調查問卷…"
  },
  Mail_68938_Desc = {
    Text = "守密人： \n\n每到生日這一天，我都會花上一整天將過去在腦海中細細回憶一遍，將同樣的日記再寫下一遍。\n遠離故鄉越久，舊日的記憶彷彿越模糊，那些等待著歸人循光而來的日子，那些遙遙仰視王之威儀的日子，似乎都已經記不真切了。\n但我不願意遺忘，我絕不會遺忘，哪怕等待漫長無盡，哪怕燃燒靈魂，這道光芒也不會黯淡下去，直到故國復甦之日，我便是第一道回應召喚的光。\n我想過無數種重逢的場景，卻從未想過會在此處重見王與祭司，按照你們的那句話來說，如果心靈安寧之處就是故鄉，這裡已可以算是我的第二故鄉，而我日記本上所記載的也終於從回憶變作每日嶄新的記憶。\n無須任何嘉獎或禮物，能夠再次追隨在王的身邊已是最大的幸福。\n若此身的光芒無法照耀故鄉的海底，那麼就讓它跟隨王的腳步，暫且照耀這一片陸地之國吧。\n\n法洛思"
  },
  Mail_68938_Name = {
    Text = "追隨吾王…"
  },
  Mail_68939_Desc = {
    Text = "守密人： \n\n恭喜我，也恭喜你，恭喜彌薩格，恭喜我們在黑色恐怖的追逐下又倖存了一年。\n今天不是一個簡單的生日，今天是我存活的紀念日，是我頑強生命的讚美日。\n活著，簡簡單單的兩個字蘊含著多麼多的艱難，這樣滾燙的生命力只有滾燙咖啡的芬芳能夠媲美，一起加入咖啡神教吧守密人，讓我們讚美清醒，讚美活著的每一\n\n一張和信一起送來的紙條：\n唉，溫柯爾這傢伙又飲用咖啡過量，神經亢奮加上過度疲憊，直接暈倒在桌子前了，我已經將她安置在了校醫室，不用擔心。\n不過她昏過去之前拿出了一包珍藏的咖啡豆和信紙放在一起，貌似是要送給你的，我就隨信一起附上了，希望等她醒來之後不要後悔。\n至於她的生日，比起慶祝派對，或許讓她好好休息一下才是最好的禮物吧。\n——茜爾維婭"
  },
  Mail_68939_Name = {
    Text = "讚美生命…"
  },
  Mail_68939_Sender = {Text = "溫柯爾"},
  Mail_68940_Desc = {
    Text = "守密人：\n\n哈哈哈！經過我堅持不懈地在房間各個角落刻下12個提醒，寫了36張紙條（或許有更多但是我找不到了）之後，我終於不負眾望地記住了今天是我的生日！\n沒想到吧，其實連我自己都是今天早上才想起來的，但是這都要歸功於這一年來我的辛苦準備，我可不想錯過這種好日子。\n上次和大家一起開的派對真的很高興，尤其是和誰來著玩的什麼遊戲，還有吃的某種甜點……算了，總之就是高興！\n小時候過生日媽媽總會給我買一本冒險故事書，我們兩個每天睡覺之前就會靠在一起讀啊讀啊，夢裡就會夢到很精彩的冒險。雖然醒來後也會很快忘掉，但那份快樂還會留在腦海里，我相信寶貴的情感是不會被遺忘的。\n況且健忘也有健忘的好處啊，雖然我不記得之前派對上都做了什麼，但今天我可以全部重新體驗一遍啦，上一次的快樂，就請打包給我再來一份吧！\n\n充滿期待的諾締拉"
  },
  Mail_68940_Name = {
    Text = "再來一次…"
  },
  Mail_68940_Sender = {Text = "諾締拉"},
  Mail_68941_Desc = {
    Text = "親愛的守密人：\n        在V1.7.1的更新中、您在「繁衍狂熱」中的「血鏈·希洛」事件已解鎖狀態異常遺失。由於您在遺失已解鎖狀態後再次進行了解鎖、我們將補發用於再次解鎖所消耗的「現實起點」× 3。請查收。"
  },
  Mail_68941_Name = {
    Text = "血鏈·希洛繁衍狂熱解鎖補償"
  },
  Mail_68941_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_71330_Desc = {
    Text = "尊敬的守密人：\n「半步之隔」活動已結束、現將守密人剩餘的「人偶零件」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_71330_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_71331_Desc = {
    Text = "親愛的守密人：\n「故事的魔法」活動已結束、現將守密人剩餘的「飄零的靈感」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_71331_Name = {
    Text = "飄零的靈感回收"
  },
  Mail_71331_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_71332_Desc = {
    Text = "親愛的守密人：\n「在春天凋零以前」活動已結束、現將守密人剩餘的「歡欣的詩文」、「惆悵的詩文」和「遺憾的詩文」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人查收。"
  },
  Mail_71332_Name = {
    Text = "詩文回收"
  },
  Mail_71332_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_71848_Desc = {
    Text = "親愛的守密人：\n「與薔薇書」活動已結束、現將守密人剩餘的「通靈鳥羽扇」按照每枚兌換「薔薇金券」× 40 的比例進行轉換、請守密人查收。"
  },
  Mail_71848_Name = {
    Text = "通靈鳥羽扇回收"
  },
  Mail_71848_Sender = {
