  Mail_74020_Desc = {
    Text = "親愛的守密人：\n「群星正位·復刻」活動已結束、現將守密人剩餘的「無識之胚」、「無欲之胚」和「無厭之胚」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人查收。"
