  },
  Mail_74347_Desc = {
    Text = "親愛的守密人：\n「靈魂的牧人·復刻」活動已結束、現將守密人剩餘的「義賣券」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_74347_Name = {
