  },
  Mail_74347_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_74841_Desc = {
    Text = "搭檔：\n\n去年的今天，我還遠遠沒有想到時隔一年之後，我便只能將這封信投入一個空空的郵箱。\n那時你剛剛進入彌薩格不久，與一個頑劣又懶惰的學生沒什麼兩樣，即使現在想來，我那時常常對你過於嚴格，也過於在意自己那張理性又矜持的面具了。\n其實去年的這一天我買了一束花，我站在圖書館的門前，看了那束躺在紅色絲帶與墨綠色的包裝紙裡的玫瑰很久，最終把它插在了我的床頭。\n一年時間花朵早已枯萎，只有那條亮紅的緞帶被我係在K-0617號銀鑰上，仍舊豔麗如新。\n我多麼、多麼想再買一束玫瑰，然而如今它們除了再次在我的床頭凋零，已經沒有了其他的歸宿。\n習慣了將所有事情都詳細列出解決方案，後悔的滋味對於我來說，是這樣新奇又苦澀。\n但我一直懷抱著一種近乎盲目的信任，認為你的靈魂始終沒有離去，你或許暫時在宇宙的某處遨遊，但最終仍會回到這裡，回到我的身邊。\n我並不覺得這是癡人說夢的幻想，只因我每每來到黑池之中遙望你的面龐時，內心中仍能感到與你連結、共鳴的那絲暖和的溫度。\n我會始終相信並期冀著重逢的那一天，在我們的手重新相牽的那一刻，我會將今日欠下的玫瑰親手交到你的手中。\n\n拉蒙娜"
  },
  Mail_76410_Desc = {
    Text = "親愛的守密人：\n「雨鎮幽影」活動已結束、現將守密人剩餘的「蒼白野獸頭骨」、「幽影野獸頭骨」和「殷紅野獸頭骨」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
