  Mail_78792_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_79390_Desc = {
    Text = "親愛的守密人：\n        感謝您對「忘卻前夜」的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調研問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。問卷截止時間3月17日9：00、請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_79390_Name = {
    Text = "版本體驗調研問卷V2.1.0"
  },
  Mail_79390_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_79646_Desc = {
    Text = "親愛的守密人：\n「埋於記憶之下」活動已結束、現將守密人剩餘的「診斷報告」按照每個兌換「薔薇金券」× 40 的比例進行轉換、請守密人記得查收。"
  },
  Mail_79646_Name = {
    Text = "埋於記憶之下貨幣回收"
  },
  Mail_79646_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_80091_Desc = {
    Text = "守密人：\n\n當你翻開這封信，就代表我在你心裡埋下的暗示已經生效。\n哈，不必擔心。這只是為了保證我的生日宴會順利進行，而施展的微不足道的催眠，不會對你產生什麼影響。\n接下來，你會發自內心產生想要逛街購物的衝動，順從它走到街上吧，從那琳琅的櫥窗裡挑選一件最和我心意的禮物，再送到我的手裡。\n我知道你此刻的疑惑，也認同它的合理性，但壽星總是有些特權的對不對？我之所以如此，只是怕你忘記了這特殊的日子。畢竟，你可是我心心念念的客人。\n最後，我會耐心等待你的來訪——別忘記禮物。\n\n克萊門汀"
  },
  Mail_80091_Name = {
    Text = "“親自”挑選的禮物"
  },
  Mail_80091_Sender = {
    Text = "克萊門汀"
  },
  Mail_81288_Desc = {
    Text = "親愛的守密人：\n        感謝您對「忘卻前夜」的支持和認可、為了讓守密人在彌薩格大學有更好的遊戲體驗、誠邀您填寫以下體驗調研問卷。為感謝您的配合、我們準備了「銀芯」× 200 作為獎勵、完成問卷即可領取。問卷截止時間4月14日9：00、請注意及時填寫。\n        <SurveyLink:【點擊前往填寫】>\n        我們會認真聽取每一位守密人的建議、您的反饋也一定會使彌薩格大學越來越好！\n        ——願銀鑰指引前路。"
  },
  Mail_81288_Name = {
    Text = "版本體驗調研問卷V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "彌薩格校務處"
  },
  Mail_81326_Desc = {
    Text = "恩人：\n\n今天對於我和波呂克斯來說，是一年之中唯一的節日。在教會中時，我們並不被允許過度關注自我的意義，我們全部的價值都只存在於侍奉持燈者這一永恆的事業上，在那樣的信仰面前，其他任何節日也都是無意義的虛妄。\n但每到了生日這一天，我和波呂克斯依然會偷偷地慶祝，我們會瞞著侍從為對方準備一份盡可能小的禮物，然後隱秘地期待著這一天的到來。\n生日的慶祝時刻往往在深夜——那是我們一天中僅有的自由時刻，波呂克斯靈巧的雙手和點子總能讓他的禮物勝過我的，有一次他甚至靠積攢掉落的羽毛編織了一朵盛開的花。\n其實我並不擅長準備驚喜，波呂克斯總說我平時的表情早已出賣了一切，而我所擁有的東西在您看來想必更加貧瘠無聊，不過今天我已經想到了一個絕佳的、與您分享喜悅的方式。\n當您在晚上聽到窗戶被敲響三下，請別害怕，推開窗，我將帶您去體驗雲層與夜風的觸感。\n\n卡斯托爾"
  },
  Mail_81326_Name = {Text = "夜遊…"},
  Mail_81326_Sender = {
    Text = "卡斯托爾"
  },
  Mail_84142_Desc = {
    Text = "守密人：  \n\n在匯合前，我寫下了這封信，正式邀請及向您介紹我的「生日航行」。\n本次航行的第一站，是泰晤士河。我們會登上貨船改造成的移動餐廳，一邊泛舟，一邊品嘗罐裝蜜漬鳳梨和朗姆酒。這是船員生日時才會特供的美味，希望您會喜歡。\n本次航行的第二站，是港口觀景臺。請您放心，我已經向熱氣球協會申請了觀測權限。當熱氣球飛上高空，俯瞰整個倫敦航道時，我們會共同切開蛋糕，作為慶祝。\n從前，航行條件有限，所謂的生日蛋糕只是木匠用橡木和焦糖製作的模型，因此我也不知道蛋糕的味道，這次能與您共同品味，我想除了食物的美好外，我還會收穫更多。\n第三站，或者，應該被稱為第三個環節，是訂製星圖。我在海圖上標注了自己出生時的天體位置，如果您不介意的話，我想將您的也標注進去，這樣獨一無二的航海星圖，將會是最值得珍藏的禮物。\n事實上，在寫下這封信時，我曾有過猶豫。這些行為無疑超出了尋常的界限，但今天是個特殊的日子，您對於我來說也是特殊之人，值得我為之打破常規。\n所以請您務必不要拒絕，並按時赴約。\n\n克珀珊特"
  },
  Mail_84142_Name = {
    Text = "「航行」邀請"
  },
  Mail_84355_Desc = {
    Text = "親愛的守密人：\n「於暴雨中搖曳」活動已結束、現將守密人剩餘的活動貨幣「信號旗」按照每個兌換「薔薇金券」× 40 的比例進行回收、請守密人記得查收。"
  },
  Mail_84355_Name = {
    Text = "信號旗回收"
  },
  Mail_84355_Sender = {
    Text = "彌薩格校委會"
  },
