  },
  Mail_94503_Desc = {
    Text = "我的明燈：\n\n自從我與卡斯托爾來到這裡，您對我們的照拂堪比賜予了我們新生，感謝您為我們精心準備的生日蛋糕，雖然把您在蛋糕上畫的兩隻小鳥認成了蝴蝶十分抱歉，但我們真的很喜歡這份禮物，這也是我們第一次收到來自他人的生日禮物。\n我們還從訶勒特院長那裡收到了學校贈送的賀卡，那枚白色的信封上粘貼了金色的華麗印章，裡面寫滿了美好的祝福，這真是一個溫暖的地方，我們的人生中從沒有像現在一樣幸福的時刻。\n請來與我和卡斯托爾一同慶祝生日吧，這是我們兒時堅持的儀式，作為我們的恩人，我們也為您準備了互換的禮物，是我用卡斯托爾掉落的羽毛編制的一頂頭冠。\n我將這粗陋的冠冕獻予您，以求聊表我們的崇敬之情，我願用我的餘生追隨您左右，踐行這所學校偉大的願景，消除那些真正的罪惡與黑暗。\n許久未曾做這些事，卡斯托爾還笑話我的手藝不如兒時，希望您不要嫌棄。\n\n波呂克斯"
  },
  Mail_94503_Name = {
    Text = "羽毛頭冠…"
  },
  Mail_94503_Sender = {
    Text = "波呂克斯"
  },
  Mail_95382_Desc = {
    Text = "可愛的小傢伙：\n\n小傢伙，今天是我降臨的那一天。\n不是作為不停燃燒的大火球，而是那個叫凱蒂古拉的女孩的生日。\n按照生前的習慣，這一天我們會開一個盛大的晚宴，肆意享用美酒和烤肉。\n當然，總有臭小子不會看氣氛地調侃我又老了一歲，所以我用拳頭問候了他們的腦殼。\n而如今，這個宴會新增了一個功能，供我們懷念曾經度過的時光。\n今年我打算再加一個活動，那就是——狩獵我們的小傢伙！\n知道麼，我已經迫不及待地想把你抓到我的宴會上，用你那害羞無措的可愛表情、半醉半醒的迷離眼神、自內而發的甘醇香氣來裝飾我今年的生日晚宴，這將會是我自出生以來，得到的最好的生日禮物！\n現在開始籌備逃跑計劃已經晚了，因為當你看到這封信件時……我·早·已·來·到·你·的·門·前。\n別害怕，小傢伙，如果一切正常，你只會在這裡聆聽最好的故事，品嘗最美味的食物。\n當然，被捕獲的小獸，發生點意外也很正常對吧。\n乖乖跟我走吧小傢伙，今晚你那美好的時光，註定要跟我一起度過。\n\n凱蒂古拉"
  },
  Mail_95382_Name = {
    Text = "時光的晚宴…"
  },
  Mail_95382_Sender = {
    Text = "凱蒂古拉"
  },
