  Mail_96012_Sender = {
    Text = "彌薩格校委會"
  },
  Mail_96323_Desc = {
    Text = "守密人閣下：\n\n活人慶祝生日，是為了在余命之中撿拾意義。而我不過是借這個夜晚將死亡的香氣烹煮得更加馥郁。\n那些不再掙扎、不再懷有執念的亡者，生前的一切污濁都被洗淨，他們的悔恨如同細鹽，在火候恰好之時融入血線之間，形成一種濕潤而溫順的芳香。他們的骨骼會發出低聲的裂響，皮膚滲出的油脂淡雅如薄荷，而靈魂深處的未竟之語，會在煨煮之中慢慢逸出，留下一絲細膩的甘甜。我早已開始幻想你化為沉靜之物的模樣——皮膚在爐火前收緊時的脆響、骨肉間蒸騰出的情感，你純淨靈魂逐漸被吞食的甜蜜口感……\n可你不同。\n你仍在發光，仍在跳動，卻擁有任何亡者都無法比擬的香氣，讓人心醉神迷。你是我願意等待的熟成，我甚至希望這場等待，能持續得比永恆更久。\n在這無數重複的年輪中，你的出現為我的生日賦予了意義。不再只是為了美妙的進食，更是為了你仍在躍動的生命。\n\n杜勒賽因"
  },
